window.OMD_CONTENT = {"version":"1.1.0-integrated","total":1009,"items":[{"id":"fact-001","category":"Unnützes Wissen","title":"Venustag","text":"Auf der Venus dauert eine vollständige Drehung um die eigene Achse länger als ein Umlauf um die Sonne.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/venus/venus-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-002","category":"Unnützes Wissen","title":"Venus rückwärts","text":"Die Venus dreht sich im Vergleich zu den meisten Planeten in entgegengesetzter Richtung.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/venus/venus-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-003","category":"Unnützes Wissen","title":"Heißeste Venus","text":"Die Venus ist trotz größerer Sonnenentfernung heißer als Merkur. Ihre dichte Atmosphäre erzeugt einen extremen Treibhauseffekt.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/venus/venus-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-004","category":"Unnützes Wissen","title":"Venusdruck","text":"Der Druck an der Venusoberfläche beträgt ungefähr das 93-Fache des irdischen Luftdrucks auf Meereshöhe.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/venus/venus-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-005","category":"Unnützes Wissen","title":"Mondrückseite","text":"Menschen sahen die Mondrückseite erstmals 1959 auf Aufnahmen der sowjetischen Sonde Luna 3.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/moon/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-006","category":"Unnützes Wissen","title":"Gebundener Mond","text":"Der Mond rotiert ungefähr so schnell, wie er die Erde umrundet. Deshalb zeigt er uns fast immer dieselbe Seite.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/moon/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-007","category":"Unnützes Wissen","title":"Lebendes Licht","text":"Biolumineszenz ist Licht, das Lebewesen durch chemische Reaktionen selbst erzeugen.","source":"Verifizierte Referenz","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/bioluminescence/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-008","category":"Unnützes Wissen","title":"Leuchtende Tiefsee","text":"Zwischen etwa 200 und 1.000 Metern Meerestiefe sind laut NOAA rund 80 Prozent der dort lebenden Tiere biolumineszent.","source":"Verifizierte Referenz","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/bioluminescence/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-009","category":"Unnützes Wissen","title":"Blaues Tiefseelicht","text":"Biolumineszenz im Meer ist meistens blau, weil blaues Licht im Wasser besonders weit reicht.","source":"Verifizierte Referenz","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/bioluminescence/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-010","category":"Unnützes Wissen","title":"Herz beim Niesen","text":"Das menschliche Herz hört beim Niesen nicht einfach auf zu schlagen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-011","category":"Unnützes Wissen","title":"Gelenkknacken","text":"Knackgeräusche in Gelenken können unter anderem durch Gasvorgänge und Bewegungen im Gelenk entstehen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-012","category":"Unnützes Wissen","title":"Stärkster Muskel","text":"Es gibt keinen eindeutig stärksten Muskel, weil Stärke auf verschiedene Arten gemessen werden kann.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-013","category":"Unnützes Wissen","title":"Graue Haare","text":"Graues Haar enthält weniger Pigment; weißes Haar praktisch keines mehr.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-014","category":"Unnützes Wissen","title":"Zombie-Ameisen","text":"Bestimmte Ophiocordyceps-Pilze infizieren Ameisen und verändern deren Verhalten.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-015","category":"Unnützes Wissen","title":"Kraken erkennen Menschen","text":"Oktopusse können lernen, einzelne Menschen voneinander zu unterscheiden.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-016","category":"Unnützes Wissen","title":"Zebras","text":"Zebras lassen sich nicht wie Pferde zuverlässig domestizieren.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-017","category":"Unnützes Wissen","title":"Kamelhöcker","text":"Kamele speichern im Höcker vor allem Fett, nicht Wasser.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-018","category":"Unnützes Wissen","title":"Eisbärenfell","text":"Eisbärenhaare sind weitgehend transparent beziehungsweise farblos und wirken im Verbund weiß.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-019","category":"Unnützes Wissen","title":"Gänse-V","text":"Die V-Formation kann nachfolgenden Gänsen aerodynamische Vorteile verschaffen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-020","category":"Unnützes Wissen","title":"Fischregen","text":"Kleine Tiere können durch starke Wetterereignisse verfrachtet werden und später an anderer Stelle zu Boden fallen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-021","category":"Unnützes Wissen","title":"Feuertornado","text":"Unter extremen Brandbedingungen können rotierende Feuersäulen beziehungsweise Feuertornados entstehen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-022","category":"Unnützes Wissen","title":"Strohhaus","text":"Aus trockenen, fest gepressten Strohballen lassen sich dauerhafte Gebäude errichten.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-023","category":"Unnützes Wissen","title":"Touchscreen","text":"Kapazitive Touchscreens erkennen Berührungen über Veränderungen eines elektrischen Feldes.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-024","category":"Unnützes Wissen","title":"Versteinertes Holz","text":"Bei versteinertem Holz wird organisches Material über lange Zeit durch Mineralien ersetzt.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-025","category":"Unnützes Wissen","title":"Sieben Meere","text":"Für den Ausdruck „die sieben Meere“ gibt es keine universell gültige Liste.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-026","category":"Unnützes Wissen","title":"Black-eyed peas","text":"Black-eyed peas sind botanisch Augenbohnen und keine Erbsen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-027","category":"Unnützes Wissen","title":"Grapefruit","text":"Der Name Grapefruit wird wahrscheinlich auf das traubenartige Wachstum der Früchte in Gruppen zurückgeführt.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-028","category":"Unnützes Wissen","title":"Kokosnuss","text":"Botanisch ist die Kokosnuss eine Steinfrucht und keine echte Nuss.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-029","category":"Unnützes Wissen","title":"Schokolade","text":"Schokolade schmilzt in der Hand, weil ihr Schmelzbereich unter der menschlichen Körpertemperatur liegt.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-030","category":"Unnützes Wissen","title":"Elementsymbole","text":"Einige Elementsymbole stammen aus älteren, oft lateinischen Namen und passen deshalb nicht zum heutigen Namen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-031","category":"Unnützes Wissen","title":"Kevlar","text":"Stephanie Kwolek ließ eine ungewöhnliche Polymerlösung trotz Skepsis weiter untersuchen. Daraus entwickelte sich Kevlar.","source":"Verifizierte Referenz","sourceUrl":"https://invention.si.edu/invention-stories/recognize-unusual","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-032","category":"Unnützes Wissen","title":"Scotchgard","text":"Eine versehentlich auf Stoffschuhe gelangte Chemikalie führte zur Entdeckung der wasserabweisenden Eigenschaften hinter Scotchgard.","source":"Verifizierte Referenz","sourceUrl":"https://invention.si.edu/invention-stories/recognize-unusual","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-033","category":"Unnützes Wissen","title":"Post-it","text":"Der Klebstoff hinter Post-it Notes wurde gerade wegen seiner ungewöhnlich schwachen Haftung nützlich.","source":"Verifizierte Referenz","sourceUrl":"https://invention.si.edu/invention-stories/recognize-unusual","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-034","category":"Unnützes Wissen","title":"Mikrowelle","text":"Der Mikrowellenherd entstand aus der Beobachtung einer unerwarteten Erwärmungswirkung bei Arbeiten mit Mikrowellentechnik.","source":"Verifizierte Referenz","sourceUrl":"https://invention.si.edu/invention-stories/recognize-unusual","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-035","category":"Unnützes Wissen","title":"45-Minuten-Krieg","text":"Der Anglo-Sansibar-Krieg von 1896 gilt mit ungefähr 45 Minuten als kürzester Krieg der Geschichte.","source":"Verifizierte Referenz","sourceUrl":"https://www.guinnessworldrecords.com/world-records/65353-shortest-war","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-036","category":"Unnützes Wissen","title":"Ältester Witz","text":"Der älteste von Guinness geführte aufgezeichnete Witz stammt ungefähr aus 1900 v. Chr. und handelt von einem Furz.","source":"Verifizierte Referenz","sourceUrl":"https://www.guinnessworldrecords.com/world-records/491582-oldest-joke","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-037","category":"Unnützes Wissen","title":"Tanzepidemie","text":"1518 ist in Straßburg eine Tanzepidemie historisch dokumentiert. Ihre genaue Ursache ist bis heute nicht abschließend geklärt.","source":"Verifizierte Referenz","sourceUrl":"https://www.history.com/articles/what-was-the-dancing-plague-of-1518","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-038","category":"Unnützes Wissen","title":"Alcatraz","text":"Frank Morris sowie John und Clarence Anglin flohen 1962 aus Alcatraz. Ihr endgültiges Schicksal ist ungeklärt.","source":"Verifizierte Referenz","sourceUrl":"https://www.fbi.gov/history/cases-and-criminals/alcatraz-escape","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-039","category":"Unnützes Wissen","title":"Alcatraz-Versuche","text":"Von 1934 bis 1963 versuchten 36 Männer in 14 Aktionen aus Alcatraz zu fliehen.","source":"Verifizierte Referenz","sourceUrl":"https://www.fbi.gov/history/cases-and-criminals/alcatraz-escape","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-040","category":"Unnützes Wissen","title":"Bienenparagraph","text":"Das deutsche BGB enthält eigene Vorschriften über ausgezogene Bienenschwärme.","source":"Verifizierte Referenz","sourceUrl":"https://www.gesetze-im-internet.de/bgb/__961.html","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-041","category":"Unnützes Wissen","title":"Schatzfund","text":"§ 984 BGB regelt einen Schatzfund grundsätzlich mit hälftigem Eigentum für Finder und Eigentümer der Sache, in der der Schatz verborgen war.","source":"Verifizierte Referenz","sourceUrl":"https://www.gesetze-im-internet.de/bgb/__984.html","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-042","category":"Unnützes Wissen","title":"Bananen","text":"Bananen gelten botanisch als Beeren; Erdbeeren dagegen nicht als echte Beeren.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-043","category":"Unnützes Wissen","title":"Ananas","text":"Eine Ananas entsteht aus vielen einzelnen Blüten, deren Früchte zusammenwachsen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-044","category":"Unnützes Wissen","title":"Bambus","text":"Bambus gehört botanisch zu den Gräsern.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-045","category":"Unnützes Wissen","title":"Pilze","text":"Pilze bilden ein eigenes Reich und sind keine Pflanzen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-046","category":"Unnützes Wissen","title":"Korallen","text":"Korallen bestehen aus Kolonien kleiner Tiere, den Polypen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-047","category":"Unnützes Wissen","title":"Drei Herzen","text":"Oktopusse besitzen drei Herzen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-048","category":"Unnützes Wissen","title":"Blaues Blut","text":"Viele Kopffüßer transportieren Sauerstoff mit kupferhaltigem Hämocyanin; ihr Blut wirkt dadurch blau.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-049","category":"Unnützes Wissen","title":"Seepferdchen","text":"Bei Seepferdchen trägt das Männchen die sich entwickelnden Eier in einer Bruttasche.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-050","category":"Unnützes Wissen","title":"Wombatwürfel","text":"Wombats sind für würfelförmigen Kot bekannt; die Form entsteht im letzten Darmabschnitt.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-051","category":"Unnützes Wissen","title":"Kolibri","text":"Kolibris können kontrolliert rückwärts fliegen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-052","category":"Unnützes Wissen","title":"Fledermäuse","text":"Fledermäuse sind nicht blind. Viele Arten kombinieren Sehen mit Echoortung.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-053","category":"Unnützes Wissen","title":"Giraffenhals","text":"Giraffen besitzen wie Menschen normalerweise sieben Halswirbel, nur erheblich längere.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-054","category":"Unnützes Wissen","title":"Schmetterlingsfüße","text":"Viele Schmetterlinge besitzen Geschmacksrezeptoren an den Füßen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-055","category":"Unnützes Wissen","title":"Bienentanz","text":"Honigbienen können mit dem Schwänzeltanz Richtung und Entfernung einer Futterquelle vermitteln.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-056","category":"Unnützes Wissen","title":"Ameisenatmung","text":"Ameisen besitzen keine Lungen, sondern atmen über ein Tracheensystem.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-057","category":"Unnützes Wissen","title":"Babyknochen","text":"Neugeborene besitzen mehr einzelne Knochen als Erwachsene, weil später viele miteinander verschmelzen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-058","category":"Unnützes Wissen","title":"Hornhaut","text":"Die Hornhaut des Auges besitzt normalerweise keine Blutgefäße.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-059","category":"Unnützes Wissen","title":"Zungenkarte","text":"Die bekannte Zungenkarte mit streng getrennten Geschmackszonen ist eine irreführende Vereinfachung.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-060","category":"Unnützes Wissen","title":"Gänsehaut","text":"Gänsehaut entsteht durch winzige Muskeln an den Haarfollikeln und ist ein evolutionäres Überbleibsel.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-061","category":"Unnützes Wissen","title":"Jupiter","text":"Jupiter ist der größte Planet unseres Sonnensystems.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/jupiter/jupiter-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-062","category":"Unnützes Wissen","title":"Jupitertag","text":"Ein Tag auf Jupiter dauert nur knapp zehn Stunden.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/jupiter/jupiter-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-063","category":"Unnützes Wissen","title":"Uranus","text":"Uranus besitzt eine extrem gekippte Rotationsachse und wirkt, als rolle er auf seiner Umlaufbahn.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/uranus/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-064","category":"Unnützes Wissen","title":"Olympus Mons","text":"Olympus Mons auf dem Mars ist der größte bekannte Vulkan des Sonnensystems.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/mars/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-065","category":"Unnützes Wissen","title":"Sonnenlicht","text":"Sonnenlicht braucht im Mittel etwas mehr als acht Minuten bis zur Erde.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/sun/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-066","category":"Unnützes Wissen","title":"Sterne Vergangenheit","text":"Wegen der endlichen Lichtgeschwindigkeit sehen wir entfernte Sterne so, wie sie in der Vergangenheit aussahen.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/universe/stars/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-067","category":"Unnützes Wissen","title":"Schall im Vakuum","text":"Im idealen Vakuum kann sich Schall nicht ausbreiten, weil Teilchen zur Weitergabe der Schwingung fehlen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-068","category":"Unnützes Wissen","title":"Eis schwimmt","text":"Wasser wird beim Gefrieren weniger dicht. Deshalb schwimmt Eis auf flüssigem Wasser.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-069","category":"Unnützes Wissen","title":"Wikingerhörner","text":"Für gehörnte Wikingerhelme im normalen Kampf gibt es keine belastbaren archäologischen Belege.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-070","category":"Unnützes Wissen","title":"Vanille","text":"Echte Vanille wird aus den Früchten bestimmter Orchideenarten gewonnen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-071","category":"Unnützes Wissen","title":"Safran","text":"Safran besteht aus den getrockneten Narben einer Krokusart.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-072","category":"Unnützes Wissen","title":"Gefrierbrand","text":"Gefrierbrand ist im Kern Feuchtigkeitsverlust gefrorener Lebensmittel, kein tatsächlicher Brand.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-073","category":"Unnützes Wissen","title":"Zwiebeln","text":"Beim Zwiebelschneiden entstehen flüchtige Reizstoffe, die die Augen zum Tränen bringen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-074","category":"Unnützes Wissen","title":"GPS","text":"GPS muss relativistische Effekte auf Satellitenuhren berücksichtigen, sonst würden Positionsfehler anwachsen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-075","category":"Unnützes Wissen","title":"Fresnel","text":"Fresnel-Linsen ermöglichen Leuchttürmen eine starke Bündelung des Lichts.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-076","category":"Unnützes Wissen","title":"Donner","text":"Blitze erhitzen Luft extrem schnell; ihre schlagartige Ausdehnung erzeugt die Druckwelle des Donners.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"kelly-001","category":"Kelly Memory","title":"Westfalenhalle auf Risiko","text":"1994 mietete die Kelly Family die Dortmunder Westfalenhalle auf eigenes Risiko. Am 15. Mai war sie mit rund 17.000 Menschen ausverkauft.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-002","category":"Kelly Memory","title":"Songs vor Album","text":"„An Angel“, „First Time“ und „Why Why Why“ wurden in der Westfalenhalle 1994 bereits live gespielt, bevor „Over The Hump“ erschien.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-003","category":"Kelly Memory","title":"32 Songs","text":"Die Setlist des Westfalenhallen-Konzerts 1994 umfasste 32 Songs.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-004","category":"Kelly Memory","title":"Dan Kelly","text":"Beim Konzert 1994 kam Dan Kelly bei „Take My Hand“ auf die Bühne und trat nach seinem Schlaganfall erstmals seit Jahren wieder mit seinen Kindern auf.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-005","category":"Kelly Memory","title":"Cliffs of Moher","text":"Fotos für „Over The Hump“ entstanden 1994 an den Cliffs of Moher an Irlands Westküste.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/biographie/biographie.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-006","category":"Kelly Memory","title":"Kölner Studio","text":"„Over The Hump“ wurde im Sound Studio N in Köln aufgenommen.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-007","category":"Kelly Memory","title":"Produktion","text":"Hartmut Pfannmüller und Kathy Kelly werden als Produzenten von „Over The Hump“ geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-008","category":"Kelly Memory","title":"Neun im Line-up","text":"Das Album-Line-up umfasste Kathy, John, Patricia, Jimmy, Joey, Barby, Paddy, Maite und Angelo.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-009","category":"Kelly Memory","title":"Track 1","text":"„Why Why Why“ eröffnet „Over The Hump“; die Lead Vocals werden Joey und Paddy zugeschrieben.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-010","category":"Kelly Memory","title":"Track 2","text":"„Father's Nose“ ist Track 2; die Lead Vocals liegen bei Kathy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-011","category":"Kelly Memory","title":"Track 3","text":"„First Time“ ist Track 3; die Lead Vocals liegen bei Patricia.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-012","category":"Kelly Memory","title":"Durchbruch","text":"„Over The Hump“ wurde 1994 zum entscheidenden kommerziellen Durchbruch der Kelly Family im deutschsprachigen Raum.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-013","category":"Kelly Memory","title":"Straße trotz Halle","text":"Auch nachdem große Hallen gefüllt wurden, spielte die Familie 1994 weiterhin Straßenkonzerte und Straßenfeste.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/biographie/biographie.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-014","category":"Kelly Memory","title":"Irland 1994","text":"Anfang 1994 besuchte die Familie Cork und spielte spontan in einer Dubliner Fußgängerzone.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/biographie/biographie.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-015","category":"Kelly Memory","title":"Tough Road","text":"„Tough Road Vol. 3 – Backstage“ dokumentiert zentrale Stationen des Jahres 1994, darunter Westfalenhalle, Recording-Session und „An Angel“-Making-of.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/videos/tough_road_vol_3_backstage.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-016","category":"Kelly Memory","title":"30 Jahre später","text":"„Tough Road – Live At Westfalenhalle '94“ erschien zum 30-jährigen Jubiläum erstmals als Live-Album auf CD.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-017","category":"Kelly Memory","title":"An Angel verknüpft","text":"Zu „Over The Hump“ gehören als verlinkte Veröffentlichungen unter anderem „An Angel“, „Why Why Why“, „Roses Of Red“ und „First Time“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-018","category":"Kelly Memory","title":"CD MC LP","text":"„Over The Hump“ ist in den Formaten CD, MC und LP dokumentiert.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-019","category":"Kelly Memory","title":"Executive Producer","text":"Dan Kelly und Mike Ungefehr werden für „Over The Hump“ als Executive Producer geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-020","category":"Kelly Memory","title":"Vor dem Album live","text":"Das große Dortmunder Konzert im Mai 1994 lag zeitlich vor der Veröffentlichung von „Over The Hump“ und macht es zu einem besonders spannenden Zeitdokument.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"motivation-001","category":"Motivation","title":"One More Day","text":"Du musst heute nicht die ganze Woche schaffen. Heute reicht heute.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-002","category":"Motivation","title":"One More Day","text":"Motivation ist unzuverlässig. Gewohnheit taucht wenigstens auch montags auf.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-003","category":"Motivation","title":"One More Day","text":"Ein schlechter Arbeitstag, den man erledigt hat, ist immer noch erledigt.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-004","category":"Motivation","title":"One More Day","text":"Fortschritt sieht selten spektakulär aus. Meistens sieht er aus wie: trotzdem gegangen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-005","category":"Motivation","title":"One More Day","text":"Manchmal ist Disziplin nur Motivation in Arbeitskleidung.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-006","category":"Motivation","title":"One More Day","text":"Du brauchst keinen perfekten Tag. Du brauchst nur einen abgeschlossenen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-007","category":"Motivation","title":"One More Day","text":"Ein Schritt Richtung Arbeit ist immer auch ein Schritt Richtung Feierabend.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-008","category":"Motivation","title":"One More Day","text":"Jeder erledigte Arbeitstag ist ein Beweis, dass der nächste machbar ist.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-009","category":"Motivation","title":"One More Day","text":"Montag ist kein Charaktertest. Er ist nur ein Tag mit sehr schlechtem Marketing.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-010","category":"Motivation","title":"One More Day","text":"Der innere Schweinehund hat viele Argumente. Er hat nur leider keinen Arbeitsvertrag.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-011","category":"Motivation","title":"One More Day","text":"Keine Lust zu haben und trotzdem hinzugehen ist eine ziemlich praktische Superkraft.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-012","category":"Motivation","title":"One More Day","text":"Nicht jeder Tag muss großartig werden. Manchmal reicht: hingegangen, erledigt, nach Hause gekommen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-013","category":"Motivation","title":"One More Day","text":"Ein Ziel muss nicht riesig sein. „Heute schaffen“ ist völlig ausreichend.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-014","category":"Motivation","title":"One More Day","text":"Manchmal gewinnt nicht der motivierteste Mensch, sondern der, der einfach angefangen hat.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-015","category":"Motivation","title":"One More Day","text":"Der Feierabend fühlt sich besser an, wenn man vorher tatsächlich da war. Ärgerliche Konstruktion, aber offenbar so vorgesehen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-016","category":"Motivation","title":"One More Day","text":"Mittwoch ist keine Feier. Aber immerhin ist Montag inzwischen Geschichte.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-017","category":"Motivation","title":"One More Day","text":"Freitag wird nicht schneller, wenn man Donnerstag böse anschaut.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-018","category":"Motivation","title":"One More Day","text":"Ein Arbeitstag nach dem anderen. Menschen haben schon kompliziertere Systeme erfolgreich überlebt.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-019","category":"Motivation","title":"One More Day","text":"Der Weg zur Arbeit ist morgens selten attraktiv. Der Weg zurück hat dagegen ausgezeichnete Bewertungen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-020","category":"Motivation","title":"One More Day","text":"One More Day heißt nicht „für immer“. Es heißt genau das: noch diesen einen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"fact-077","category":"Unnützes Wissen","title":"Tausendfüßer sind keine Tausendfüßer","text":"Der Name ist unzuverlässig: Die meisten Tausendfüßer haben deutlich weniger als tausend Beine. 2021 wurde allerdings erstmals eine Art mit mehr als 1.000 Beinen beschrieben.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-078","category":"Unnützes Wissen","title":"Hundertfüßer zählen auch nicht sauber","text":"Auch Hundertfüßer haben nicht zwingend genau 100 Beine. Die Zahl variiert je nach Art.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-079","category":"Unnützes Wissen","title":"Motte oder Schmetterling?","text":"Die Unterscheidung zwischen Motten und Tagfaltern ist biologisch weniger sauber, als Alltagssprache vermuten lässt. Typische Merkmale helfen, haben aber Ausnahmen.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-080","category":"Unnützes Wissen","title":"Spinnen kleben nicht überall fest","text":"Spinnen vermeiden, an ihrem eigenen Netz hängen zu bleiben, unter anderem durch die Struktur ihrer Beine und dadurch, dass nicht jeder Faden gleich klebrig ist.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-081","category":"Unnützes Wissen","title":"Armadillos können springen","text":"Neunbinden-Gürteltiere können bei Schreck überraschend hoch senkrecht aufspringen. Im Straßenverkehr ist genau diese Reaktion leider gefährlich.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-082","category":"Unnützes Wissen","title":"Katzen schnurren nicht nur vor Glück","text":"Katzen schnurren nicht ausschließlich, wenn sie zufrieden sind. Auch Stress, Schmerz oder Selbstberuhigung können eine Rolle spielen.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-083","category":"Unnützes Wissen","title":"Mücken wählen tatsächlich aus","text":"Warum manche Menschen häufiger gestochen werden, hängt unter anderem von Körpergeruch, ausgeatmetem Kohlendioxid, Wärme und weiteren chemischen Signalen ab.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-084","category":"Unnützes Wissen","title":"Truthähne haben helles und dunkles Fleisch","text":"Unterschiedliche Muskelarbeit beeinflusst den Myoglobingehalt. Deshalb unterscheiden sich stark beanspruchte und weniger beanspruchte Muskelpartien in Farbe und Geschmack.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-085","category":"Unnützes Wissen","title":"Süßkartoffel ist nicht gleich Yams","text":"Süßkartoffeln und Yams sind botanisch verschiedene Pflanzenfamilien, obwohl die Namen im Handel teilweise durcheinandergehen.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-086","category":"Unnützes Wissen","title":"Fortune Cookies werden gefaltet","text":"Glückskekse werden zunächst flach gebacken. Der Zettel wird eingelegt und der noch warme, biegsame Keks anschließend gefaltet.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-087","category":"Unnützes Wissen","title":"Tiefkühlkost hat einen Namen","text":"Clarence Birdseye gilt als Schlüsselfigur der modernen Tiefkühlkost, weil er Verfahren zur schnellen Gefrierung industriell weiterentwickelte.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-088","category":"Unnützes Wissen","title":"Pfeffer reizt die Nase","text":"Pfeffer kann Niesen auslösen, weil seine Bestandteile empfindliche Nervenenden in der Nasenschleimhaut reizen.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-089","category":"Unnützes Wissen","title":"Grillen als Thermometer","text":"Bei bestimmten Grillenarten hängt die Zirprate von der Temperatur ab. Näherungsformeln können daraus tatsächlich eine Temperatur schätzen.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-090","category":"Unnützes Wissen","title":"Murmeltiere sind schlechte Meteorologen","text":"Der Schatten eines Murmeltiers liefert keine wissenschaftlich verlässliche Vorhersage darüber, ob der Winter sechs Wochen länger dauert.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-091","category":"Unnützes Wissen","title":"Feuerwerk trägt Sterne","text":"Die kleinen pyrotechnischen Pellets, die in Feuerwerkskörpern die sichtbaren Farben erzeugen, werden im Englischen tatsächlich „stars“ genannt.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-092","category":"Unnützes Wissen","title":"Metalle färben Feuer","text":"Bestimmte Metallverbindungen erzeugen beim Erhitzen charakteristische Farben. Genau dieses Prinzip wird bei farbigem Feuerwerk genutzt.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-093","category":"Unnützes Wissen","title":"Tiefsee beginnt früh","text":"NOAA definiert den tiefen Ozean typischerweise ab ungefähr 200 Metern, dort wo das Sonnenlicht deutlich schwächer wird.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/deep-ocean/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-094","category":"Unnützes Wissen","title":"Ab 1.000 Metern wird es richtig dunkel","text":"Unterhalb von ungefähr 1.000 Metern erreicht praktisch kein Sonnenlicht mehr den offenen Ozean.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/deep-ocean/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-095","category":"Unnützes Wissen","title":"Tiefsee ist kalt","text":"Die tiefe See hat laut NOAA im Mittel nur ungefähr 4 °C.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/deep-ocean/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-096","category":"Unnützes Wissen","title":"Tiefsee ist Drucksache","text":"In großen Meerestiefen herrscht ein Vielfaches des atmosphärischen Drucks an der Erdoberfläche.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/deep-ocean/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-097","category":"Unnützes Wissen","title":"Fluoreszenz ist kein eigenes Licht","text":"Bei Fluoreszenz wird eingestrahltes Licht aufgenommen und in anderer Farbe wieder abgegeben. Biolumineszenz dagegen entsteht durch eine chemische Reaktion im Organismus.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/living-light/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-098","category":"Unnützes Wissen","title":"Phosphoreszenz leuchtet nach","text":"Phosphoreszierendes Material kann nach dem Ende der Anregung weiterleuchten. Fluoreszenz verschwindet dagegen typischerweise sehr schnell.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/living-light/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-099","category":"Unnützes Wissen","title":"Vampirtintenfisch mit Lichtshow","text":"Vampirtintenfische besitzen Leuchtorgane und können Lichtsignale zur Ablenkung möglicher Angreifer einsetzen.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/wp-content/uploads/2025/04/bioluminescence-fact-sheet.pdf","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-100","category":"Unnützes Wissen","title":"Leuchten ohne Hitze","text":"Biolumineszenz erzeugt sichtbares Licht durch chemische Reaktionen und ist wesentlich effizienter als Lichtproduktion über starke Erwärmung.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/living-light/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-101","category":"Unnützes Wissen","title":"Licht zum Verstecken","text":"Einige Meerestiere nutzen Licht nicht nur, um gesehen zu werden, sondern zur Tarnung: Gegenbeleuchtung kann ihre Silhouette von unten abschwächen.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/education/bioluminescence/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-102","category":"Unnützes Wissen","title":"Katzen sprechen anders mit uns","text":"Hauskatzen nutzen Miauen besonders intensiv in der Kommunikation mit Menschen; unter erwachsenen Katzen spielt es untereinander eine geringere Rolle.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-103","category":"Unnützes Wissen","title":"Schwarzes und weißes Truthahnfleisch","text":"Brustmuskeln und Beinmuskeln eines Truthahns erfüllen unterschiedliche Aufgaben. Das beeinflusst ihre Zusammensetzung und Farbe.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-104","category":"Unnützes Wissen","title":"Petrified Forest war einmal Wald","text":"Versteinertes Holz bewahrt Strukturen ehemaliger Bäume, obwohl ein großer Teil des ursprünglichen organischen Materials durch Mineralien ersetzt wurde.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/categories/earth-sciences/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-105","category":"Unnützes Wissen","title":"Schnee ist komplizierter als sechs Zacken","text":"Eiskristalle besitzen eine sechszählige Grundsymmetrie, können aber je nach Temperatur und Feuchtigkeit sehr unterschiedliche Formen entwickeln.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-106","category":"Unnützes Wissen","title":"Schokolade schmilzt absichtlich günstig","text":"Dass Schokolade nahe der Körpertemperatur schmilzt, trägt wesentlich zu ihrem Mundgefühl bei. In der Hand ist dieselbe Eigenschaft weniger beeindruckend.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-107","category":"Unnützes Wissen","title":"Natrium heißt Na","text":"Das Elementsymbol Na für Natrium stammt vom lateinischen „natrium“. Ähnliche historische Namensreste erklären weitere scheinbar unpassende Symbole.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-108","category":"Unnützes Wissen","title":"Gold heißt Au","text":"Das chemische Symbol Au für Gold geht auf das lateinische „aurum“ zurück.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-109","category":"Unnützes Wissen","title":"Eisen heißt Fe","text":"Das Elementsymbol Fe stammt vom lateinischen „ferrum“.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-110","category":"Unnützes Wissen","title":"Kalium heißt K","text":"Das K in der Chemie stammt von „kalium“, auch wenn das Element auf Englisch potassium heißt.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-111","category":"Unnützes Wissen","title":"Gefrierbrand ist meist Qualitätsproblem","text":"Gefrierbrand macht Lebensmittel trocken und verändert Geschmack und Textur. Er ist nicht automatisch ein Zeichen für verdorbene Lebensmittel.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/food-and-nutrition/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-112","category":"Unnützes Wissen","title":"Zwiebeln greifen nicht persönlich an","text":"Das Tränen beim Zwiebelschneiden ist eine chemische Abwehrreaktion der Pflanze, keine persönliche Bewertung deiner Kochkünste.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/food-and-nutrition/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-113","category":"Unnützes Wissen","title":"Tiefsee ohne Photosynthese","text":"Unterhalb der lichtdurchfluteten Zone reicht Sonnenlicht nicht für Photosynthese. Tiefseeökosysteme brauchen deshalb andere Energiequellen oder organisches Material von oben.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/deep-ocean/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-114","category":"Unnützes Wissen","title":"Biolumineszenz hat mehrere Erfinder","text":"Die Fähigkeit, Licht zu erzeugen, scheint sich im Lauf der Evolution mehrfach unabhängig entwickelt zu haben.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/bioluminescence/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-115","category":"Unnützes Wissen","title":"Rot ist in der Tiefsee fast schwarz","text":"Rotes Licht dringt im Meerwasser schlecht in große Tiefen vor. Rote Tiere können deshalb in der Tiefsee besonders dunkel wirken.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/education/bioluminescence/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-116","category":"Unnützes Wissen","title":"Lebendes Licht gibt es von Bakterien bis Haien","text":"Biolumineszente Vertreter finden sich in sehr unterschiedlichen Tier- und Organismengruppen des Meeres.","source":"NOAA","sourceUrl":"https://oceanservice.noaa.gov/facts/biolum.html","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"kelly-021","category":"Kelly Deep Cut","title":"Almost Heaven erschien 1996","text":"„Almost Heaven“ erschien erstmals am 25. Oktober 1996 und war als CD, MC und LP erhältlich.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-022","category":"Kelly Deep Cut","title":"Zwei Studios für Almost Heaven","text":"„Almost Heaven“ wurde bei Capri Digital in Italien und im Sound Studio N in Köln aufgenommen.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-023","category":"Kelly Deep Cut","title":"Produzenten-Duo","text":"Paddy Kelly und Kathy Kelly werden als Produzenten von „Almost Heaven“ geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-024","category":"Kelly Deep Cut","title":"Albumauftakt 1996","text":"„When The Boys Come Into Town“ eröffnet „Almost Heaven“; Lead Vocals: John, Maite und Paddy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-025","category":"Kelly Deep Cut","title":"Every Baby","text":"„Every Baby“ ist Track 2 von „Almost Heaven“ und wird von Maite gesungen.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-026","category":"Kelly Deep Cut","title":"I Can't Help Myself","text":"„I Can't Help Myself“ steht auf „Almost Heaven“ an Position 3; Lead Vocals: Angelo und Paddy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-027","category":"Kelly Deep Cut","title":"Nanana gehört Jimmy","text":"Auf „Almost Heaven“ werden die Lead Vocals von „Nanana“ Jimmy zugeschrieben.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-028","category":"Kelly Deep Cut","title":"You Belong To Me","text":"Patricia übernimmt die Lead Vocals bei „You Belong To Me“ auf „Almost Heaven“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-029","category":"Kelly Deep Cut","title":"Staying Alive","text":"Joey singt die Lead Vocals von „Staying Alive“ auf „Almost Heaven“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-030","category":"Kelly Deep Cut","title":"Come Back To Me","text":"„Come Back To Me“ wird auf „Almost Heaven“ von Kathy gesungen.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-031","category":"Kelly Deep Cut","title":"Alien-Duo","text":"Bei „Fell In Love With An Alien“ werden Paddy und Kathy als Lead Vocals geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-032","category":"Kelly Deep Cut","title":"Vier Stimmen bei Hey Diddle Diddle","text":"„Hey Diddle Diddle“ führt Paddy, Maite, Angelo und Barby gemeinsam als Lead Vocals.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-033","category":"Kelly Deep Cut","title":"Like A Queen","text":"Barby übernimmt die Lead Vocals bei „Like A Queen“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-034","category":"Kelly Deep Cut","title":"Stars Fall From Heaven","text":"Patricia und Maite teilen sich die Lead Vocals bei „Stars Fall From Heaven“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-035","category":"Kelly Deep Cut","title":"Thunder","text":"Jimmy singt „Thunder“ auf „Almost Heaven“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-036","category":"Kelly Deep Cut","title":"Calling Heaven","text":"Paddy übernimmt die Lead Vocals bei „Calling Heaven“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-037","category":"Kelly Deep Cut","title":"Albumabschluss","text":"„Nothing Like Home“ schließt „Almost Heaven“ ab; Lead Vocals: Kathy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-038","category":"Kelly Memory","title":"Erste Almost-Heaven-Single","text":"„I Can't Help Myself“ erschien in Deutschland am 18. Juli 1996 als Single, noch vor dem Album.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/i_cant_help_myself.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-039","category":"Kelly Deep Cut","title":"Look Up My File als Bonus","text":"Auf der Single „I Can't Help Myself“ befand sich der zuvor unveröffentlichte Bonus-Track „Look Up My File“ mit Paddy als Lead Vocal.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/i_cant_help_myself.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-040","category":"Kelly Memory","title":"Every Baby Single","text":"„Every Baby“ erschien am 21. November 1996 als Single.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/every_baby.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-041","category":"Kelly Deep Cut","title":"Fat Man Bonus-Track","text":"Die „Every Baby“-Single enthielt den zuvor unveröffentlichten Bonus-Track „Fat Man“ mit Paddy, Kathy und Angelo.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/every_baby.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-042","category":"Kelly Memory","title":"Alien am Valentinstag","text":"„Fell In Love With An Alien“ erschien am 14. Februar 1997 als Single. Valentinstag war dafür zumindest thematisch nicht die unpassendste Wahl.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/fell_in_love_with_an_alien.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-043","category":"Kelly Deep Cut","title":"Never Gonna Break Me Down","text":"Die „Fell In Love With An Alien“-Single enthielt „Never Gonna Break Me Down“ als zuvor unveröffentlichten Bonus-Track mit Joey und Paddy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/fell_in_love_with_an_alien.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-044","category":"Kelly Memory","title":"Nanana Single","text":"„Nanana“ erschien am 23. Mai 1997 als Single.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/nanana.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-045","category":"Kelly Deep Cut","title":"I'm So Happy","text":"Auf der „Nanana“-Single findet sich „I'm So Happy“ mit Angelo als Lead Vocal als zuvor unveröffentlichter Bonus-Track.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/nanana.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-046","category":"Kelly Memory","title":"Because It's Love","text":"„Because It's Love“ erschien am 29. August 1997 als Single und ist mit „Growin' Up“ verknüpft.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/because_its_love.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-047","category":"Kelly Deep Cut","title":"I'll Send You A Letter","text":"Die 3-Track-Version von „Because It's Love“ enthält „I'll Send You A Letter“ mit Paddy und Maite.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/because_its_love.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-048","category":"Kelly Memory","title":"One More Song Single","text":"„One More Song“ erschien am 29. Januar 1998 als Single und ist mit „Growin' Up“ verknüpft.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/one_more_song.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-049","category":"Kelly Deep Cut","title":"Leave It To The Spirits","text":"Die 3-Track-Version von „One More Song“ enthält „Leave It To The Spirits“ mit Barby und Jimmy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/one_more_song.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-050","category":"Kelly Memory","title":"From Their Hearts","text":"„From Their Hearts“ erschien am 2. November 1998 als Studioalbum.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-051","category":"Kelly Deep Cut","title":"Drei Produzenten","text":"Paddy, Kathy und Angelo werden als Produzenten von „From Their Hearts“ geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-052","category":"Kelly Memory","title":"Irland und Frankreich","text":"„From Their Hearts“ wurde mit dem Blue Moon Mobile Recording Unit in Cork sowie im Studio Miraval in Correns, Frankreich, aufgenommen.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-053","category":"Kelly Deep Cut","title":"Sean als Special Guest","text":"Bei „From Their Hearts“ wird Sean als Special Guest im Line-up geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-054","category":"Kelly Deep Cut","title":"I Feel Love","text":"„I Feel Love“ eröffnet „From Their Hearts“ mit Paddy, Maite und Angelo als Lead Vocals.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-055","category":"Kelly Deep Cut","title":"Hooks","text":"„Hooks“ ist Track 2 von „From Their Hearts“ mit Barby und Paddy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-056","category":"Kelly Deep Cut","title":"Please Don't Go","text":"Patricia und Jimmy teilen sich die Lead Vocals von „Please Don't Go“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-057","category":"Kelly Deep Cut","title":"Maximum","text":"Joey übernimmt die Lead Vocals bei „Maximum“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-058","category":"Kelly Deep Cut","title":"Oh It Hurts","text":"Maite singt die Lead Vocals bei „Oh It Hurts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-059","category":"Kelly Deep Cut","title":"Yo Te Quiero","text":"Kathy singt „Yo Te Quiero“ auf „From Their Hearts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-060","category":"Kelly Deep Cut","title":"Dance To The Rock'n'Roll","text":"Paddy, Maite und Sean werden bei „Dance To The Rock'n'Roll“ als Lead Vocals geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-061","category":"Kelly Deep Cut","title":"Why Don't You Go","text":"Paddy übernimmt „Why Don't You Go“ auf „From Their Hearts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-062","category":"Kelly Deep Cut","title":"You're Losing Me","text":"Kathy singt die Lead Vocals bei „You're Losing Me“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-063","category":"Kelly Deep Cut","title":"You Got Me Rockin' Now","text":"Angelo, Paddy und Maite teilen sich die Lead Vocals bei „You Got Me Rockin' Now“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-064","category":"Kelly Deep Cut","title":"Hallelujah","text":"Joey übernimmt „Hallelujah“ auf „From Their Hearts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-065","category":"Kelly Deep Cut","title":"Sweetest Angel","text":"Barby singt „Sweetest Angel“ auf „From Their Hearts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-066","category":"Kelly Deep Cut","title":"I Will Be Your Bride","text":"Angelo übernimmt die Lead Vocals bei „I Will Be Your Bride“, dem letzten regulären Track von „From Their Hearts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-067","category":"Kelly Memory","title":"I Really Love You spät als Single","text":"„I Really Love You“ erschien erst am 25. Dezember 1999 als Single, mehr als ein Jahr nach „From Their Hearts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/i_really_love_you.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-068","category":"Kelly Deep Cut","title":"Live-Version auf Single","text":"Eine 3-Track-Version von „I Really Love You“ enthält „Quisiera Ser Un Angel“ als Live-Version mit Paddy und Kathy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/i_really_love_you.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"motivation-021","category":"Motivation","title":"One More Day","text":"Wenn heute nur durchschnittlich wird, ist das völlig okay. Durchschnittliche Tage bringen einen genauso Richtung Wochenende.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-022","category":"Motivation","title":"One More Day","text":"Du musst dich nicht auf Arbeit freuen. Es genügt, wenn du dich später auf Feierabend freust.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-023","category":"Motivation","title":"One More Day","text":"Ein Haken hinter einem Tag ist manchmal mehr wert als zehn gute Vorsätze.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-024","category":"Motivation","title":"One More Day","text":"Der heutige Auftrag ist überschaubar: auftauchen, durchkommen, abhaken.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-025","category":"Motivation","title":"One More Day","text":"Nicht jeder Fortschritt fühlt sich nach Fortschritt an. Manchmal fühlt er sich einfach nach Mittwoch an.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-026","category":"Motivation","title":"One More Day","text":"Wenn der Kopf schon beim ganzen Monat streikt, gib ihm nur den heutigen Tag.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-027","category":"Motivation","title":"One More Day","text":"Ein erledigter Tag braucht im Nachhinein keine Motivation mehr.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-028","category":"Motivation","title":"One More Day","text":"Die Woche wird nicht auf einmal geschafft. Sie wird in einzelnen Tagen eingesammelt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-029","category":"Motivation","title":"One More Day","text":"Auch 60 Prozent Energie können 100 Prozent Anwesenheit schaffen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-030","category":"Motivation","title":"One More Day","text":"Der Start darf schwer sein. Er muss nur stattfinden.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-031","category":"Motivation","title":"One More Day","text":"Wenn heute zäh ist, darf heute zäh sein. Das Ziel bleibt trotzdem dasselbe.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-032","category":"Motivation","title":"One More Day","text":"Du arbeitest nicht für den Montag. Du arbeitest dich durch ihn hindurch.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-033","category":"Motivation","title":"One More Day","text":"Jeder Feierabend beginnt irgendwann mit einem Arbeitsbeginn. Leider hat das System diese Lücke nie geschlossen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-034","category":"Motivation","title":"One More Day","text":"Nicht denken, wie lange noch. Erst einmal anfangen, dann darf die Uhr ihren Job machen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-035","category":"Motivation","title":"One More Day","text":"Manchmal ist „ich bin trotzdem gegangen“ die beste Leistung des Tages.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-036","category":"Motivation","title":"One More Day","text":"Du brauchst heute keine Heldengeschichte. Ein grüner Haken reicht.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-037","category":"Motivation","title":"One More Day","text":"Ein Tag mehr geschafft ist kein Motivationsspruch, sondern Mathematik.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-038","category":"Motivation","title":"One More Day","text":"Wenn die Woche nervt, zerleg sie in Stücke. Heute ist nur eines davon.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-039","category":"Motivation","title":"One More Day","text":"Der morgige Tag bekommt seine Probleme morgen. Heute hat schon genug eigene.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-040","category":"Motivation","title":"One More Day","text":"Ein kleines Ziel, konsequent erreicht, schlägt ein großes Ziel, das nur hübsch klingt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"mpk-001","category":"MPK · Hinter dem Song","title":"B.O.A.T.S. heißt wörtlich Programm","text":"B.O.A.T.S. steht für „Based On A True Story“. Michael Patrick Kelly erklärte, dass die Songs des Albums auf wahren Geschichten beruhen, die er selbst erlebt oder von anderen Menschen erfahren hat.","source":"GALA Interview","sourceUrl":"https://www.gala.de/stars/interview/michael-patrick-kelly--er-war--wie-ein-alter-laptop-mit-viren--22546196.html","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-002","category":"MPK · Hinter dem Song","title":"60 fertige Songs, 15 ausgewählt","text":"Für B.O.A.T.S. schrieb Kelly nach eigener Aussage 60 vollständige Songs. Für die ursprüngliche Albumfassung wählte er daraus 15 aus.","source":"GALA Interview","sourceUrl":"https://www.gala.de/stars/interview/michael-patrick-kelly--er-war--wie-ein-alter-laptop-mit-viren--22546196.html","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-003","category":"MPK · Hinter dem Song","title":"Vier Jahre Reifezeit","text":"Zwischen seinem vorherigen Album und B.O.A.T.S. lagen rund vier Jahre. Kelly wollte den Songs bewusst mehr Zeit zum Reifen geben, statt schnell das nächste Album nachzuschieben.","source":"GALA Interview","sourceUrl":"https://www.gala.de/stars/interview/michael-patrick-kelly--er-war--wie-ein-alter-laptop-mit-viren--22546196.html","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-004","category":"MPK · Hinter dem Song","title":"Halbe Weltreise für Geschichten","text":"Für B.O.A.T.S. reiste Kelly unter anderem nach Grönland, auf die Färöer, nach Kenia, Kalifornien und in die Toskana, um Menschen und Geschichten zu finden, die ihn inspirieren konnten.","source":"urbanite Interview","sourceUrl":"https://www.urbanite.net/artikel/interview-michael-patrick-kelly/","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-005","category":"MPK · Hinter dem Song","title":"Wahre Geschichten statt Fiktion","text":"Kelly sagte, wahre Geschichten hätten für ihn eine besondere Kraft. Diese Vorliebe für „based on a true story“ übertrug er bewusst auf das Albumkonzept.","source":"t-online / dpa","sourceUrl":"https://berlin.t-online.de/region/berlin/id_91112726/hit-melodien-mit-tiefgang-boats-von-michael-patrick-kelly.html","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-006","category":"MPK · Hinter dem Song","title":"Mother's Day","text":"„Mother's Day“ ist Kellys früh verstorbener Mutter gewidmet. Er war fünf Jahre alt, als sie im Alter von 36 Jahren starb.","source":"Allgäuer Zeitung Interview","sourceUrl":"https://www.allgaeuer-zeitung.de/panorama/saenger-michael-patrick-kelly-ich-traeume-nachts-meine-songs-103492752","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-007","category":"MPK · Hinter dem Song","title":"Perfektion bis zum Master","text":"Kelly berichtete, dass er selbst während des Mixings noch Teile neu aufnimmt, wenn ihn etwas stört. Vor Abgabe des B.O.A.T.S.-Masters arbeitete er bis in die letzte Nacht hinein.","source":"Allgäuer Zeitung Interview","sourceUrl":"https://www.allgaeuer-zeitung.de/panorama/saenger-michael-patrick-kelly-ich-traeume-nachts-meine-songs-103492752","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-008","category":"MPK Moment","title":"Songideen kommen schnell, Songs nicht","text":"Kelly unterscheidet zwischen spontanen Songideen und fertigen Songs: Erste Ideen kämen oft schnell, an Text, Struktur und Produktion arbeite er dagegen lange.","source":"subtext.at Interview","sourceUrl":"https://www.subtext.at/2021/11/mpk-das-geschenk-des-lebens-ist-nicht-selbstverstaendlich/","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-009","category":"MPK Moment","title":"Bewusst auf Stop gedrückt","text":"Nach Jahren des schnellen Musikgeschäfts nahm Kelly bewusst ein Sabbatjahr. Er wollte Zeit zum Reisen und Schreiben haben und ein Album schaffen, das nicht nur dem nächsten Veröffentlichungstermin hinterherläuft.","source":"subtext.at Interview","sourceUrl":"https://www.subtext.at/2021/11/mpk-das-geschenk-des-lebens-ist-nicht-selbstverstaendlich/","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-010","category":"MPK Moment","title":"Songs bekommen ein Eigenleben","text":"Kelly bezeichnete es als besonderen Erfolg, wenn Menschen seine Songs mit eigenen wichtigen Lebensmomenten verbinden, etwa Wettkämpfen, Hochzeiten, Abschieden oder Trost.","source":"MoPop Interview","sourceUrl":"https://mopop.de/interviews/michael-patrick-kelly-leute-haben-zu-meinen-songs-kinder-gezeugt-19655","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-011","category":"MPK Moment","title":"Shake Away als mentale Hilfe","text":"Kelly erzählte von der Skirennfahrerin Michelle Gisin, die seine Musik vor Wettkämpfen nutzte, um Ängste und Sorgen abzuschütteln; er nannte „Shake Away“ als passenden Song dazu.","source":"MoPop Interview","sourceUrl":"https://mopop.de/interviews/michael-patrick-kelly-leute-haben-zu-meinen-songs-kinder-gezeugt-19655","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-012","category":"MPK Moment","title":"Musik als gemeinsames Erlebnis","text":"Kelly beschreibt Konzerte als Momente, in denen Menschen Alltagssorgen für einige Stunden loslassen, gemeinsam tanzen, singen, lachen oder weinen können.","source":"urbanite Interview","sourceUrl":"https://www.urbanite.net/artikel/interview-michael-patrick-kelly/","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-013","category":"MPK · Hinter dem Song","title":"Der Titelsong B.O.A.T.S.","text":"Beim Titelsong geht es laut Kelly auch um die Frage, wo Menschen ihre eigene Geschichte beschönigen, Muster verdrängen oder sich selbst ein falsches Bild erzählen.","source":"Süddeutsche Zeitung Interview","sourceUrl":"https://www.sueddeutsche.de/muenchen/michael-patrick-kelly-paddy-kelly-kelly-family-olympiahalle-muenchen-1.5653295","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-014","category":"MPK Moment","title":"Drei Akkorde und Wahrheit","text":"Für B.O.A.T.S. griff Kelly wiederholt das Songwriter-Motto auf, ein guter Song brauche im Kern wenige Akkorde und Wahrheit. Für ihn war die Wahrhaftigkeit der Geschichten das verbindende Element des Albums.","source":"GALA / t-online Interviews","sourceUrl":"https://www.gala.de/stars/interview/michael-patrick-kelly--er-war--wie-ein-alter-laptop-mit-viren--22546196.html","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-015","category":"MPK Moment","title":"60 aus Hunderten Ideen","text":"Kelly berichtete von hunderten Songideen, aus denen schließlich 60 vollständige Songs entstanden. Nur ein Teil davon schaffte es auf B.O.A.T.S.","source":"subtext.at Interview","sourceUrl":"https://www.subtext.at/2021/11/mpk-das-geschenk-des-lebens-ist-nicht-selbstverstaendlich/","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"joey-001","category":"Joey Impuls","title":"Das Ziel kommt vor der Motivation","text":"Joey Kelly hält das konkrete Ziel für wichtiger als das Gefühl von Motivation. Ist das Ziel entschieden, entstehen für ihn daraus Motivation, Disziplin und Ausdauer.","source":"Handwerk Magazin Interview","sourceUrl":"https://www.handwerk-magazin.de/interview-mit-joey-kelly-wer-ziele-hat-ist-motiviert-182659/","verified":true,"tone":"fan","sensitive":false,"tags":["Joey","Motivation"]},{"id":"joey-002","category":"Joey Impuls","title":"Ein Termin macht das Ziel konkret","text":"Bei Zielen betont Joey Kelly nicht nur das Was, sondern auch einen klaren Termin. Ein Ziel ohne zeitlichen Rahmen bleibt leichter unverbindlich.","source":"Handwerk Magazin Interview","sourceUrl":"https://www.handwerk-magazin.de/interview-mit-joey-kelly-wer-ziele-hat-ist-motiviert-182659/","verified":true,"tone":"fan","sensitive":false,"tags":["Joey","Motivation"]},{"id":"joey-003","category":"Joey Impuls","title":"Disziplin statt Tagesform","text":"In Joey Kellys Verständnis folgt auf ein gesetztes Ziel nicht tägliche Begeisterung, sondern diszipliniertes und ausdauerndes Verfolgen des Vorhabens.","source":"Handwerk Magazin Interview","sourceUrl":"https://www.handwerk-magazin.de/interview-mit-joey-kelly-wer-ziele-hat-ist-motiviert-182659/","verified":true,"tone":"fan","sensitive":false,"tags":["Joey","Motivation"]},{"id":"history-001","category":"Kuriose Geschichte","title":"Ein Schloss spart am falschen Ende","text":"Beim Bau des Smithsonian Castle wurden aus Kostengründen geplante feuerfeste Konstruktionen teilweise durch Holz ersetzt. 1850 sackte während der Bauarbeiten ein großer Teil der Innenkonstruktion in den Keller.","source":"Smithsonian Institution Archives","sourceUrl":"https://siarchives.si.edu/blog/smithsonian-castle-mystery","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte"]},{"id":"history-002","category":"Kuriose Geschichte","title":"Das Smithsonian Castle brannte später wirklich","text":"1865 zerstörte ein Brand große Teile des oberen Smithsonian Castle. Das Feuer vernichtete unter anderem Räume und Sammlungsbestandteile. Sparen an Brandsicherheit besitzt rückblickend einen gewissen bitteren Humor.","source":"Smithsonian Institution Archives","sourceUrl":"https://siarchives.si.edu/blog/smithsonian-castle-mystery","verified":true,"tone":"dark","sensitive":true,"tags":["Geschichte"]},{"id":"history-003","category":"Historisches Rätsel","title":"Das verschwundene Bernsteinzimmer","text":"Das berühmte Bernsteinzimmer wurde im Zweiten Weltkrieg von deutschen Truppen demontiert und abtransportiert. Sein endgültiges Schicksal nach Kriegsende ist bis heute nicht zweifelsfrei geklärt.","source":"Smithsonian Magazine","sourceUrl":"https://www.smithsonianmag.com/history/a-brief-history-of-the-amber-room-160940121/","verified":true,"tone":"mystery","sensitive":false,"tags":["Mystery"]},{"id":"history-004","category":"Kuriose Geschichte","title":"Orient-Express: mehr als Luxuszug","text":"Der Orient-Express wurde nicht nur zum Symbol luxuriösen Reisens. Seine Geschichte ist auch mit Diplomatie, Spionage, Krieg und politischen Umbrüchen verbunden.","source":"Smithsonian Magazine","sourceUrl":"https://www.smithsonianmag.com/history/a-brief-history-of-the-orient-express-149702768/","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte"]},{"id":"history-005","category":"Kuriose Geschichte","title":"Katzen leben lange mit uns","text":"Archäologische und genetische Forschung deutet darauf hin, dass Katzen seit Tausenden Jahren in enger Nähe zu Menschen leben, ohne denselben Domestikationsweg wie Hunde genommen zu haben.","source":"Smithsonian Magazine","sourceUrl":"https://www.smithsonianmag.com/history/a-brief-history-of-house-cats-158390681/","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Geschichte"]},{"id":"antike-001","category":"Geschichte · Antike","title":"Woher das Wort Demokratie kommt","text":"Das griechische dēmokratia verbindet dēmos, das Bürger- beziehungsweise Volkskörper bezeichnet, mit kratos, Herrschaft oder Macht. Wörtlich steckt also die Herrschaft des Volkes im Begriff.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/71/government--society-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-002","category":"Geschichte · Antike","title":"Athens Demokratie war direkt","text":"Im klassischen Athen entschieden Bürger nicht nur, wer sie vertreten sollte. Sie konnten selbst in der Volksversammlung sprechen und über Sachfragen abstimmen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-003","category":"Geschichte · Antike","title":"Aber längst nicht alle durften mitmachen","text":"Die berühmte athenische Demokratie war nach heutigem Maßstab stark eingeschränkt: Politische Bürgerrechte hatten freie erwachsene männliche Bürger. Frauen, Sklaven und viele Zugewanderte waren ausgeschlossen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-004","category":"Geschichte · Antike","title":"Mehrheit per Handzeichen","text":"In der athenischen Volksversammlung wurden Entscheidungen häufig durch Handzeichen getroffen. Eine einfache Mehrheit entschied.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-005","category":"Geschichte · Antike","title":"Platz für ungefähr 6.000","text":"Der Versammlungsort der Athener konnte ungefähr 6.000 Bürger aufnehmen. Bei besonders wichtigen Fragen war entsprechend viel Betrieb.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-006","category":"Geschichte · Antike","title":"Politik war Bürgerpflicht","text":"Athenische Bürger konnten nicht nur abstimmen. Von ihnen wurde auch erwartet, zeitweise Ämter oder andere öffentliche Aufgaben zu übernehmen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-007","category":"Geschichte · Antike","title":"Los statt Wahl","text":"Viele öffentliche Aufgaben in Athen wurden per Los vergeben. Dahinter stand die Idee, politische Beteiligung nicht dauerhaft einer kleinen Berufspolitiker-Schicht zu überlassen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-008","category":"Geschichte · Antike","title":"Eine Maschine loste Geschworene aus","text":"Das Kleroterion war eine Losmaschine, mit der Athen unter anderem Geschworene zufällig auswählte. Zufall sollte Manipulation und vorherige Bestechung erschweren.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-009","category":"Geschichte · Antike","title":"Riesige Geschworenengerichte","text":"Athenische Gerichte konnten aus sehr vielen Bürgern bestehen. Das unterschied sich deutlich von modernen zwölfköpfigen Jurys.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-010","category":"Geschichte · Antike","title":"Politisches Exil per Abstimmung","text":"Beim Ostrakismos konnten Athener darüber abstimmen, einen als gefährlich angesehenen Bürger für Jahre aus der Stadt zu verbannen. Daher stammt unser Wort Ostrakismus.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/71/government--society-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-011","category":"Geschichte · Antike","title":"Agora: Marktplatz und Nachrichtenfeed","text":"Die Agora war nicht bloß Einkaufsplatz. Sie war ein zentraler sozialer und politischer Treffpunkt, an dem Handel, Gespräche und öffentliche Angelegenheiten zusammenliefen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/76/daily-life-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-012","category":"Geschichte · Antike","title":"Symposium war mehr als Trinken","text":"Bei einem griechischen Symposium wurde getrunken, aber auch musiziert, Gedichte vorgetragen, diskutiert und über Politik oder Alltagsfragen gesprochen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/76/daily-life-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-013","category":"Geschichte · Antike","title":"Griechische Nachbarn konnten sehr verschieden sein","text":"Das antike Griechenland war kein einheitlicher Nationalstaat wie das heutige Griechenland, sondern bestand aus zahlreichen Poleis mit eigenen politischen Systemen und Interessen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/71/government--society-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-014","category":"Geschichte · Antike","title":"Demokratie war nicht überall griechisch","text":"Neben Demokratien existierten in griechischen Stadtstaaten auch Oligarchien, Monarchien und andere Herrschaftsformen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/71/government--society-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-015","category":"Geschichte · Antike","title":"Sport und Politik lagen nah beieinander","text":"Öffentliche Wettkämpfe, religiöse Feste und Politik waren in der griechischen Polis eng mit dem Gemeinschaftsleben verbunden.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/76/daily-life-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-016","category":"Geschichte · Antike","title":"Die Griechen bauten kilometerlange Tunnel","text":"Griechische Ingenieure bauten bereits im 6. Jahrhundert v. Chr. auf Samos einen ungefähr einen Kilometer langen Tunnel zur Wasserversorgung.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-017","category":"Geschichte · Antike","title":"Krane halfen beim Tempelbau","text":"Flaschenzüge, Winden und Krane ermöglichten griechischen Baumeistern, schwere Steinblöcke für Tempel und Befestigungen zu bewegen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-018","category":"Geschichte · Antike","title":"Aquädukte waren nicht nur römisch","text":"Auch Griechen bauten Wasserleitungen und Aquädukte. Die Römer machten diese Technik später besonders berühmt und entwickelten sie in enormem Maßstab weiter.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-019","category":"Geschichte · Antike","title":"Geometrie wurde zur Beweisdisziplin","text":"Griechische Mathematiker machten systematische Beweise und logische Herleitungen zu einem zentralen Bestandteil mathematischen Denkens.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-020","category":"Geschichte · Antike","title":"Medizin löste sich teilweise von Magie","text":"Griechische medizinische Traditionen versuchten Krankheiten zunehmend durch Beobachtung natürlicher Ursachen zu erklären, auch wenn Religion und Medizin weiterhin nebeneinander existierten.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-021","category":"Geschichte · Rom","title":"Rom war fast 500 Jahre Republik","text":"Traditionell wird die römische Republik von 509 bis 27 v. Chr. datiert. Danach begann mit Augustus die Kaiserzeit.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-022","category":"Geschichte · Rom","title":"Zwei Konsuln statt eines Königs","text":"An der Spitze der Republik standen gewöhnlich zwei jährlich gewählte Konsuln. Die Aufteilung sollte verhindern, dass die höchste reguläre Macht dauerhaft bei nur einer Person lag.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-023","category":"Geschichte · Rom","title":"SPQR ist kein Fantasiecode","text":"SPQR steht für Senatus Populusque Romanus: Senat und römisches Volk. Die Buchstaben erschienen unter anderem auf militärischen Standarten und sind bis heute mit Rom verbunden.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/49/government-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-024","category":"Geschichte · Rom","title":"Rom war demokratisch und oligarchisch zugleich","text":"Römische Bürger konnten in Versammlungen Gesetze beschließen, doch der aristokratisch geprägte Senat besaß enormen Einfluss. Die Republik war deshalb keine moderne Demokratie.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-025","category":"Geschichte · Rom","title":"Senatoren waren leicht zu erkennen","text":"Römische Senatoren demonstrierten ihren Rang unter anderem mit besonderen Kleidungsmerkmalen, Ringen und Schuhen. Statussymbole sind also wirklich keine Erfindung von LinkedIn.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/49/government-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-026","category":"Geschichte · Rom","title":"Römischer Beton war ein Gamechanger","text":"Die Römer erfanden Beton nicht, nutzten ihn aber ab dem späten republikanischen Zeitalter besonders innovativ. Vulkanisches Material wie Pozzolan half bei widerstandsfähigem Mörtel.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-027","category":"Geschichte · Rom","title":"Beton ermöglichte riesige Innenräume","text":"Mit römischem Beton konnten Gewölbe und Kuppeln gebaut werden, ohne überall massive Steinblöcke oder Säulenreihen zu benötigen.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-028","category":"Geschichte · Rom","title":"Triumphbögen waren politische Medien","text":"Triumphbögen feierten militärische und politische Erfolge mit Architektur und Reliefbildern. Monumentale Öffentlichkeitsarbeit gab es lange vor Plakatwänden.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-029","category":"Geschichte · Rom","title":"Thermen waren soziale Netzwerke","text":"Römische Bäder dienten nicht nur der Körperpflege. Sie waren Orte für Sport, Gespräche, Geschäftskontakte, Entspannung und Klatsch.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/48/daily-life-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-030","category":"Geschichte · Rom","title":"Wagenrennen hatten Fangruppen","text":"Römische Wagenrennen besaßen farblich gekennzeichnete Rennställe beziehungsweise Parteien. Anhänger konnten ihre Teams leidenschaftlich und gelegentlich gewalttätig unterstützen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/48/daily-life-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-031","category":"Geschichte · Rom","title":"Wagenlenker konnten reich werden","text":"Erfolgreiche Wagenlenker konnten durch Preisgelder enorme Summen verdienen und zu gefeierten Publikumslieblingen werden.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/48/daily-life-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-032","category":"Geschichte · Rom","title":"Saturnalien stellten Regeln auf den Kopf","text":"Während der Saturnalien gehörten Rollentausch, ausgelassene Feiern und gelockerte gesellschaftliche Regeln zum Fest. Rom hatte also eine offiziell genehmigte Phase kontrollierten Chaos.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/48/daily-life-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-033","category":"Geschichte · Rom","title":"Brot und Spiele hatte politische Bedeutung","text":"Öffentliche Unterhaltung und Versorgung spielten eine wichtige Rolle im Verhältnis zwischen Herrschenden und Bevölkerung. Spiele waren deshalb weit mehr als bloßer Zeitvertreib.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/48/daily-life-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-034","category":"Geschichte · Rom","title":"Gladiatoren waren nicht jeden Tag dran","text":"Gladiatorenkämpfe waren besondere Veranstaltungen, nicht die tägliche Standardbeschäftigung jedes Römers. Theater, Wagenrennen, Bäder und religiöse Feste gehörten ebenso zur Unterhaltung.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/48/daily-life-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-035","category":"Geschichte · Rom","title":"Die Republik hatte viele Ämter","text":"Neben den Konsuln existierten zahlreiche weitere Magistrate, darunter Prätoren, Quästoren und Ädilen, mit unterschiedlichen Verwaltungs- und Rechtsaufgaben.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/49/government-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-036","category":"Geschichte · Rom","title":"Zwölftafelgesetz als frühe Rechtsbasis","text":"Die Zwölftafeln aus dem 5. Jahrhundert v. Chr. gehörten zu den grundlegenden schriftlich fixierten Rechtsquellen Roms.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/49/government-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-037","category":"Geschichte · Rom","title":"Augustus behielt republikanische Kulissen","text":"Augustus stellte seine Herrschaft offiziell als Wiederherstellung der Republik dar, konzentrierte tatsächlich aber entscheidende Macht bei sich. Politik verstand schon damals Branding.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-038","category":"Geschichte · Rom","title":"Kaiserbilder waren Propaganda","text":"Porträts der Kaiser auf Statuen, Münzen und anderen Medien verbreiteten ein kontrolliertes öffentliches Herrscherbild im ganzen Reich.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/de/essays/the-julio-claudian-dynasty-27-b-c-68-a-d","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-039","category":"Geschichte · Rom","title":"Claudius baute Infrastruktur","text":"Unter Kaiser Claudius wurden große öffentliche Bauprojekte vorangetrieben, darunter Aquädukte, Kanäle und der Ausbau des Hafens von Ostia.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/de/essays/the-julio-claudian-dynasty-27-b-c-68-a-d","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-040","category":"Geschichte · Rom","title":"Römische Freizeit begann teils früh","text":"Für manche wohlhabende Römer konzentrierten sich Geschäfte auf den Vormittag; der Nachmittag konnte Bädern, Spielen oder anderen Freizeitaktivitäten gehören.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/637/roman-daily-life/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"history-006","category":"Geschichte · Ägypten","title":"Hieroglyphen waren nicht einfach Bilder","text":"Ägyptische Hieroglyphen konnten Laute, ganze Wörter oder Bedeutungszusätze darstellen. Das Schriftsystem war erheblich komplexer als eine Sammlung kleiner Bildchen.","source":"Smithsonian Institution","sourceUrl":"https://www.si.edu/spotlight/ancient-egypt","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"history-007","category":"Geschichte · Ägypten","title":"Mumifizierung war religiös geprägt","text":"Die Erhaltung des Körpers hing mit altägyptischen Vorstellungen vom Tod und Weiterleben zusammen. Mumifizierung war deshalb Teil eines größeren religiösen Systems.","source":"British Museum","sourceUrl":"https://www.britishmuseum.org/collection/galleries/egyptian-death-and-afterlife-mummies","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"history-008","category":"Geschichte · Ägypten","title":"Nicht nur Pharaonen wurden mumifiziert","text":"Mumifizierung war keineswegs ausschließlich Herrschern vorbehalten. Je nach Epoche und sozialem Status wurden auch andere Menschen und sogar Tiere mumifiziert.","source":"British Museum","sourceUrl":"https://www.britishmuseum.org/collection/galleries/egyptian-death-and-afterlife-mummies","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"epoch-001","category":"Zeitepochen · Mesopotamien","title":"Schrift begann mit Brot und Bier","text":"Die älteste bekannte Keilschrift entstand vor 3200 v. Chr. in Mesopotamien zunächst als Verwaltungswerkzeug. Schreiber hielten damit unter anderem Brot- und Bierrationen fest. Ausgerechnet Buchhaltung half also dabei, eine der ältesten Schrifttraditionen der Welt groß zu machen.","source":"British Museum","sourceUrl":"https://www.britishmuseum.org/blog/how-write-cuneiform","verified":true,"tone":"curious","sensitive":false,"tags":["Mesopotamien","Schrift","Uruk"]},{"id":"wissen-101","category":"Wusstest du eigentlich …?","title":"Sogar Hunde tauchten in antiken Rationslisten auf","text":"Eine erhaltene Tontafel aus der Zeit der dritten Dynastie von Ur listet Brot- und Bierrationen auf – und nennt dabei neben Menschen sogar Hunde. Bürokratie machte offenbar schon vor rund 4.000 Jahren vor Haustieren nicht Halt.","source":"British Museum","sourceUrl":"https://www.britishmuseum.org/collection/object/W_1896-0406-52","verified":true,"tone":"curious","sensitive":false,"tags":["Mesopotamien","Alltag","Kurios"]},{"id":"epoch-002","category":"Zeitepochen · Azteken","title":"Tenochtitlan war eine Wasserstadt","text":"Tenochtitlan lag im Texcoco-See und war von Straßen und Kanälen durchzogen. Drei Dämme verbanden die Stadt mit dem Festland, zwei Aquädukte brachten Frischwasser hinein. Menschen und Waren bewegten sich in großer Zahl per Kanu durch die Stadt.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/it/essays/tenochtitlan","verified":true,"tone":"curious","sensitive":false,"tags":["Azteken","Stadt","Amerika"]},{"id":"wissen-102","category":"Wusstest du eigentlich …?","title":"Mitten in Tenochtitlan gab es sogar Zoos","text":"Die Paläste der Herrscher von Tenochtitlan umfassten nicht nur Gärten, sondern auch Volieren und Zoos. Das gehört zu den Details, die das Bild einer hochkomplexen Großstadt deutlich besser treffen als das übliche Schulbuch-Kästchen.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/it/essays/tenochtitlan","verified":true,"tone":"curious","sensitive":false,"tags":["Azteken","Tenochtitlan","Kurios"]},{"id":"epoch-003","category":"Zeitepochen · Japan","title":"Japan war in der Edo-Zeit nicht völlig abgeschottet","text":"Während der Edo-Zeit war der Außenkontakt stark eingeschränkt, aber nicht vollständig beendet. Chinesische und niederländische Händler durften weiterhin über Nagasaki Handel treiben. Über diesen schmalen Korridor kamen Waren, Wissen und kulturelle Einflüsse ins Land.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/zh/essays/art-of-the-edo-period-1615-1868","verified":true,"tone":"curious","sensitive":false,"tags":["Japan","Edo","Handel"]},{"id":"wissen-103","category":"Wusstest du eigentlich …?","title":"Japanisches Porzellan wurde für Europa maßgeschneidert","text":"Niederländische Händler ließen japanische Töpfer im 17. und 18. Jahrhundert Keramik gezielt für europäische Geschmäcker herstellen. Dafür wurden sogar Modelle und westliche Gefäßformen nach Japan geschickt, damit sie dort nachgebaut werden konnten.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/toah/hd/jpor/ho_2002.447.123.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Japan","Edo","Porzellan"]},{"id":"epoch-004","category":"Zeitepochen · Skandinavien","title":"Skandinavien war lange fast menschenleer","text":"Nach dem Ende der letzten Eiszeit wurde Skandinavien erst vergleichsweise spät dauerhaft besiedelt. Die ersten Menschen kamen dort erst nach etwa 13.500 v. Chr. an, als sich Eisflächen zurückzogen und neue Landschaften entstanden.","source":"Smithsonian Libraries","sourceUrl":"https://www.si.edu/object/siris_sil_1078812","verified":true,"tone":"curious","sensitive":false,"tags":["Skandinavien","Steinzeit","Besiedlung"]},{"id":"wissen-104","category":"Wusstest du eigentlich …?","title":"Steinzeitliche Küsten liegen heute unter Wasser","text":"Nach der Eiszeit stieg der Meeresspiegel stark an. Küstenplätze, an denen Menschen damals lebten, liegen heute teils unter dem Meer. Archäologen suchen deshalb nicht nur an Land nach frühen Siedlungsspuren.","source":"National Park Service","sourceUrl":"https://www.nps.gov/orgs/1539/learn-about-archeology.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Steinzeit","Archäologie","Meer"]},{"id":"epoch-005","category":"Zeitepochen · Wikingerzeit","title":"Wikinger waren nicht nur Plünderer","text":"Die Wikingerzeit bestand nicht nur aus Überfällen. Archäologische und historische Forschung behandelt ebenso Landwirtschaft, Handwerk, Handel, Städte, Schifffahrt und Alltagsleben. Der dauerplündernde Krieger ist also nur ein Ausschnitt einer viel größeren Gesellschaft.","source":"Smithsonian Institution","sourceUrl":"https://www.si.edu/object/vikings-north-atlantic-saga-edited-william-w-fitzhugh-and-elisabeth-i-ward%3Asiris_sil_593550","verified":true,"tone":"curious","sensitive":false,"tags":["Wikinger","Alltag","Handel"]},{"id":"entstehung-101","category":"Wie entstand eigentlich …?","title":"… die Zahnbürste?","text":"Zähne putzen ist viel älter als Plastikgriffe und Nylon. Schon um 3000 v. Chr. nutzten Menschen ausgefranste Zweige als Kau- und Reibstäbe. Eine bürstenähnliche Form mit Tierborsten ist für China ab 1498 belegt; Nylonborsten kamen 1938 auf den Markt.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/categories/technology/item/who-invented-the-toothbrush-and-when-was-it-invented/","verified":true,"tone":"curious","sensitive":false,"tags":["Alltag","Erfindungen","Hygiene"]},{"id":"entstehung-102","category":"Wie entstand eigentlich …?","title":"… der Einkaufswagen?","text":"Der moderne Einkaufswagen entstand aus einem sehr simplen Problem: Kunden konnten nur so viel kaufen, wie sie tragen konnten. Sylvan Goldman führte 1937 einen Wagen mit Körben ein; Orla Watson entwickelte 1946 die ineinanderschiebbaren Wagen, die heute vor fast jedem Supermarkt stehen.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories/reinventing-shopping-cart","verified":true,"tone":"curious","sensitive":false,"tags":["Einkaufen","Erfindungen","Supermarkt"]},{"id":"wissen-105","category":"Wusstest du eigentlich …?","title":"Einkaufswagen sollten ursprünglich mehr verkaufen helfen","text":"Kühlschränke machten größere Lebensmitteleinkäufe praktischer. Händler erkannten schnell, dass Kunden mehr kaufen konnten, wenn sie ihre Waren nicht mehr im Arm tragen mussten. Der Einkaufswagen war also Komfort und Verkaufsstrategie zugleich.","source":"National Museum of American History","sourceUrl":"https://www.americanhistory.si.edu/explore/exhibitions/object-project/online/refrigerators/cart","verified":true,"tone":"curious","sensitive":false,"tags":["Einkaufen","Alltag","Wirtschaftsgeschichte"]},{"id":"entstehung-103","category":"Wie entstand eigentlich …?","title":"… der moderne Aufzug?","text":"Aufzüge gab es in primitiver Form schon in der Antike. Der entscheidende Schritt zur modernen Personenbeförderung war aber der Sicherheitsaufzug des 19. Jahrhunderts: Erst Systeme, die einen Absturz bei Seilbruch verhindern konnten, machten hohe Gebäude für normale Nutzer wirklich praktikabel.","source":"Smithsonian Libraries","sourceUrl":"https://www.si.edu/object/tell-me-about-elevators-edited-paul-anderson%3Asiris_sil_783584","verified":true,"tone":"curious","sensitive":false,"tags":["Erfindungen","Aufzug","Industrialisierung"]},{"id":"wissen-106","category":"Wusstest du eigentlich …?","title":"Beulah Henry bekam 49 Patente","text":"Die amerikanische Erfinderin Beulah Louise Henry entwickelte über Jahrzehnte Dutzende Ideen und erhielt insgesamt 49 Patente. Sie arbeitete an sehr unterschiedlichen Dingen und wurde zeitweise sogar als „Lady Edison“ bezeichnet.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories/exploring-history-women-inventors","verified":true,"tone":"curious","sensitive":false,"tags":["Erfindungen","Frauen","20. Jahrhundert"]},{"id":"wissen-107","category":"Wusstest du eigentlich …?","title":"Frauen waren auch Piraten","text":"Die Vorstellung, Piraterie sei ausschließlich Männersache gewesen, hält historisch nicht stand. Der US National Park Service verweist auf mindestens drei weibliche Piraten, die in der Geschichte der Vereinigten Staaten auftauchen.","source":"National Park Service","sourceUrl":"https://www.nps.gov/articles/did-you-know-women-s-history.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Piraten","Frauen","Kurios"]},{"id":"wissen-108","category":"Wusstest du eigentlich …?","title":"In manchen Häusern durfte das Feuer über Generationen nicht ausgehen","text":"Bevor Heizung und elektrisches Licht selbstverständlich wurden, war die offene Feuerstelle Zentrum des Hauses: Wärme, Licht und Kochstelle zugleich. In manchen Familien wurde das Herdfeuer so wichtig genommen, dass es möglichst dauerhaft am Brennen gehalten wurde.","source":"Smithsonian Magazine","sourceUrl":"https://www.smithsonianmag.com/innovation/ten-surprising-facts-about-everyday-household-objects-180974566/","verified":true,"tone":"curious","sensitive":false,"tags":["Mittelalter","Alltag","Wohnen"]},{"id":"wissen-109","category":"Wusstest du eigentlich …?","title":"Ein archäologischer Fundplatz kann an einem Tag verschwinden","text":"Stürme und Hurrikane können archäologische Fundstellen in sehr kurzer Zeit freilegen, verschütten oder vollständig abtragen. Der National Park Service weist darauf hin, dass manche Plätze innerhalb eines einzigen Tages unter mehreren Fuß Sand oder Erde verschwinden können.","source":"National Park Service","sourceUrl":"https://www.nps.gov/orgs/1539/learn-about-archeology.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Archäologie","Natur","Kurios"]},{"id":"wissen-110","category":"Wusstest du eigentlich …?","title":"Der erste Einkaufswagen war fast ein Klappstuhl auf Rädern","text":"Sylvan Goldmans früher Einkaufswagen bestand aus einem klappbaren Rahmen mit zwei Körben. Erst später entstand die heute vertraute ineinanderschiebbare Bauform. Der Supermarktklassiker begann also erstaunlich improvisiert.","source":"Smithsonian Institution","sourceUrl":"https://www.si.edu/object/nmah_1194185","verified":true,"tone":"curious","sensitive":false,"tags":["Einkaufen","Design","Kurios"]},{"id":"entstehung-104","category":"Wie entstand eigentlich …?","title":"… elektrischer Weihnachtsschmuck?","text":"Thomas Edison zeigte 1880 eine frühe elektrische Lichterkette, Edward Johnson dekorierte 1882 einen Weihnachtsbaum elektrisch. Später halfen weitere Anbieter dabei, die Technik bezahlbarer und alltagstauglicher zu machen.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/categories/technology/","verified":true,"tone":"curious","sensitive":false,"tags":["Weihnachten","Erfindungen","Elektrizität"]},{"id":"wissen-111","category":"Wusstest du eigentlich …?","title":"Das vertraute Haushaltsleben ist historisch Luxus","text":"Weiche Kissen, gepolsterte Möbel, zuverlässige Beleuchtung und angenehm temperierte Räume wirken heute banal. Viele dieser Dinge waren über lange Zeit teuer, unbequem oder nur Wohlhabenden zugänglich. Ein durchschnittlicher moderner Haushalt besitzt Komfort, von dem selbst frühere Eliten nur eingeschränkt profitieren konnten.","source":"Smithsonian Magazine","sourceUrl":"https://www.smithsonianmag.com/innovation/ten-surprising-facts-about-everyday-household-objects-180974566/","verified":true,"tone":"curious","sensitive":false,"tags":["Alltag","Wohnen","Sozialgeschichte"]},{"id":"tier-001","category":"Tier im Fokus","title":"Blauwal","text":"Bis rund 30 Meter lang und deutlich über 100 Tonnen schwer: Blauwale sind die größten bekannten Tiere der Erdgeschichte. Trotz dieser Dimensionen leben sie fast ausschließlich von winzigem Krill und können viele Jahrzehnte alt werden.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Blauwal"],"topicKey":"animal-blauwal"},{"id":"tier-002","category":"Tier im Fokus","title":"Afrikanischer Savannenelefant","text":"Große Bullen können mehr als sechs Tonnen wiegen. Elefanten sind Pflanzenfresser, verbringen einen großen Teil des Tages mit Fressen und Trinken und können in freier Wildbahn mehrere Jahrzehnte leben.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Afrikanischer Savannenelefant"],"topicKey":"animal-afrikanischer-savannenelefant"},{"id":"tier-003","category":"Tier im Fokus","title":"Asiatischer Elefant","text":"Asiatische Elefanten sind etwas kleiner als ihre afrikanischen Verwandten. Ein erwachsenes Tier kann täglich weit über 100 Kilogramm Pflanzenmaterial aufnehmen; Gras, Blätter, Rinde und Früchte stehen auf dem Speiseplan.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Asiatischer Elefant"],"topicKey":"animal-asiatischer-elefant"},{"id":"tier-004","category":"Tier im Fokus","title":"Gepard","text":"Geparden sind die schnellsten Landsäuger, aber ihre Höchstgeschwindigkeit halten sie nur kurz durch. In freier Wildbahn liegt ihre durchschnittliche Lebensspanne deutlich unter der vieler großer Katzen.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Gepard"],"topicKey":"animal-gepard"},{"id":"tier-005","category":"Tier im Fokus","title":"Löwe","text":"Löwen leben ungewöhnlich sozial für Katzen. Weibchen bilden den Kern eines Rudels und jagen häufig gemeinsam; wilde Löwen erreichen meist keine 20 Jahre.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Löwe"],"topicKey":"animal-lowe"},{"id":"tier-006","category":"Tier im Fokus","title":"Tiger","text":"Tiger sind die größten lebenden Katzen. Sie leben überwiegend allein, jagen vor allem größere Huftiere und können je nach Unterart weit über 200 Kilogramm wiegen.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Tiger"],"topicKey":"animal-tiger"},{"id":"tier-007","category":"Tier im Fokus","title":"Jaguar","text":"Jaguare sind die größten Katzen Amerikas. Sie besitzen im Verhältnis zur Körpergröße extrem kräftige Kiefer und jagen unter anderem Pekaris, Hirsche, Schildkröten und Kaimane.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Jaguar"],"topicKey":"animal-jaguar"},{"id":"tier-008","category":"Tier im Fokus","title":"Schneeleopard","text":"Schneeleoparden leben in Hochgebirgen Zentralasiens. Ihr langer Schwanz hilft beim Balancieren und kann beim Ruhen wie ein Schal um den Körper gelegt werden.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Schneeleopard"],"topicKey":"animal-schneeleopard"},{"id":"tier-009","category":"Tier im Fokus","title":"Puma","text":"Pumas besitzen eines der größten Verbreitungsgebiete aller Landsäuger der westlichen Hemisphäre. Sie können trotz ihrer Größe nicht wie Löwen brüllen, sondern schnurren, fauchen und schreien.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Puma"],"topicKey":"animal-puma"},{"id":"tier-010","category":"Tier im Fokus","title":"Wolf","text":"Wölfe leben meist in Familienverbänden. Ihr Speiseplan reicht von großen Huftieren bis zu kleineren Beutetieren; die Größe eines Rudels hängt stark von Lebensraum und Nahrungsangebot ab.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Wolf"],"topicKey":"animal-wolf"},{"id":"tier-011","category":"Tier im Fokus","title":"Polarfuchs","text":"Polarfüchse sind an extreme Kälte angepasst. Ihr Winterfell isoliert so gut, dass sie Temperaturen weit unter dem Gefrierpunkt aushalten und selbst kleine Ohren helfen, Wärmeverlust zu verringern.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Polarfuchs"],"topicKey":"animal-polarfuchs"},{"id":"tier-012","category":"Tier im Fokus","title":"Fennek","text":"Der Fennek ist der kleinste Fuchs der Welt. Seine riesigen Ohren helfen nicht nur beim Hören von Beute im Sand, sondern auch dabei, überschüssige Körperwärme abzugeben.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Fennek"],"topicKey":"animal-fennek"},{"id":"tier-013","category":"Tier im Fokus","title":"Braunbär","text":"Braunbären sind Allesfresser. Je nach Region reicht ihr Speiseplan von Gräsern und Beeren über Insekten bis zu Fisch und größeren Säugetieren.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Braunbär"],"topicKey":"animal-braunbar"},{"id":"tier-014","category":"Tier im Fokus","title":"Koala","text":"Koalas ernähren sich fast ausschließlich von Eukalyptusblättern. Weil diese Nahrung energiearm ist, ruhen oder schlafen sie einen Großteil des Tages.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Koala"],"topicKey":"animal-koala"},{"id":"tier-015","category":"Tier im Fokus","title":"Roter Panda","text":"Rote Pandas sind trotz ihres Namens nicht eng mit dem Großen Panda verwandt. Bambus macht den größten Teil ihrer Nahrung aus, ergänzt durch Früchte, Insekten und gelegentlich kleine Tiere.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Roter Panda"],"topicKey":"animal-roter-panda"},{"id":"tier-016","category":"Tier im Fokus","title":"Orang-Utan","text":"Orang-Utans verbringen den größten Teil ihres Lebens in Bäumen. Sie fressen vor allem Früchte, aber auch Blätter, Rinde und Insekten und können in menschlicher Obhut mehrere Jahrzehnte alt werden.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Orang-Utan"],"topicKey":"animal-orang-utan"},{"id":"tier-017","category":"Tier im Fokus","title":"Gorilla","text":"Gorillas sind die größten heute lebenden Primaten. Trotz ihrer Kraft ernähren sie sich überwiegend pflanzlich und verbringen viele Stunden am Tag mit Fressen.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Gorilla"],"topicKey":"animal-gorilla"},{"id":"tier-018","category":"Tier im Fokus","title":"Schimpanse","text":"Schimpansen nutzen Werkzeuge, pflegen komplexe soziale Beziehungen und jagen gelegentlich gemeinsam kleinere Säugetiere. Sie können über 40 Jahre alt werden.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Schimpanse"],"topicKey":"animal-schimpanse"},{"id":"tier-019","category":"Tier im Fokus","title":"Bonobo","text":"Bonobos sind nahe Verwandte der Schimpansen, unterscheiden sich aber deutlich in ihrem Sozialverhalten. Konflikte werden in ihren Gruppen häufig durch soziale Kontakte entschärft.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Bonobo"],"topicKey":"animal-bonobo"},{"id":"tier-020","category":"Tier im Fokus","title":"Gibbon","text":"Gibbons bewegen sich mit langen Armen schwingend durch Baumkronen. Ihre Duettgesänge können über weite Entfernung gehört werden und helfen Paaren, ihr Revier zu markieren.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Gibbon"],"topicKey":"animal-gibbon"},{"id":"tier-021","category":"Tier im Fokus","title":"Erdmännchen","text":"Erdmännchen leben in Gruppen mit klarer Arbeitsteilung. Während einige Tiere nach Nahrung suchen, halten andere auf erhöhten Punkten Wache.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Erdmännchen"],"topicKey":"animal-erdmannchen"},{"id":"tier-022","category":"Tier im Fokus","title":"Honigdachs","text":"Honigdachse sind kleine, kräftige Raubtiere mit sehr widerstandsfähiger Haut. Sie fressen nahezu alles, von Insekten und Wurzeln bis zu Schlangen und kleinen Säugetieren.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Honigdachs"],"topicKey":"animal-honigdachs"},{"id":"tier-023","category":"Tier im Fokus","title":"Vielfraß","text":"Der Vielfraß ist trotz seines Namens kein Wolf, sondern ein Marder. Er ist erstaunlich kräftig und kann Beute oder Aas verwerten, das deutlich größer ist als er selbst.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Vielfraß"],"topicKey":"animal-vielfra"},{"id":"tier-024","category":"Tier im Fokus","title":"Biber","text":"Biber ernähren sich von Pflanzen, Rinde und Zweigen. Mit ihren Dämmen verändern sie ganze Landschaften und schaffen Feuchtgebiete, von denen viele andere Arten profitieren.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Biber"],"topicKey":"animal-biber"},{"id":"tier-025","category":"Tier im Fokus","title":"Seeotter","text":"Seeotter nutzen Steine als Werkzeuge, etwa um Muscheln zu öffnen. Sie besitzen kein dickes Speckpolster wie viele Meeressäuger und sind deshalb auf ihr extrem dichtes Fell angewiesen.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Seeotter"],"topicKey":"animal-seeotter"},{"id":"tier-026","category":"Tier im Fokus","title":"Flusspferd","text":"Flusspferde verbringen viel Zeit im Wasser, sind aber keine guten Langstreckenschwimmer. Nachts gehen sie an Land und fressen vor allem Gras.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Flusspferd"],"topicKey":"animal-flusspferd"},{"id":"tier-027","category":"Tier im Fokus","title":"Nashorn","text":"Nashörner sind Pflanzenfresser. Je nach Art wiegen ausgewachsene Tiere von unter einer bis weit über zwei Tonnen; ihre Hörner bestehen aus Keratin, demselben Material wie menschliche Fingernägel.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Nashorn"],"topicKey":"animal-nashorn"},{"id":"tier-028","category":"Tier im Fokus","title":"Okapi","text":"Okapis leben in den Regenwäldern der Demokratischen Republik Kongo und gehören zur Giraffenfamilie. Ihre gestreiften Beine erinnern zwar an Zebras, verwandtschaftlich sind sie ihnen aber fern.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Okapi"],"topicKey":"animal-okapi"},{"id":"tier-029","category":"Tier im Fokus","title":"Rentier","text":"Rentiere sind die einzige Hirschart, bei der normalerweise auch Weibchen Geweihe tragen. Große Herden können saisonal über enorme Entfernungen wandern.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Rentier"],"topicKey":"animal-rentier"},{"id":"tier-030","category":"Tier im Fokus","title":"Elch","text":"Elche sind die größten Vertreter der Hirsche. Sie fressen Land- und Wasserpflanzen und sind überraschend gute Schwimmer.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Elch"],"topicKey":"animal-elch"},{"id":"tier-031","category":"Tier im Fokus","title":"Alpaka","text":"Alpakas wurden in Südamerika vor allem wegen ihrer Wolle domestiziert. Sie sind kleiner als Lamas und ernähren sich überwiegend von Gräsern.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Alpaka"],"topicKey":"animal-alpaka"},{"id":"tier-033","category":"Tier im Fokus","title":"Yak","text":"Yaks sind an große Höhen angepasst. Ihr dichtes Fell schützt vor Kälte, und ihr Blut sowie ihre Atmung sind auf sauerstoffarme Gebirgsluft abgestimmt.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Yak"],"topicKey":"animal-yak"},{"id":"tier-034","category":"Tier im Fokus","title":"Moschusochse","text":"Moschusochsen leben in arktischen Regionen und tragen ein extrem dichtes Unterfell namens Qiviut. Bei Gefahr können sie einen Schutzkreis um Jungtiere bilden.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Moschusochse"],"topicKey":"animal-moschusochse"},{"id":"tier-035","category":"Tier im Fokus","title":"Känguru","text":"Große Kängurus bewegen sich mit energiesparenden Sprüngen fort. Weibchen können die Entwicklung eines Embryos verzögern, wenn bereits ein Jungtier im Beutel versorgt wird.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Känguru"],"topicKey":"animal-kanguru"},{"id":"tier-036","category":"Tier im Fokus","title":"Tasmanischer Teufel","text":"Tasmanische Teufel sind die größten heute lebenden fleischfressenden Beuteltiere. Ihr kräftiger Kiefer hilft ihnen, selbst Knochen und zähe Nahrung zu verwerten.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Tasmanischer Teufel"],"topicKey":"animal-tasmanischer-teufel"},{"id":"tier-037","category":"Tier im Fokus","title":"Schnabeltier","text":"Schnabeltiere sind Säugetiere, legen aber Eier. Männchen besitzen an den Hinterbeinen Giftsporne, und ihr Schnabel kann elektrische Signale von Beutetieren wahrnehmen.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Schnabeltier"],"topicKey":"animal-schnabeltier"},{"id":"tier-038","category":"Tier im Fokus","title":"Ameisenigel","text":"Ameisenigel gehören wie Schnabeltiere zu den eierlegenden Säugetieren. Sie fressen vor allem Ameisen und Termiten und besitzen keine Zähne.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Ameisenigel"],"topicKey":"animal-ameisenigel"},{"id":"tier-039","category":"Tier im Fokus","title":"Kaiserpinguin","text":"Kaiserpinguine sind die größten Pinguine. Während des antarktischen Winters brüten die Männchen das Ei auf ihren Füßen aus und fasten dabei über Wochen.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Kaiserpinguin"],"topicKey":"animal-kaiserpinguin"},{"id":"tier-040","category":"Tier im Fokus","title":"Albatros","text":"Große Albatrosse können Flügelspannweiten von über drei Metern erreichen. Sie nutzen Wind über dem Meer so effizient, dass sie lange Strecken mit erstaunlich wenig Flügelschlag zurücklegen.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Albatros"],"topicKey":"animal-albatros"},{"id":"tier-041","category":"Tier im Fokus","title":"Wanderfalke","text":"Wanderfalken erreichen im Sturzflug Geschwindigkeiten von weit über 300 km/h. Damit gelten sie als die schnellsten Tiere überhaupt.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Wanderfalke"],"topicKey":"animal-wanderfalke"},{"id":"tier-042","category":"Tier im Fokus","title":"Harpyie","text":"Harpyien gehören zu den kräftigsten Greifvögeln. Sie jagen in tropischen Baumkronen unter anderem Faultiere und Affen.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Harpyie"],"topicKey":"animal-harpyie"},{"id":"tier-043","category":"Tier im Fokus","title":"Sekretärvogel","text":"Sekretärvögel jagen überwiegend zu Fuß durch afrikanische Grasländer. Mit kräftigen Tritten überwältigen sie Schlangen, Insekten und kleine Wirbeltiere.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Sekretärvogel"],"topicKey":"animal-sekretarvogel"},{"id":"tier-044","category":"Tier im Fokus","title":"Kakapo","text":"Der Kakapo ist ein schwerer, flugunfähiger Papagei aus Neuseeland. Er ist nachtaktiv und kann außergewöhnlich alt werden.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Kakapo"],"topicKey":"animal-kakapo"},{"id":"tier-045","category":"Tier im Fokus","title":"Kea","text":"Keas sind neugierige Bergpapageien aus Neuseeland. Sie lösen komplexe Aufgaben und untersuchen neue Gegenstände mit einer Hartnäckigkeit, die in menschlicher Umgebung gelegentlich teuer wird.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Kea"],"topicKey":"animal-kea"},{"id":"tier-046","category":"Tier im Fokus","title":"Kolkrabe","text":"Kolkraben sind äußerst lernfähig, können Probleme lösen und andere Tiere beobachten, um an Nahrung zu gelangen. In freier Wildbahn können sie deutlich über zehn Jahre alt werden.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Kolkrabe"],"topicKey":"animal-kolkrabe"},{"id":"tier-047","category":"Tier im Fokus","title":"Afrikanischer Graupapagei","text":"Graupapageien sind für ihre Lernfähigkeit und Lautnachahmung bekannt. In menschlicher Obhut können sie mehrere Jahrzehnte leben, was ihre Haltung zu einer sehr langfristigen Verantwortung macht.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Afrikanischer Graupapagei"],"topicKey":"animal-afrikanischer-graupapagei"},{"id":"tier-048","category":"Tier im Fokus","title":"Komodowaran","text":"Komodowarane sind die größten lebenden Echsen und können über drei Meter lang werden. Sie jagen Hirsche, Wildschweine und kleinere Tiere; ihr Biss enthält Giftstoffe.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Komodowaran"],"topicKey":"animal-komodowaran"},{"id":"tier-049","category":"Tier im Fokus","title":"Salzwasserkrokodil","text":"Salzwasserkrokodile sind die größten heute lebenden Reptilien. Sehr große Männchen können mehr als fünf Meter lang werden und in Flussmündungen ebenso wie im Meer leben.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Salzwasserkrokodil"],"topicKey":"animal-salzwasserkrokodil"},{"id":"tier-050","category":"Tier im Fokus","title":"Gila-Krustenechse","text":"Die Gila-Krustenechse ist eine der wenigen giftigen Echsen. Sie bewegt sich meist langsam und speichert Fett in ihrem kräftigen Schwanz.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Gila-Krustenechse"],"topicKey":"animal-gila-krustenechse"},{"id":"tier-051","category":"Tier im Fokus","title":"Grüne Meeresschildkröte","text":"Grüne Meeresschildkröten können mehrere Jahrzehnte alt werden und weite Wanderungen zwischen Nahrungs- und Nistgebieten zurücklegen. Erwachsene Tiere fressen überwiegend Seegras und Algen.","source":"NOAA Ocean Exploration","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Grüne Meeresschildkröte"],"topicKey":"animal-grune-meeresschildkrote"},{"id":"tier-052","category":"Tier im Fokus","title":"Lederschildkröte","text":"Lederschildkröten sind die größten Meeresschildkröten. Statt eines harten Panzers besitzen sie eine lederartige Haut über einer flexiblen Knochenstruktur und fressen vor allem Quallen.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Lederschildkröte"],"topicKey":"animal-lederschildkrote"},{"id":"tier-053","category":"Tier im Fokus","title":"Riesenmanta","text":"Riesenmantas können Spannweiten von mehreren Metern erreichen. Sie sind Filtrierer und ernähren sich von Plankton und kleinen Organismen im Wasser.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Riesenmanta"],"topicKey":"animal-riesenmanta"},{"id":"tier-054","category":"Tier im Fokus","title":"Walhai","text":"Walhaie sind die größten lebenden Fische. Trotz ihrer Größe fressen sie überwiegend Plankton und kleine Fische, die sie aus dem Wasser filtern.","source":"NOAA Ocean Exploration","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Walhai"],"topicKey":"animal-walhai"},{"id":"tier-055","category":"Tier im Fokus","title":"Weißer Hai","text":"Weiße Haie sind große Spitzenprädatoren. Jungtiere fressen vor allem Fische und Rochen, größere Tiere nehmen häufiger Meeressäuger als Beute.","source":"NOAA Ocean Exploration","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Weißer Hai"],"topicKey":"animal-wei-er-hai"},{"id":"tier-056","category":"Tier im Fokus","title":"Grönlandhai","text":"Grönlandhaie wachsen extrem langsam und gehören zu den langlebigsten bekannten Wirbeltieren. Einzelne Tiere können mehrere Jahrhunderte alt werden.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Grönlandhai"],"topicKey":"animal-gronlandhai"},{"id":"tier-057","category":"Tier im Fokus","title":"Hammerhai","text":"Hammerhaie besitzen einen stark verbreiterten Kopf mit weit auseinanderliegenden Augen und Sinnesorganen. Diese Form verbessert unter anderem die Wahrnehmung elektrischer Signale von Beute.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Hammerhai"],"topicKey":"animal-hammerhai"},{"id":"tier-059","category":"Tier im Fokus","title":"Nautilus","text":"Nautilusse besitzen eine gekammerte Schale und regulieren ihren Auftrieb über Gas und Flüssigkeit in diesen Kammern. Ihre Abstammungslinie reicht Hunderte Millionen Jahre zurück.","source":"NOAA Ocean Exploration","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Nautilus"],"topicKey":"animal-nautilus"},{"id":"tier-060","category":"Tier im Fokus","title":"Riesenassel","text":"Riesenasseln leben in großer Tiefe und gehören zu den Krebstieren. Sie können sehr lange ohne Nahrung auskommen, wenn in ihrem nahrungsarmen Lebensraum gerade nichts Verwertbares vorbeikommt.","source":"Smithsonian National Zoo / Animal Diversity Web","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Riesenassel"],"topicKey":"animal-riesenassel"},{"id":"tierbeziehung-001","category":"Ungewöhnliche Tierbeziehungen","title":"Gepard & Hund","text":"In einigen Zoos werden junge Geparden mit ruhigen Haushunden zusammengebracht. Die Hunde können den scheuen Katzen als soziale Orientierung dienen und helfen, neue Situationen entspannter zu erleben.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-gepard-hund"},{"id":"tierbeziehung-002","category":"Ungewöhnliche Tierbeziehungen","title":"Kojote & Dachs","text":"Kojoten und Dachse können gemeinsam jagen: Der Dachs verfolgt Beute unter der Erde, während der Kojote oberirdisch wartet. Beide können von der Zusammenarbeit profitieren.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-kojote-dachs"},{"id":"tierbeziehung-003","category":"Ungewöhnliche Tierbeziehungen","title":"Pistolenkrebs & Grundel","text":"Pistolenkrebse graben Wohnhöhlen, während manche Grundeln Wache halten. Der fast blinde Krebs bleibt über seine Fühler mit dem Fisch in Kontakt und reagiert auf dessen Warnsignale.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-pistolenkrebs-grundel"},{"id":"tierbeziehung-004","category":"Ungewöhnliche Tierbeziehungen","title":"Clownfisch & Seeanemone","text":"Clownfische finden Schutz zwischen den Nesseltentakeln bestimmter Seeanemonen. Im Gegenzug können sie die Anemone mit Nahrung versorgen und verteidigen.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-clownfisch-seeanemone"},{"id":"tierbeziehung-005","category":"Ungewöhnliche Tierbeziehungen","title":"Putzerlippfisch & Riffbewohner","text":"Putzerlippfische betreiben regelrechte Reinigungsstationen. Größere Fische kommen vorbei und lassen Parasiten sowie abgestorbene Haut entfernen.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-putzerlippfisch-riffbewohner"},{"id":"tierbeziehung-006","category":"Ungewöhnliche Tierbeziehungen","title":"Ameise & Akazie","text":"Bestimmte Akazien bieten Ameisen Nahrung und Wohnraum. Die Ameisen verteidigen dafür die Pflanze aggressiv gegen Pflanzenfresser und konkurrierende Vegetation.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-ameise-akazie"},{"id":"tierbeziehung-007","category":"Ungewöhnliche Tierbeziehungen","title":"Ochsenpicker & große Säuger","text":"Ochsenpicker sitzen auf großen afrikanischen Säugetieren und fressen Zecken sowie andere kleine Tiere. Die Beziehung ist nützlich, aber nicht immer völlig harmlos, weil die Vögel auch an Wunden picken können.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-ochsenpicker-gro-e-sauger"},{"id":"tierbeziehung-008","category":"Ungewöhnliche Tierbeziehungen","title":"Wolf & Rabe","text":"Raben folgen häufig Wölfen und profitieren von Beuteresten. Beobachtungen zeigen außerdem, dass die Vögel Wölfe auf mögliche Nahrung aufmerksam machen können.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-wolf-rabe"},{"id":"tierbeziehung-009","category":"Ungewöhnliche Tierbeziehungen","title":"Mensch & Honiganzeiger","text":"In Teilen Afrikas führen Große Honiganzeiger Menschen zu Bienennestern. Nach dem Öffnen des Nestes profitieren die Vögel von Wachs und Resten, an die sie allein schwer herankämen.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-mensch-honiganzeiger"},{"id":"tierbeziehung-010","category":"Ungewöhnliche Tierbeziehungen","title":"Einsiedlerkrebs & Seeanemone","text":"Manche Einsiedlerkrebse tragen Seeanemonen auf ihrem Schneckenhaus. Der Krebs bekommt zusätzlichen Schutz, die Anemone wiederum wird zu neuen Futterplätzen transportiert.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-einsiedlerkrebs-seeanemone"},{"id":"tierbeziehung-011","category":"Ungewöhnliche Tierbeziehungen","title":"Seegurke & Perlfisch","text":"Einige Perlfische suchen Schutz im Körper von Seegurken. Für den Fisch ist das ein sicherer Unterschlupf; für die Seegurke ist die Beziehung je nach Art neutral bis unangenehm.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-seegurke-perlfisch"},{"id":"tierbeziehung-013","category":"Ungewöhnliche Tierbeziehungen","title":"Nilkrokodil & Vogelmythos","text":"Die berühmte Geschichte, kleine Vögel würden regelmäßig Zähne von Krokodilen reinigen, ist viel schlechter belegt als oft behauptet. Ein schönes Beispiel dafür, dass eine attraktive Tiergeschichte nicht automatisch eine gesicherte Partnerschaft ist.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-nilkrokodil-vogelmythos"},{"id":"tierbeziehung-014","category":"Ungewöhnliche Tierbeziehungen","title":"Blattlaus & Ameise","text":"Viele Ameisen 'melken' Blattläuse nach zuckerreichem Honigtau und schützen sie im Gegenzug vor Fressfeinden. Eine Art winzige Viehzucht, nur mit deutlich weniger Papierkram.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-blattlaus-ameise"},{"id":"tierbeziehung-015","category":"Ungewöhnliche Tierbeziehungen","title":"Termite & Darmmikroben","text":"Termiten können Holz nur deshalb so effizient nutzen, weil Mikroorganismen im Verdauungssystem beim Abbau von Zellulose helfen. Das Tier lebt also mit einem kompletten Verdauungsteam zusammen.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-termite-darmmikroben"},{"id":"tierbeziehung-017","category":"Ungewöhnliche Tierbeziehungen","title":"Wiederkäuer & Pansenmikroben","text":"Kühe, Schafe und andere Wiederkäuer verdauen Zellulose nicht allein. Milliarden Mikroorganismen im Pansen zerlegen Pflanzenmaterial und machen die darin gebundene Energie verfügbar.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-wiederkauer-pansenmikroben"},{"id":"tierbeziehung-018","category":"Ungewöhnliche Tierbeziehungen","title":"Faultier & Fellalgen","text":"Im Fell von Faultieren wachsen Algen, die dem Fell einen grünlichen Ton geben können. Außerdem lebt dort eine ganze Gemeinschaft aus kleinen Organismen – ein mobiles Mini-Ökosystem.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-faultier-fellalgen"},{"id":"tierbeziehung-019","category":"Ungewöhnliche Tierbeziehungen","title":"Nacktmull & Kolonie","text":"Nacktmulle leben in hochsozialen Kolonien mit einer fortpflanzenden Königin und vielen nicht fortpflanzenden Helfern. Ihr Sozialleben erinnert stärker an soziale Insekten als an typische Säugetiere.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-nacktmull-kolonie"},{"id":"tierbeziehung-020","category":"Ungewöhnliche Tierbeziehungen","title":"Kaiserschnurrbart-Tamarin & Gruppe","text":"Bei mehreren Krallenaffenarten tragen Männchen und andere Gruppenmitglieder Jungtiere einen großen Teil des Tages herum. Nachwuchsbetreuung ist dort deutlich mehr Teamarbeit als Einzeljob.","source":"Smithsonian / zoologische Fachquellen","sourceUrl":"https://nationalzoo.si.edu/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Partnerschaft"],"topicKey":"relationship-kaiserschnurrbart-tamarin-gruppe"},{"id":"person-001","category":"Wer ist eigentlich …?","title":"Steve Irwin","text":"Australischer Tierfilmer und Naturschützer. Er wuchs im Reptilienpark seiner Eltern auf, half schon als Kind beim Umgang mit Krokodilen und wurde mit „The Crocodile Hunter“ weltweit bekannt.","source":"Australia Zoo","sourceUrl":"https://australiazoo.com.au/about-us/the-irwins/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Steve Irwin"],"topicKey":"person-steve-irwin"},{"id":"person-002","category":"Wer ist eigentlich …?","title":"Marie Curie","text":"Physikerin und Chemikerin, die Radioaktivität erforschte und Polonium sowie Radium mitentdeckte. Sie war der erste Mensch mit zwei Nobelpreisen in unterschiedlichen Naturwissenschaften.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Marie Curie"],"topicKey":"person-marie-curie"},{"id":"person-003","category":"Wer ist eigentlich …?","title":"Albert Einstein","text":"Physiker, bekannt für Relativitätstheorie und Beiträge zur Quantentheorie. Seinen Nobelpreis erhielt er ausdrücklich für Arbeiten zum photoelektrischen Effekt.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Albert Einstein"],"topicKey":"person-albert-einstein"},{"id":"person-004","category":"Wer ist eigentlich …?","title":"Alexander Fleming","text":"Bakteriologe, dessen Beobachtung von Penicillin den Weg für moderne Antibiotika ebnete. 1945 erhielt er gemeinsam mit Chain und Florey den Medizin-Nobelpreis.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Alexander Fleming"],"topicKey":"person-alexander-fleming"},{"id":"person-005","category":"Wer ist eigentlich …?","title":"Rosalind Franklin","text":"Chemikerin und Röntgenkristallografin. Ihre Arbeiten an DNA-Strukturen lieferten entscheidende Daten für das Verständnis der Doppelhelix.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Rosalind Franklin"],"topicKey":"person-rosalind-franklin"},{"id":"person-006","category":"Wer ist eigentlich …?","title":"Niels Bohr","text":"Dänischer Physiker, der entscheidend zum Verständnis von Atomen und Quantentheorie beitrug und 1922 den Physik-Nobelpreis erhielt.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Niels Bohr"],"topicKey":"person-niels-bohr"},{"id":"person-007","category":"Wer ist eigentlich …?","title":"Max Planck","text":"Deutscher Physiker und Begründer der Quantentheorie. Seine Idee, Energie werde in diskreten Portionen übertragen, veränderte die Physik grundlegend.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Max Planck"],"topicKey":"person-max-planck"},{"id":"person-008","category":"Wer ist eigentlich …?","title":"Werner Heisenberg","text":"Deutscher Physiker und einer der wichtigsten Begründer der Quantenmechanik. Bekannt ist vor allem die Unschärferelation.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Werner Heisenberg"],"topicKey":"person-werner-heisenberg"},{"id":"person-009","category":"Wer ist eigentlich …?","title":"Erwin Schrödinger","text":"Österreichischer Physiker, dessen Wellengleichung zu den Grundlagen der Quantenmechanik gehört. Die berühmte 'Schrödingers Katze' war ursprünglich ein Gedankenexperiment.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Erwin Schrödinger"],"topicKey":"person-erwin-schrodinger"},{"id":"person-010","category":"Wer ist eigentlich …?","title":"Enrico Fermi","text":"Italienisch-amerikanischer Physiker. Er arbeitete an Kernphysik, Neutronen und leitete das Team, das 1942 die erste kontrollierte nukleare Kettenreaktion erreichte.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Enrico Fermi"],"topicKey":"person-enrico-fermi"},{"id":"person-011","category":"Wer ist eigentlich …?","title":"Richard Feynman","text":"US-Physiker, bekannt für Arbeiten zur Quantenelektrodynamik und seine außergewöhnlich anschauliche Art, Physik zu erklären.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Richard Feynman"],"topicKey":"person-richard-feynman"},{"id":"person-012","category":"Wer ist eigentlich …?","title":"Dorothy Crowfoot Hodgkin","text":"Britische Chemikerin, die mit Röntgenstrukturanalyse wichtige Biomoleküle untersuchte. 1964 erhielt sie den Chemie-Nobelpreis.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Dorothy Crowfoot Hodgkin"],"topicKey":"person-dorothy-crowfoot-hodgkin"},{"id":"person-013","category":"Wer ist eigentlich …?","title":"Barbara McClintock","text":"US-Genetikerin, die bewegliche genetische Elemente entdeckte. Für diese Arbeit erhielt sie 1983 den Medizin-Nobelpreis.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Barbara McClintock"],"topicKey":"person-barbara-mcclintock"},{"id":"person-014","category":"Wer ist eigentlich …?","title":"Tu Youyou","text":"Chinesische Pharmazeutin. Ihre Arbeit führte zur Entwicklung von Artemisinin, einem entscheidenden Medikament gegen Malaria.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Tu Youyou"],"topicKey":"person-tu-youyou"},{"id":"person-015","category":"Wer ist eigentlich …?","title":"Katalin Karikó","text":"Biochemikerin, deren jahrzehntelange Forschung an mRNA entscheidend für moderne mRNA-Impfstoffe wurde. 2023 erhielt sie dafür den Medizin-Nobelpreis.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Katalin Karikó"],"topicKey":"person-katalin-kariko"},{"id":"person-016","category":"Wer ist eigentlich …?","title":"Svante Pääbo","text":"Genetiker und Begründer der Paläogenetik. Sein Team entschlüsselte unter anderem große Teile des Neandertaler-Genoms.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Svante Pääbo"],"topicKey":"person-svante-paabo"},{"id":"person-017","category":"Wer ist eigentlich …?","title":"Ada Lovelace","text":"Britische Mathematikerin des 19. Jahrhunderts. Ihre Notizen zur Analytical Engine von Charles Babbage enthalten einen der frühesten veröffentlichten Algorithmen für eine Maschine.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Ada Lovelace"],"topicKey":"person-ada-lovelace"},{"id":"person-018","category":"Wer ist eigentlich …?","title":"Grace Hopper","text":"Informatikpionierin und US-Navy-Offizierin. Sie arbeitete an frühen Compilern und prägte die Entwicklung benutzerfreundlicher Programmiersprachen mit.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Grace Hopper"],"topicKey":"person-grace-hopper"},{"id":"person-019","category":"Wer ist eigentlich …?","title":"Hedy Lamarr","text":"Hollywood-Schauspielerin und Miterfinderin eines Frequenzsprungverfahrens für Funkkommunikation. Ihre technische Arbeit wurde erst viel später breiter gewürdigt.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Hedy Lamarr"],"topicKey":"person-hedy-lamarr"},{"id":"person-023","category":"Wer ist eigentlich …?","title":"Patricia Bath","text":"US-Augenärztin und Erfinderin. Sie entwickelte ein laserbasiertes Verfahren zur Behandlung von Grauem Star.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Patricia Bath"],"topicKey":"person-patricia-bath"},{"id":"person-024","category":"Wer ist eigentlich …?","title":"Marion Donovan","text":"US-Erfinderin, die einen wiederverwendbaren wasserdichten Windelüberzug entwickelte und damit die Entwicklung moderner Wegwerfwindeln beeinflusste.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Marion Donovan"],"topicKey":"person-marion-donovan"},{"id":"person-025","category":"Wer ist eigentlich …?","title":"Wilson Greatbatch","text":"US-Erfinder, der entscheidend zur Entwicklung des implantierbaren Herzschrittmachers beitrug.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Wilson Greatbatch"],"topicKey":"person-wilson-greatbatch"},{"id":"person-026","category":"Wer ist eigentlich …?","title":"Garrett Morgan","text":"US-Erfinder und Unternehmer, bekannt unter anderem für eine frühe Sicherheits-Haube für Atemschutz und ein Verkehrssignal mit zusätzlicher Warnphase.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Garrett Morgan"],"topicKey":"person-garrett-morgan"},{"id":"person-027","category":"Wer ist eigentlich …?","title":"George Washington Carver","text":"US-Agrarwissenschaftler, der Bodenfruchtbarkeit, Fruchtwechsel und alternative Nutzpflanzen förderte. Viele populäre Erfindungsmythen über ihn sind stark übertrieben.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","George Washington Carver"],"topicKey":"person-george-washington-carver"},{"id":"person-028","category":"Wer ist eigentlich …?","title":"Chien-Shiung Wu","text":"Chinesisch-amerikanische Experimentalphysikerin. Ihre Experimente spielten eine Schlüsselrolle beim Nachweis der Paritätsverletzung in der Teilchenphysik.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Chien-Shiung Wu"],"topicKey":"person-chien-shiung-wu"},{"id":"person-029","category":"Wer ist eigentlich …?","title":"Mae Jemison","text":"Ärztin, Ingenieurin und Astronautin. 1992 wurde sie als erste schwarze Frau im All bekannt.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Mae Jemison"],"topicKey":"person-mae-jemison"},{"id":"person-030","category":"Wer ist eigentlich …?","title":"Sally Ride","text":"Physikerin und Astronautin. 1983 wurde sie die erste US-Amerikanerin im All.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Sally Ride"],"topicKey":"person-sally-ride"},{"id":"person-031","category":"Wer ist eigentlich …?","title":"Neil Armstrong","text":"Testpilot und Astronaut. 1969 betrat er als erster Mensch den Mond.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Neil Armstrong"],"topicKey":"person-neil-armstrong"},{"id":"person-032","category":"Wer ist eigentlich …?","title":"Buzz Aldrin","text":"Astronaut und Ingenieur. Er folgte Neil Armstrong 1969 als zweiter Mensch auf die Mondoberfläche.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Buzz Aldrin"],"topicKey":"person-buzz-aldrin"},{"id":"person-033","category":"Wer ist eigentlich …?","title":"Yuri Gagarin","text":"Sowjetischer Kosmonaut. 1961 wurde er als erster Mensch im Weltraum und im Erdorbit bekannt.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Yuri Gagarin"],"topicKey":"person-yuri-gagarin"},{"id":"person-034","category":"Wer ist eigentlich …?","title":"Valentina Tereschkowa","text":"Sowjetische Kosmonautin. 1963 wurde sie die erste Frau im Weltraum.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Valentina Tereschkowa"],"topicKey":"person-valentina-tereschkowa"},{"id":"person-035","category":"Wer ist eigentlich …?","title":"John Glenn","text":"Pilot, Astronaut und später US-Senator. 1962 umrundete er als erster US-Amerikaner die Erde im Orbit.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","John Glenn"],"topicKey":"person-john-glenn"},{"id":"person-036","category":"Wer ist eigentlich …?","title":"Alan Shepard","text":"Mercury-Astronaut. 1961 wurde er der erste US-Amerikaner im Weltraum und 1971 einer der wenigen Menschen, die auf dem Mond standen.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Alan Shepard"],"topicKey":"person-alan-shepard"},{"id":"person-037","category":"Wer ist eigentlich …?","title":"Eileen Collins","text":"US-Astronautin und Pilotin. Sie war die erste Frau, die ein Space Shuttle steuerte und später auch kommandierte.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Eileen Collins"],"topicKey":"person-eileen-collins"},{"id":"person-038","category":"Wer ist eigentlich …?","title":"Katherine Johnson","text":"Mathematikerin bei NACA und NASA. Ihre Berechnungen halfen bei Flugbahnen für frühe bemannte Raumflüge und Mondmissionen.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Katherine Johnson"],"topicKey":"person-katherine-johnson"},{"id":"person-039","category":"Wer ist eigentlich …?","title":"Nancy Grace Roman","text":"Astronomin und erste Chefastronomin der NASA. Wegen ihrer Rolle bei der Entwicklung großer Weltraumteleskop-Projekte wird sie oft 'Mother of Hubble' genannt.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Nancy Grace Roman"],"topicKey":"person-nancy-grace-roman"},{"id":"person-040","category":"Wer ist eigentlich …?","title":"Carl Sagan","text":"Astronom, Wissenschaftskommunikator und Mitbegründer der modernen populären Astronomievermittlung. Er arbeitete an mehreren Raumfahrtmissionen und moderierte die Serie 'Cosmos'.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Carl Sagan"],"topicKey":"person-carl-sagan"},{"id":"person-041","category":"Wer ist eigentlich …?","title":"Clyde Tombaugh","text":"US-Astronom, der 1930 Pluto entdeckte, nachdem er fotografische Himmelsaufnahmen systematisch verglichen hatte.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Clyde Tombaugh"],"topicKey":"person-clyde-tombaugh"},{"id":"person-042","category":"Wer ist eigentlich …?","title":"Jocelyn Bell Burnell","text":"Astrophysikerin, die als Doktorandin die ersten Pulsarsignale identifizierte. Die Nobel-Auszeichnung für die zugehörige Forschung ging später an andere Beteiligte.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Jocelyn Bell Burnell"],"topicKey":"person-jocelyn-bell-burnell"},{"id":"person-043","category":"Wer ist eigentlich …?","title":"Caroline Herschel","text":"Astronomin des 18. und frühen 19. Jahrhunderts. Sie entdeckte mehrere Kometen und arbeitete eng mit ihrem Bruder William Herschel zusammen.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Caroline Herschel"],"topicKey":"person-caroline-herschel"},{"id":"person-044","category":"Wer ist eigentlich …?","title":"Tycho Brahe","text":"Dänischer Astronom, dessen extrem präzise Himmelsbeobachtungen noch vor dem Teleskop Johannes Kepler wichtige Grundlagen lieferten.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Tycho Brahe"],"topicKey":"person-tycho-brahe"},{"id":"person-045","category":"Wer ist eigentlich …?","title":"Johannes Kepler","text":"Astronom und Mathematiker. Aus Beobachtungsdaten entwickelte er die Gesetze der Planetenbewegung.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Johannes Kepler"],"topicKey":"person-johannes-kepler"},{"id":"person-046","category":"Wer ist eigentlich …?","title":"Nikolaus Kopernikus","text":"Astronom, der ein heliozentrisches Modell ausarbeitete, in dem die Erde und andere Planeten die Sonne umkreisen.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Nikolaus Kopernikus"],"topicKey":"person-nikolaus-kopernikus"},{"id":"person-047","category":"Wer ist eigentlich …?","title":"Galileo Galilei","text":"Italienischer Naturforscher. Mit verbesserten Teleskopen beobachtete er unter anderem Jupitermonde und Phasen der Venus.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Galileo Galilei"],"topicKey":"person-galileo-galilei"},{"id":"person-048","category":"Wer ist eigentlich …?","title":"Isaac Newton","text":"Mathematiker und Physiker, der Bewegungsgesetze und Gravitation mathematisch formulierte und grundlegende Arbeiten zur Optik veröffentlichte.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Isaac Newton"],"topicKey":"person-isaac-newton"},{"id":"person-049","category":"Wer ist eigentlich …?","title":"Stephen Hawking","text":"Britischer theoretischer Physiker, bekannt für Arbeiten zu Schwarzen Löchern und Kosmologie sowie für populärwissenschaftliche Bücher.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Stephen Hawking"],"topicKey":"person-stephen-hawking"},{"id":"person-050","category":"Wer ist eigentlich …?","title":"Sergei Koroljow","text":"Sowjetischer Raketeningenieur und zentrale Figur des frühen sowjetischen Raumfahrtprogramms.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Sergei Koroljow"],"topicKey":"person-sergei-koroljow"},{"id":"person-051","category":"Wer ist eigentlich …?","title":"Wernher von Braun","text":"Raketeningenieur, der zuerst im nationalsozialistischen Deutschland an Raketen arbeitete und später eine zentrale Rolle im US-Raumfahrtprogramm spielte. Seine Biografie ist wegen des Einsatzes von Zwangsarbeit eng mit Verbrechen des NS-Regimes verbunden.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Wernher von Braun"],"topicKey":"person-wernher-von-braun"},{"id":"person-052","category":"Wer ist eigentlich …?","title":"James Webb","text":"US-Verwaltungsmanager und NASA-Administrator während eines großen Teils des Apollo-Programms. Das James-Webb-Weltraumteleskop trägt seinen Namen.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","James Webb"],"topicKey":"person-james-webb"},{"id":"person-053","category":"Wer ist eigentlich …?","title":"Christopher Kraft","text":"NASA-Ingenieur, der das Konzept moderner Missionskontrolle wesentlich mitentwickelte und prägte.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Christopher Kraft"],"topicKey":"person-christopher-kraft"},{"id":"person-054","category":"Wer ist eigentlich …?","title":"Gene Kranz","text":"Flugdirektor der NASA, besonders bekannt für seine Rolle bei Apollo 13 und andere frühe bemannte Missionen.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Gene Kranz"],"topicKey":"person-gene-kranz"},{"id":"person-055","category":"Wer ist eigentlich …?","title":"Margaret Hamilton","text":"Informatikerin, die das Softwareteam für die Apollo-Bordsoftware am MIT leitete. Ihr Team prägte die professionelle Entwicklung komplexer Flugsoftware.","source":"NASA","sourceUrl":"https://starchild.gsfc.nasa.gov/docs/StarChild/whos_who_level2/whos_who.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Margaret Hamilton"],"topicKey":"person-margaret-hamilton"},{"id":"person-056","category":"Wer ist eigentlich …?","title":"James Smithson","text":"Britischer Chemiker und Mineraloge, dessen Vermögen nach seinem Tod zur Gründung der Smithsonian Institution in den USA führte – obwohl er die Vereinigten Staaten zu Lebzeiten nie besucht hatte.","source":"Smithsonian Institution","sourceUrl":"https://www.si.edu/newsdesk/factsheets/james-smithson-biographical-information","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","James Smithson"],"topicKey":"person-james-smithson"},{"id":"person-057","category":"Wer ist eigentlich …?","title":"Joseph Henry","text":"US-Physiker und erster Sekretär der Smithsonian Institution. Er arbeitete unter anderem an Elektromagnetismus und half, die wissenschaftliche Ausrichtung der Institution zu prägen.","source":"Smithsonian Institution Archives","sourceUrl":"https://siarchives.si.edu/history/featured-topics/henry/biography","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Joseph Henry"],"topicKey":"person-joseph-henry"},{"id":"person-058","category":"Wer ist eigentlich …?","title":"Jane Goodall","text":"Primatologin, bekannt für jahrzehntelange Feldforschung an Schimpansen in Gombe. Ihre Beobachtungen veränderten das Bild davon, wie ähnlich uns Menschenaffen in Verhalten und Werkzeuggebrauch sind.","source":"Jane Goodall Institute","sourceUrl":"https://janegoodall.org/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Jane Goodall"],"topicKey":"person-jane-goodall"},{"id":"person-059","category":"Wer ist eigentlich …?","title":"Dian Fossey","text":"Primatologin, die Berggorillas in Ruanda erforschte und sich intensiv für ihren Schutz einsetzte.","source":"Dian Fossey Gorilla Fund","sourceUrl":"https://gorillafund.org/who-we-are/dian-fossey/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Dian Fossey"],"topicKey":"person-dian-fossey"},{"id":"person-060","category":"Wer ist eigentlich …?","title":"David Attenborough","text":"Britischer Naturfilmer und Moderator, der über Jahrzehnte Naturdokumentationen prägte und Generationen für Tierwelt und Ökologie begeisterte.","source":"BBC","sourceUrl":"https://www.bbc.com/historyofthebbc/research/david-attenborough","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","David Attenborough"],"topicKey":"person-david-attenborough"},{"id":"person-061","category":"Wer ist eigentlich …?","title":"Jacques Cousteau","text":"Französischer Meeresforscher und Filmemacher. Er half, Tauchtechnik populär zu machen und brachte Unterwasserwelten in Millionen Wohnzimmer.","source":"Cousteau Society","sourceUrl":"https://www.cousteau.org/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Jacques Cousteau"],"topicKey":"person-jacques-cousteau"},{"id":"person-062","category":"Wer ist eigentlich …?","title":"Rachel Carson","text":"US-Meeresbiologin und Autorin. Ihr Buch 'Silent Spring' machte Umweltfolgen bestimmter Pestizide einem breiten Publikum bekannt.","source":"U.S. Fish & Wildlife Service","sourceUrl":"https://www.fws.gov/staff-profile/rachel-carson","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Rachel Carson"],"topicKey":"person-rachel-carson"},{"id":"person-063","category":"Wer ist eigentlich …?","title":"Charles Darwin","text":"Britischer Naturforscher, dessen Arbeiten zur Evolution durch natürliche Selektion die Biologie grundlegend veränderten.","source":"Natural History Museum","sourceUrl":"https://www.nhm.ac.uk/discover/charles-darwin-most-famous-biologist.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Charles Darwin"],"topicKey":"person-charles-darwin"},{"id":"person-064","category":"Wer ist eigentlich …?","title":"Alfred Russel Wallace","text":"Britischer Naturforscher, der unabhängig von Darwin die Idee der Evolution durch natürliche Selektion entwickelte und wichtige Beiträge zur Biogeografie leistete.","source":"Natural History Museum","sourceUrl":"https://www.nhm.ac.uk/discover/alfred-russel-wallace.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Alfred Russel Wallace"],"topicKey":"person-alfred-russel-wallace"},{"id":"person-065","category":"Wer ist eigentlich …?","title":"Alexander von Humboldt","text":"Preußischer Naturforscher und Forschungsreisender. Er verband Beobachtungen zu Klima, Geografie, Pflanzenwelt und Umwelt zu einem erstaunlich modernen Gesamtbild von Naturzusammenhängen.","source":"Alexander von Humboldt-Stiftung","sourceUrl":"https://www.humboldt-foundation.de/entdecken/alexander-von-humboldt","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Alexander von Humboldt"],"topicKey":"person-alexander-von-humboldt"},{"id":"person-066","category":"Wer ist eigentlich …?","title":"Mary Anning","text":"Englische Fossiliensammlerin und Paläontologie-Pionierin. Ihre Funde von Meeresreptilien halfen im 19. Jahrhundert, das Verständnis ausgestorbener Lebensformen zu verändern.","source":"Natural History Museum","sourceUrl":"https://www.nhm.ac.uk/discover/mary-anning-unsung-hero.html","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Mary Anning"],"topicKey":"person-mary-anning"},{"id":"person-067","category":"Wer ist eigentlich …?","title":"Louis Pasteur","text":"Französischer Chemiker und Mikrobiologe. Seine Arbeiten zu Keimen, Impfstoffen und Pasteurisierung beeinflussten Medizin und Lebensmittelhygiene nachhaltig.","source":"Nobel Prize / Wissenschaftsgeschichte","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Louis Pasteur"],"topicKey":"person-louis-pasteur"},{"id":"person-068","category":"Wer ist eigentlich …?","title":"Robert Koch","text":"Deutscher Mediziner und Mikrobiologe. Er entwickelte zentrale Methoden der Bakteriologie und identifizierte unter anderem die Erreger von Tuberkulose und Cholera.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Robert Koch"],"topicKey":"person-robert-koch"},{"id":"person-069","category":"Wer ist eigentlich …?","title":"Ignaz Semmelweis","text":"Ungarischer Arzt, der erkannte, dass Händedesinfektion die Sterblichkeit von Wöchnerinnen drastisch senken konnte – lange bevor die Keimtheorie allgemein akzeptiert war.","source":"Encyclopaedia Britannica","sourceUrl":"https://www.britannica.com/biography/Ignaz-Semmelweis","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Ignaz Semmelweis"],"topicKey":"person-ignaz-semmelweis"},{"id":"person-070","category":"Wer ist eigentlich …?","title":"Florence Nightingale","text":"Britische Krankenpflegerin und Reformerin. Sie nutzte auch Statistik, um Missstände in der medizinischen Versorgung sichtbar zu machen.","source":"Science Museum","sourceUrl":"https://www.sciencemuseum.org.uk/objects-and-stories/florence-nightingale-pioneer-statistician","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Florence Nightingale"],"topicKey":"person-florence-nightingale"},{"id":"person-071","category":"Wer ist eigentlich …?","title":"Alan Turing","text":"Britischer Mathematiker und Informatikpionier. Er arbeitete an theoretischen Grundlagen des Rechnens und im Zweiten Weltkrieg an der Entschlüsselung deutscher Funksprüche.","source":"UK National Archives","sourceUrl":"https://www.nationalarchives.gov.uk/turing/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Alan Turing"],"topicKey":"person-alan-turing"},{"id":"person-072","category":"Wer ist eigentlich …?","title":"Tim Berners-Lee","text":"Britischer Informatiker, der am CERN das World Wide Web entwickelte – mit URL, HTTP und HTML als zentralen Bausteinen.","source":"CERN","sourceUrl":"https://home.cern/science/computing/birth-web","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Tim Berners-Lee"],"topicKey":"person-tim-berners-lee"},{"id":"person-073","category":"Wer ist eigentlich …?","title":"Vint Cerf","text":"US-Informatiker und einer der Entwickler von TCP/IP, den grundlegenden Protokollen, mit denen Rechnernetze im Internet miteinander kommunizieren.","source":"Internet Society","sourceUrl":"https://www.internetsociety.org/internet/history-internet/brief-history-internet/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Vint Cerf"],"topicKey":"person-vint-cerf"},{"id":"person-074","category":"Wer ist eigentlich …?","title":"Radia Perlman","text":"Informatikerin, deren Arbeit am Spanning Tree Protocol entscheidend für robuste Computernetzwerke wurde. Sie wird manchmal scherzhaft 'Mother of the Internet' genannt, obwohl das Internet natürlich nicht auf einer einzelnen Person beruht.","source":"Smithsonian / Computer History","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Radia Perlman"],"topicKey":"person-radia-perlman"},{"id":"person-075","category":"Wer ist eigentlich …?","title":"Dennis Ritchie","text":"US-Informatiker, Mitentwickler der Programmiersprache C und des Betriebssystems Unix. Beides beeinflusst Software bis heute enorm.","source":"Computer History Museum","sourceUrl":"https://www.computerhistory.org/fellowawards/hall/dennis-m-ritchie/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Dennis Ritchie"],"topicKey":"person-dennis-ritchie"},{"id":"person-076","category":"Wer ist eigentlich …?","title":"Ken Thompson","text":"US-Informatiker und Mitentwickler von Unix. Seine Arbeit prägte Betriebssysteme, Programmiersprachen und Softwarewerkzeuge nachhaltig.","source":"Computer History Museum","sourceUrl":"https://www.computerhistory.org/fellowawards/hall/ken-thompson/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Ken Thompson"],"topicKey":"person-ken-thompson"},{"id":"person-077","category":"Wer ist eigentlich …?","title":"Guido van Rossum","text":"Niederländischer Programmierer und Schöpfer von Python. Die Sprache sollte lesbar sein und entwickelte sich zu einer der wichtigsten Programmiersprachen für Wissenschaft, Automatisierung und KI.","source":"Python Software Foundation","sourceUrl":"https://www.python.org/doc/essays/foreword/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Guido van Rossum"],"topicKey":"person-guido-van-rossum"},{"id":"person-078","category":"Wer ist eigentlich …?","title":"Linus Torvalds","text":"Finnisch-amerikanischer Programmierer, der 1991 den Linux-Kernel begann und später auch Git initiierte.","source":"Linux Foundation","sourceUrl":"https://www.linuxfoundation.org/about/linux","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Linus Torvalds"],"topicKey":"person-linus-torvalds"},{"id":"person-079","category":"Wer ist eigentlich …?","title":"Douglas Engelbart","text":"US-Ingenieur, bekannt für frühe Arbeiten an interaktiven Computersystemen und für die Entwicklung einer der ersten praktischen Computer-Mäuse.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Douglas Engelbart"],"topicKey":"person-douglas-engelbart"},{"id":"person-080","category":"Wer ist eigentlich …?","title":"George de Mestral","text":"Schweizer Ingenieur, der nach Kletten an Kleidung und Hundefell das Prinzip entwickelte, aus dem der Klettverschluss Velcro entstand.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/categories/technology/item/who-came-up-with-the-idea-for-velcro","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","George de Mestral"],"topicKey":"person-george-de-mestral"},{"id":"person-082","category":"Wer ist eigentlich …?","title":"Garrett Brown","text":"US-Kameramann und Erfinder der Steadicam, die flüssige Kamerabewegungen ohne Schienen oder starre Stative revolutionierte.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Garrett Brown"],"topicKey":"person-garrett-brown"},{"id":"person-083","category":"Wer ist eigentlich …?","title":"Lonnie Johnson","text":"US-Ingenieur und Erfinder, der unter anderem am Super Soaker arbeitete und außerdem an Energie- und Raumfahrttechnik forschte.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Lonnie Johnson"],"topicKey":"person-lonnie-johnson"},{"id":"person-084","category":"Wer ist eigentlich …?","title":"Temple Grandin","text":"US-Tierwissenschaftlerin und Autistin. Sie entwickelte tierschonendere Anlagen für den Umgang mit Nutztieren und ist zugleich eine bekannte Autorin über Autismus.","source":"Smithsonian / Hochschulquellen","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Temple Grandin"],"topicKey":"person-temple-grandin"},{"id":"person-085","category":"Wer ist eigentlich …?","title":"George Eastman","text":"US-Unternehmer und Foto-Pionier, der mit Rollfilm und einfach zu bedienenden Kameras Fotografie einem Massenpublikum zugänglicher machte.","source":"George Eastman Museum","sourceUrl":"https://www.eastman.org/george-eastman","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","George Eastman"],"topicKey":"person-george-eastman"},{"id":"person-087","category":"Wer ist eigentlich …?","title":"Akio Morita","text":"Japanischer Unternehmer und Mitgründer von Sony. Er half, japanische Unterhaltungselektronik weltweit zu etablieren.","source":"Sony History","sourceUrl":"https://www.sony.com/en/SonyInfo/CorporateInfo/History/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Akio Morita"],"topicKey":"person-akio-morita"},{"id":"origin-001","category":"Wie entstand eigentlich …?","title":"… Telefon?","text":"Alexander Graham Bell erhielt 1876 ein entscheidendes Telefonpatent, doch die Entwicklung entstand nicht im luftleeren Raum: Auch Antonio Meucci, Johann Reis und Elisha Gray arbeiteten an ähnlichen Ideen. Technikgeschichte ist selten ein Ein-Mann-Märchen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Telefon"],"topicKey":"origin-telefon"},{"id":"origin-002","category":"Wie entstand eigentlich …?","title":"… Kühlschrank?","text":"Mechanische Kühlung entwickelte sich schrittweise aus Eiskellern, isolierten Behältern und frühen Kältemaschinen. Haushaltskühlschränke wurden erst im 20. Jahrhundert wirklich alltäglich.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Kühlschrank"],"topicKey":"origin-kuhlschrank"},{"id":"origin-003","category":"Wie entstand eigentlich …?","title":"… Staubsauger?","text":"Frühe Reinigungsmaschinen waren riesig und wurden teils von außen über Schläuche betrieben. Erst kleinere elektrische Geräte machten den Staubsauger zum normalen Haushaltsgerät.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Staubsauger"],"topicKey":"origin-staubsauger"},{"id":"origin-004","category":"Wie entstand eigentlich …?","title":"… Toaster?","text":"Elektrische Toaster wurden möglich, als hitzebeständige Drähte entwickelt waren. Frühe Geräte toasteten oft nur eine Seite gleichzeitig und mussten von Hand überwacht werden.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Toaster"],"topicKey":"origin-toaster"},{"id":"origin-005","category":"Wie entstand eigentlich …?","title":"… Mikrofon?","text":"Mikrofone entstanden im 19. Jahrhundert aus Experimenten mit Telefonie und Schallübertragung. Kohlemikrofone machten Sprache deutlich besser elektrisch übertragbar.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Mikrofon"],"topicKey":"origin-mikrofon"},{"id":"origin-006","category":"Wie entstand eigentlich …?","title":"… Lautsprecher?","text":"Die Entwicklung des Lautsprechers hängt eng mit Telefon, Radio und elektrischer Verstärkung zusammen. Aus frühen Telefonhörern wurden Geräte, die ganze Räume beschallen konnten.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Lautsprecher"],"topicKey":"origin-lautsprecher"},{"id":"origin-007","category":"Wie entstand eigentlich …?","title":"… Radio?","text":"Radio entstand aus mehreren Entdeckungen zu elektromagnetischen Wellen, Funkentelegrafie und Verstärkung. Die Idee vom 'Erfinder des Radios' ist deshalb deutlich komplizierter als ein einzelner Name.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Radio"],"topicKey":"origin-radio"},{"id":"origin-008","category":"Wie entstand eigentlich …?","title":"… Fernsehen?","text":"Fernsehen entwickelte sich aus mechanischen Bildabtastern und später elektronischen Röhren. Erst nach vielen konkurrierenden Systemen setzte sich eine praktikable Fernsehtechnik durch.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Fernsehen"],"topicKey":"origin-fernsehen"},{"id":"origin-009","category":"Wie entstand eigentlich …?","title":"… Handy?","text":"Mobiltelefone wurden aus Funktelefonie, Mobilfunkzellen und immer kleineren elektronischen Bauteilen möglich. Die ersten Geräte waren weit entfernt vom heutigen Taschencomputer.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Handy"],"topicKey":"origin-handy"},{"id":"origin-010","category":"Wie entstand eigentlich …?","title":"… Smartphone?","text":"Smartphones verbinden Entwicklungen aus Mobiltelefon, PDA, Kamera, Internetzugang und Touchscreen. Sie sind eher eine technologische Fusion als eine einzelne Erfindung.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Smartphone"],"topicKey":"origin-smartphone"},{"id":"origin-013","category":"Wie entstand eigentlich …?","title":"… Barcode?","text":"Barcodes wurden entwickelt, um Waren maschinell schnell identifizieren zu können. Der bekannte UPC-Code setzte sich im Einzelhandel in den 1970er-Jahren durch.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Barcode"],"topicKey":"origin-barcode"},{"id":"origin-014","category":"Wie entstand eigentlich …?","title":"… Geldautomat?","text":"Geldautomaten entstanden in den 1960er-Jahren aus dem Wunsch, Bargeld auch außerhalb von Bankschalterzeiten verfügbar zu machen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Geldautomat"],"topicKey":"origin-geldautomat"},{"id":"origin-015","category":"Wie entstand eigentlich …?","title":"… Kreditkarte?","text":"Moderne Kreditkarten entwickelten sich aus Kundenkarten und Reise-/Restaurantkarten. Der entscheidende Schritt war eine Karte, die bei vielen unterschiedlichen Händlern akzeptiert wurde.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Kreditkarte"],"topicKey":"origin-kreditkarte"},{"id":"origin-016","category":"Wie entstand eigentlich …?","title":"… Reißverschluss?","text":"Der Reißverschluss entstand aus mehreren Patenten für Verschlusssysteme. Gideon Sundback entwickelte Anfang des 20. Jahrhunderts eine Form, die dem heutigen Prinzip sehr nahekommt.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Reißverschluss"],"topicKey":"origin-rei-verschluss"},{"id":"origin-017","category":"Wie entstand eigentlich …?","title":"… Sicherheitsnadel?","text":"Walter Hunt patentierte 1849 eine Sicherheitsnadel mit Federwirkung und geschützter Spitze. Die Grundidee ist seitdem erstaunlich wenig verändert worden.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Sicherheitsnadel"],"topicKey":"origin-sicherheitsnadel"},{"id":"origin-018","category":"Wie entstand eigentlich …?","title":"… Büroklammer?","text":"Die Büroklammer hat keine simple Ein-Erfinder-Geschichte. Mehrere Drahtklammerformen entstanden parallel; die heute typische Gem-Form wurde besonders verbreitet.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Büroklammer"],"topicKey":"origin-buroklammer"},{"id":"origin-019","category":"Wie entstand eigentlich …?","title":"… Kugelschreiber?","text":"Kugelschreiber wurden populär, nachdem László Bíró ein System mit schnell trocknender Tinte und rollender Kugelspitze weiterentwickelte.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Kugelschreiber"],"topicKey":"origin-kugelschreiber"},{"id":"origin-020","category":"Wie entstand eigentlich …?","title":"… Bleistift?","text":"Der moderne Bleistift entstand aus Graphitstiften und der Idee, Graphit mit Ton zu mischen. Dadurch ließ sich die Härte der Mine gezielt verändern.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Bleistift"],"topicKey":"origin-bleistift"},{"id":"origin-021","category":"Wie entstand eigentlich …?","title":"… Radiergummi?","text":"Vor Gummi radierten Menschen Bleistiftspuren unter anderem mit Brotkrumen. Kautschuk erwies sich als deutlich praktischer und gab dem Radiergummi seinen Namen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Radiergummi"],"topicKey":"origin-radiergummi"},{"id":"origin-022","category":"Wie entstand eigentlich …?","title":"… Füllfederhalter?","text":"Füllfederhalter entwickelten sich aus Schreibfedern mit integriertem Tintenvorrat. Entscheidend war, den Tintenfluss kontrollierbar und auslaufsicher zu machen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Füllfederhalter"],"topicKey":"origin-fullfederhalter"},{"id":"origin-023","category":"Wie entstand eigentlich …?","title":"… Schreibmaschine?","text":"Schreibmaschinen entstanden im 19. Jahrhundert aus zahlreichen konkurrierenden Konstruktionen. Das QWERTY-Tastaturlayout verbreitete sich mit frühen erfolgreichen Modellen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Schreibmaschine"],"topicKey":"origin-schreibmaschine"},{"id":"origin-024","category":"Wie entstand eigentlich …?","title":"… Fotokopierer?","text":"Moderne Kopierer gehen auf Xerografie zurück. Dabei wird ein Bild elektrostatisch erzeugt und Tonerpulver gezielt auf Papier übertragen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Fotokopierer"],"topicKey":"origin-fotokopierer"},{"id":"origin-025","category":"Wie entstand eigentlich …?","title":"… Faxgerät?","text":"Faxtechnik ist älter als viele vermuten: Schon im 19. Jahrhundert gab es Verfahren, Zeichnungen elektrisch über Leitungen zu übertragen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Faxgerät"],"topicKey":"origin-faxgerat"},{"id":"origin-026","category":"Wie entstand eigentlich …?","title":"… Fotoapparat?","text":"Fotografie entstand aus der Verbindung der Camera obscura mit lichtempfindlichen Materialien. Dauerhafte Bilder wurden im 19. Jahrhundert technisch praktikabel.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Fotoapparat"],"topicKey":"origin-fotoapparat"},{"id":"origin-027","category":"Wie entstand eigentlich …?","title":"… Sofortbildkamera?","text":"Edwin Land entwickelte ein Verfahren, bei dem Entwicklung und Positivbild direkt nach der Aufnahme in einem kompakten Prozess entstanden.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Sofortbildkamera"],"topicKey":"origin-sofortbildkamera"},{"id":"origin-028","category":"Wie entstand eigentlich …?","title":"… Kinofilm?","text":"Kino entwickelte sich aus Fotografie, Serienbildern und Projektionstechnik. Ende des 19. Jahrhunderts wurden bewegte Bilder zu öffentlichen Vorführungen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Kinofilm"],"topicKey":"origin-kinofilm"},{"id":"origin-029","category":"Wie entstand eigentlich …?","title":"… Schallplatte?","text":"Schallaufzeichnung begann mit Geräten wie dem Phonographen. Scheibenförmige Tonträger setzten sich später als praktische Form durch.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Schallplatte"],"topicKey":"origin-schallplatte"},{"id":"origin-030","category":"Wie entstand eigentlich …?","title":"… Kopfhörer?","text":"Kopfhörer wuchsen aus frühen Telefon- und Funkhörern. Leichte Stereo-Kopfhörer machten privates Musikhören im 20. Jahrhundert zum Massenphänomen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Kopfhörer"],"topicKey":"origin-kopfhorer"},{"id":"origin-031","category":"Wie entstand eigentlich …?","title":"… Elektrische Gitarre?","text":"Gitarristen wollten sich gegen lautere Bands durchsetzen. Elektrische Tonabnehmer machten es möglich, Saitenschwingungen zu verstärken, ohne nur den Resonanzkörper lauter bauen zu müssen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Elektrische Gitarre"],"topicKey":"origin-elektrische-gitarre"},{"id":"origin-032","category":"Wie entstand eigentlich …?","title":"… Heimvideospiel?","text":"Ralph Baer experimentierte in den 1960er-Jahren mit Spielen auf dem Fernseher. Daraus entstand Technik, die 1972 in der Magnavox Odyssey auf den Markt kam.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Heimvideospiel"],"topicKey":"origin-heimvideospiel"},{"id":"origin-033","category":"Wie entstand eigentlich …?","title":"… Flipperautomat?","text":"Flipper entwickelte sich aus mechanischen Tischspielen. Elektrik, Punktanzeigen und später bewegliche Flipperfinger machten daraus das bekannte Geschicklichkeitsspiel.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Flipperautomat"],"topicKey":"origin-flipperautomat"},{"id":"origin-034","category":"Wie entstand eigentlich …?","title":"… Nähmaschine?","text":"Nähmaschinen entstanden aus vielen Patenten und Rechtsstreitigkeiten. Erst funktionierende Mechanismen für Fadenführung und Stichbildung machten sie industriell und privat brauchbar.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Nähmaschine"],"topicKey":"origin-nahmaschine"},{"id":"origin-035","category":"Wie entstand eigentlich …?","title":"… Waschmaschine?","text":"Mechanische Waschhilfen gab es lange vor elektrischen Maschinen. Motorisierung, Schleudern und automatische Programme machten daraus das heutige Haushaltsgerät.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Waschmaschine"],"topicKey":"origin-waschmaschine"},{"id":"origin-036","category":"Wie entstand eigentlich …?","title":"… Geschirrspüler?","text":"Josephine Cochrane entwickelte im 19. Jahrhundert eine praktikable Geschirrspülmaschine, zunächst vor allem für Hotels und Restaurants.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Geschirrspüler"],"topicKey":"origin-geschirrspuler"},{"id":"origin-037","category":"Wie entstand eigentlich …?","title":"… Klimaanlage?","text":"Willis Carrier entwickelte Anfang des 20. Jahrhunderts ein System zur Kontrolle von Luftfeuchtigkeit in einer Druckerei. Komfortkühlung war anfangs gar nicht das Hauptziel.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Klimaanlage"],"topicKey":"origin-klimaanlage"},{"id":"origin-038","category":"Wie entstand eigentlich …?","title":"… Ventilator?","text":"Mechanische Luftbewegung ist uralt, doch elektrische Motoren machten kompakte Ventilatoren für Haushalt und Büro möglich.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Ventilator"],"topicKey":"origin-ventilator"},{"id":"origin-039","category":"Wie entstand eigentlich …?","title":"… Föhn?","text":"Haartrockner entwickelten sich aus warmer Lufttechnik und kleinen Elektromotoren. Frühe Modelle waren groß und schwer; Handgeräte wurden erst später alltagstauglich.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Föhn"],"topicKey":"origin-fohn"},{"id":"origin-040","category":"Wie entstand eigentlich …?","title":"… Elektrorasierer?","text":"Elektrorasierer entstanden mit kleinen Elektromotoren und bewegten Schneidsystemen. Sie sollten Rasieren ohne Wasser und Seife ermöglichen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Elektrorasierer"],"topicKey":"origin-elektrorasierer"},{"id":"origin-042","category":"Wie entstand eigentlich …?","title":"… Kontaktlinse?","text":"Die Idee einer Linse direkt auf dem Auge ist alt, aber erst neue Kunststoffe machten Kontaktlinsen leichter, dünner und alltagstauglich.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Kontaktlinse"],"topicKey":"origin-kontaktlinse"},{"id":"origin-043","category":"Wie entstand eigentlich …?","title":"… Brille?","text":"Linsen zur Sehkorrektur verbreiteten sich im späten Mittelalter in Europa. Frühe Brillen wurden auf die Nase geklemmt und hatten keine heutigen Bügel.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Brille"],"topicKey":"origin-brille"},{"id":"origin-044","category":"Wie entstand eigentlich …?","title":"… Stethoskop?","text":"René Laennec entwickelte 1816 ein einfaches Hörrohr, weil direktes Abhören unangenehm oder unpraktisch sein konnte. Daraus entstand das Stethoskop.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Stethoskop"],"topicKey":"origin-stethoskop"},{"id":"origin-045","category":"Wie entstand eigentlich …?","title":"… Thermometer?","text":"Thermometer entwickelten sich aus frühen Thermoskopen, die nur Temperaturänderungen anzeigten. Skalen und geschlossene Flüssigkeitssysteme machten vergleichbare Messwerte möglich.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Thermometer"],"topicKey":"origin-thermometer"},{"id":"origin-046","category":"Wie entstand eigentlich …?","title":"… Röntgenbild?","text":"Wilhelm Conrad Röntgen entdeckte 1895 eine Strahlung, die Materialien unterschiedlich durchdringt. Schon kurz darauf entstanden medizinische Aufnahmen von Knochen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Röntgenbild"],"topicKey":"origin-rontgenbild"},{"id":"origin-047","category":"Wie entstand eigentlich …?","title":"… CT?","text":"Computertomografie kombiniert viele Röntgenaufnahmen aus unterschiedlichen Richtungen und rekonstruiert daraus Schnittbilder des Körpers.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","CT"],"topicKey":"origin-ct"},{"id":"origin-048","category":"Wie entstand eigentlich …?","title":"… MRT?","text":"Magnetresonanztomografie nutzt starke Magnetfelder und Radiowellen statt Röntgenstrahlung, um detaillierte Bilder von Gewebe zu erzeugen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","MRT"],"topicKey":"origin-mrt"},{"id":"origin-049","category":"Wie entstand eigentlich …?","title":"… Herzschrittmacher?","text":"Frühe Herzschrittmacher waren externe Geräte. Fortschritte bei Elektronik und Batterien ermöglichten implantierbare Systeme.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Herzschrittmacher"],"topicKey":"origin-herzschrittmacher"},{"id":"origin-050","category":"Wie entstand eigentlich …?","title":"… Defibrillator?","text":"Defibrillation entwickelte sich aus Experimenten, bei bestimmten Herzrhythmusstörungen mit gezielten elektrischen Impulsen einen normalen Rhythmus wiederherzustellen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Defibrillator"],"topicKey":"origin-defibrillator"},{"id":"origin-051","category":"Wie entstand eigentlich …?","title":"… Anästhesie?","text":"Schmerzstillende Stoffe wurden lange genutzt, aber kontrollierte Narkose mit Äther und anderen Gasen revolutionierte Operationen im 19. Jahrhundert.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Anästhesie"],"topicKey":"origin-anasthesie"},{"id":"origin-052","category":"Wie entstand eigentlich …?","title":"… Pflaster?","text":"Wundauflagen sind uralt; selbstklebende Verbände machten kleine Verletzungen im Alltag einfacher versorgbar.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Pflaster"],"topicKey":"origin-pflaster"},{"id":"origin-053","category":"Wie entstand eigentlich …?","title":"… Sonnencreme?","text":"Moderne Sonnenschutzmittel entstanden mit dem besseren Verständnis ultravioletter Strahlung und chemischen beziehungsweise mineralischen UV-Filtern.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Sonnencreme"],"topicKey":"origin-sonnencreme"},{"id":"origin-054","category":"Wie entstand eigentlich …?","title":"… Sicherheitsgurt?","text":"Gurte gab es früh in Flugzeugen und Rennfahrzeugen. Der Dreipunktgurt von Nils Bohlin wurde zum besonders wichtigen Sicherheitsstandard im Auto.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Sicherheitsgurt"],"topicKey":"origin-sicherheitsgurt"},{"id":"origin-055","category":"Wie entstand eigentlich …?","title":"… Airbag?","text":"Airbags entwickelten sich aus der Idee, Insassen bei einem Unfall mit einem extrem schnell aufgeblasenen Kissen abzubremsen. Sensorik und zuverlässige Gasgeneratoren waren entscheidend.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Airbag"],"topicKey":"origin-airbag"},{"id":"origin-056","category":"Wie entstand eigentlich …?","title":"… Fahrrad?","text":"Das Fahrrad entwickelte sich über Laufmaschinen, Hochräder und Sicherheitsräder. Kette, gleich große Räder und Luftreifen führten zum modernen Grundprinzip.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Fahrrad"],"topicKey":"origin-fahrrad"},{"id":"origin-057","category":"Wie entstand eigentlich …?","title":"… Motorrad?","text":"Motorräder entstanden, als Verbrennungsmotoren auf fahrradähnliche Rahmen gesetzt wurden. Daraus entwickelte sich eine eigene Fahrzeugklasse.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Motorrad"],"topicKey":"origin-motorrad"},{"id":"origin-058","category":"Wie entstand eigentlich …?","title":"… U-Bahn?","text":"Untergrundbahnen entstanden als Antwort auf überfüllte Großstadtstraßen. London eröffnete 1863 die erste U-Bahn der Welt.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","U-Bahn"],"topicKey":"origin-u-bahn"},{"id":"origin-059","category":"Wie entstand eigentlich …?","title":"… Rolltreppe?","text":"Rolltreppen entstanden Ende des 19. Jahrhunderts aus beweglichen Stufen- und Bandkonstruktionen, um Menschen kontinuierlich zwischen Ebenen zu transportieren.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Rolltreppe"],"topicKey":"origin-rolltreppe"},{"id":"origin-060","category":"Wie entstand eigentlich …?","title":"… Container?","text":"Standardisierte Frachtcontainer machten es möglich, dieselbe Ladeeinheit ohne Umladen zwischen Schiff, Bahn und Lkw zu bewegen. Das veränderte Welthandel und Häfen massiv.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Container"],"topicKey":"origin-container"},{"id":"origin-061","category":"Wie entstand eigentlich …?","title":"… Konservendose?","text":"Die Konservendose entstand aus dem militärischen und zivilen Bedarf, Lebensmittel lange haltbar zu machen. Kurios: Praktische Dosenöffner kamen erst Jahrzehnte später.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Konservendose"],"topicKey":"origin-konservendose"},{"id":"origin-062","category":"Wie entstand eigentlich …?","title":"… Dosenöffner?","text":"Frühe Konservendosen wurden mit Messern, Bajonetten oder Werkzeug aufgebrochen. Der eigentliche Dosenöffner entstand erst, als Dosen dünner und massenhaft verbreitet waren.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Dosenöffner"],"topicKey":"origin-dosenoffner"},{"id":"origin-063","category":"Wie entstand eigentlich …?","title":"… Streichholz?","text":"Sichere Streichhölzer entstanden aus chemischen Zündmischungen und einer getrennten Reibfläche. Frühere Varianten konnten giftig oder brandgefährlich sein.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Streichholz"],"topicKey":"origin-streichholz"},{"id":"origin-064","category":"Wie entstand eigentlich …?","title":"… Feuerzeug?","text":"Feuerzeuge entwickelten sich aus Funkenmechanismen und später Brennstoffen wie Benzin oder Gas. Piezozünder machten viele moderne Modelle besonders einfach.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Feuerzeug"],"topicKey":"origin-feuerzeug"},{"id":"origin-065","category":"Wie entstand eigentlich …?","title":"… Korkenzieher?","text":"Der Korkenzieher entwickelte sich wahrscheinlich aus Werkzeugen, mit denen Soldaten festsitzende Ladungen aus Gewehrläufen zogen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Korkenzieher"],"topicKey":"origin-korkenzieher"},{"id":"origin-066","category":"Wie entstand eigentlich …?","title":"… Regenschirm?","text":"Schirme wurden in verschiedenen Kulturen zunächst oft als Sonnenschutz und Statussymbol verwendet. Wasserdichte Materialien machten sie zum verbreiteten Regenschutz.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Regenschirm"],"topicKey":"origin-regenschirm"},{"id":"origin-067","category":"Wie entstand eigentlich …?","title":"… Kugellager?","text":"Kugellager reduzieren Reibung zwischen bewegten Teilen. Präzise Metallbearbeitung machte sie zu einem Grundbauteil moderner Maschinen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Kugellager"],"topicKey":"origin-kugellager"},{"id":"origin-068","category":"Wie entstand eigentlich …?","title":"… Fahrstuhlknopf?","text":"Selbstbedienungsaufzüge wurden erst möglich, als sichere automatische Steuerungen menschliche Aufzugführer zunehmend ersetzten.","source":"Library of Congress / Smithsonian","sourceUrl":"https://americanhistory.si.edu/explore/exhibitions/object-project/online/household-hits","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Fahrstuhlknopf"],"topicKey":"origin-fahrstuhlknopf"},{"id":"origin-069","category":"Wie entstand eigentlich …?","title":"… Fließband?","text":"Fließfertigung ist älter als Henry Ford, aber Ford kombinierte bestehende Ideen so konsequent, dass die Taktproduktion von Autos massiv beschleunigt wurde.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","Fließband"],"topicKey":"origin-flie-band"},{"id":"history-new-001","category":"Zeitepochen & Geschichte","title":"Neolithische Revolution","text":"Vor rund 12.000 Jahren begannen Menschen in mehreren Weltregionen unabhängig voneinander, Pflanzen gezielt anzubauen und Tiere zu domestizieren. Sesshaftigkeit entstand also nicht an einem einzigen Ort.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Neolithische Revolution"],"topicKey":"history-neolithische-revolution"},{"id":"history-new-002","category":"Zeitepochen & Geschichte","title":"Göbekli Tepe","text":"Die monumentalen Steinkreise von Göbekli Tepe entstanden vor mehr als 10.000 Jahren. Sie zeigen, dass große gemeinschaftliche Bauprojekte schon vor klassischen Städten möglich waren.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Göbekli Tepe"],"topicKey":"history-gobekli-tepe"},{"id":"history-new-003","category":"Zeitepochen & Geschichte","title":"Çatalhöyük","text":"In Çatalhöyük standen Häuser so dicht, dass Menschen vielfach über Dächer gingen und von oben in ihre Wohnräume stiegen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Çatalhöyük"],"topicKey":"history-catalhoyuk"},{"id":"history-new-004","category":"Zeitepochen & Geschichte","title":"Stonehenge","text":"Stonehenge entstand in mehreren Bauphasen über Jahrhunderte. Einige der verwendeten Steine wurden über erstaunlich große Entfernungen transportiert.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Stonehenge"],"topicKey":"history-stonehenge"},{"id":"history-new-005","category":"Zeitepochen & Geschichte","title":"Höhlenmalerei","text":"Höhlenkunst wie in Lascaux zeigt, dass Menschen bereits vor Zehntausenden Jahren komplexe Bilder von Tieren, Zeichen und Szenen schufen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Höhlenmalerei"],"topicKey":"history-hohlenmalerei"},{"id":"history-new-006","category":"Zeitepochen & Geschichte","title":"Jericho","text":"Jericho gehört zu den ältesten dauerhaft besiedelten Orten der Welt. Schon sehr frühe Bewohner errichteten dort massive Mauern und einen Steinturm.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Jericho"],"topicKey":"history-jericho"},{"id":"history-new-007","category":"Zeitepochen & Geschichte","title":"Ur","text":"Die mesopotamische Stadt Ur war ein wichtiges Handels- und Machtzentrum. Monumentale Zikkurate prägten ihr Stadtbild.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Ur"],"topicKey":"history-ur"},{"id":"history-new-008","category":"Zeitepochen & Geschichte","title":"Hammurabis Stele","text":"Der berühmte Gesetzestext Hammurabis war nicht das erste Rechtssystem, aber eines der bekanntesten erhaltenen Beispiele schriftlich fixierter Herrschaftsregeln.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Hammurabis Stele"],"topicKey":"history-hammurabis-stele"},{"id":"history-new-009","category":"Zeitepochen & Geschichte","title":"Mesopotamische Schulhäuser","text":"Schreiber mussten Keilschrift systematisch lernen. Übungstafeln zeigen, dass Schüler schon vor Jahrtausenden abschrieben, Fehler machten und Aufgaben wiederholten.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Mesopotamische Schulhäuser"],"topicKey":"history-mesopotamische-schulhauser"},{"id":"history-new-010","category":"Zeitepochen & Geschichte","title":"Indus-Städte","text":"Mohenjo-Daro und Harappa besaßen planmäßig angelegte Straßen und ausgefeilte Entwässerungssysteme.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Indus-Städte"],"topicKey":"history-indus-stadte"},{"id":"history-new-011","category":"Zeitepochen & Geschichte","title":"Indus-Schrift","text":"Die Zeichen der Indus-Kultur sind bis heute nicht sicher entziffert. Es ist unbekannt, welche Sprache dahinterstand.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Indus-Schrift"],"topicKey":"history-indus-schrift"},{"id":"history-new-012","category":"Zeitepochen & Geschichte","title":"Persische Königsstraße","text":"Das Achämenidenreich unterhielt ein ausgedehntes Straßennetz. Boten konnten dadurch Nachrichten deutlich schneller über große Entfernungen transportieren.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Persische Königsstraße"],"topicKey":"history-persische-konigsstra-e"},{"id":"history-new-013","category":"Zeitepochen & Geschichte","title":"Königliche persische Post","text":"Stationen mit Pferden und Versorgung ermöglichten im Perserreich schnelle Nachrichtenübermittlung – eine frühe Form organisierter Fernkommunikation.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Königliche persische Post"],"topicKey":"history-konigliche-persische-post"},{"id":"history-new-014","category":"Zeitepochen & Geschichte","title":"Phoenizisches Alphabet","text":"Das phönizische Schriftsystem beeinflusste mehrere spätere Alphabete, darunter das griechische und über Umwege auch unser heutiges lateinisches Alphabet.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Phoenizisches Alphabet"],"topicKey":"history-phoenizisches-alphabet"},{"id":"history-new-015","category":"Zeitepochen & Geschichte","title":"Purpur aus Schnecken","text":"Tyros-Purpur wurde aus Meeresschnecken gewonnen. Die aufwendige Herstellung machte die Farbe extrem teuer und zu einem Statussymbol.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Purpur aus Schnecken"],"topicKey":"history-purpur-aus-schnecken"},{"id":"history-new-016","category":"Zeitepochen & Geschichte","title":"Karthago","text":"Karthago begann als phönizische Siedlung und entwickelte sich zu einer der mächtigsten Handelsstädte des westlichen Mittelmeers.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Karthago"],"topicKey":"history-karthago"},{"id":"history-new-017","category":"Zeitepochen & Geschichte","title":"Ägyptisches Arbeiterdorf","text":"Deir el-Medina war eine Siedlung von Handwerkern, die an königlichen Gräbern arbeiteten. Schriftfunde berichten erstaunlich viel über Löhne, Streit und Alltag.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Ägyptisches Arbeiterdorf"],"topicKey":"history-agyptisches-arbeiterdorf"},{"id":"history-new-018","category":"Zeitepochen & Geschichte","title":"Ägyptischer Arbeiterstreik","text":"Unter Ramses III. legten Arbeiter von Deir el-Medina ihre Arbeit nieder, weil Lebensmittelrationen verspätet waren. Das gilt als einer der frühesten dokumentierten Streiks.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Ägyptischer Arbeiterstreik"],"topicKey":"history-agyptischer-arbeiterstreik"},{"id":"history-new-019","category":"Zeitepochen & Geschichte","title":"Ägyptischer Kalender","text":"Die Ägypter nutzten einen Kalender mit 365 Tagen. Er half unter anderem, Landwirtschaft und religiöse Feste zu organisieren.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Ägyptischer Kalender"],"topicKey":"history-agyptischer-kalender"},{"id":"history-new-020","category":"Zeitepochen & Geschichte","title":"Papyrus","text":"Papyrus war nicht einfach 'altes Papier'. Streifen der Papyruspflanze wurden gekreuzt, gepresst und getrocknet, wodurch eine beschreibbare Fläche entstand.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Papyrus"],"topicKey":"history-papyrus"},{"id":"history-new-021","category":"Zeitepochen & Geschichte","title":"Rosetta-Stein","text":"Der Rosetta-Stein trägt denselben Inhalt in mehreren Schriftformen und war entscheidend für die Entzifferung ägyptischer Hieroglyphen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Rosetta-Stein"],"topicKey":"history-rosetta-stein"},{"id":"history-new-022","category":"Zeitepochen & Geschichte","title":"Nubische Königreiche","text":"Südlich Ägyptens existierten mächtige nubische Reiche wie Kusch. Ihre Herrscher regierten zeitweise sogar über Ägypten.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Nubische Königreiche"],"topicKey":"history-nubische-konigreiche"},{"id":"history-new-023","category":"Zeitepochen & Geschichte","title":"Meroë","text":"Meroë im heutigen Sudan war ein bedeutendes Zentrum des Reiches von Kusch und bekannt für Eisenverarbeitung sowie eigene Schrifttraditionen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Meroë"],"topicKey":"history-meroe"},{"id":"history-new-024","category":"Zeitepochen & Geschichte","title":"Aksum","text":"Das Reich von Aksum im heutigen Äthiopien und Eritrea war ein bedeutender Handelsstaat zwischen Afrika, Arabien und dem Mittelmeerraum.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Aksum"],"topicKey":"history-aksum"},{"id":"history-new-025","category":"Zeitepochen & Geschichte","title":"Groß-Simbabwe","text":"Die Ruinen von Groß-Simbabwe zeugen von einem mächtigen afrikanischen Handelszentrum. Die großen Steinmauern wurden ohne Mörtel errichtet.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Groß-Simbabwe"],"topicKey":"history-gro-simbabwe"},{"id":"history-new-026","category":"Zeitepochen & Geschichte","title":"Mansa Musa","text":"Mansa Musa regierte im 14. Jahrhundert das Mali-Reich. Seine Pilgerreise nach Mekka wurde wegen des mitgeführten Goldes legendär.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Mansa Musa"],"topicKey":"history-mansa-musa"},{"id":"history-new-027","category":"Zeitepochen & Geschichte","title":"Timbuktu","text":"Timbuktu war nicht nur Handelsplatz, sondern auch ein wichtiges Zentrum islamischer Gelehrsamkeit mit Bibliotheken und Schulen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Timbuktu"],"topicKey":"history-timbuktu"},{"id":"history-new-028","category":"Zeitepochen & Geschichte","title":"Benin-Bronzen","text":"Die sogenannten Benin-Bronzen zeigen die hochentwickelte Metallkunst des Königreichs Benin. Viele Stücke wurden 1897 von britischen Truppen geraubt.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Benin-Bronzen"],"topicKey":"history-benin-bronzen"},{"id":"history-new-029","category":"Zeitepochen & Geschichte","title":"Swahili-Städte","text":"An Ostafrikas Küste entstanden wohlhabende Swahili-Städte, die Handel zwischen Afrika, Arabien, Persien und Indien betrieben.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Swahili-Städte"],"topicKey":"history-swahili-stadte"},{"id":"history-new-030","category":"Zeitepochen & Geschichte","title":"Terrakotta-Armee","text":"Tausende Tonfiguren bewachen das Grab des ersten chinesischen Kaisers Qin Shihuangdi. Viele Figuren besitzen individuell gestaltete Gesichtszüge.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Terrakotta-Armee"],"topicKey":"history-terrakotta-armee"},{"id":"history-new-031","category":"Zeitepochen & Geschichte","title":"Chinesische Beamtenprüfungen","text":"Im kaiserlichen China konnten Prüfungen über klassische Texte den Zugang zu Staatsämtern bestimmen. Vorbereitung darauf konnte Jahre dauern.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Chinesische Beamtenprüfungen"],"topicKey":"history-chinesische-beamtenprufungen"},{"id":"history-new-032","category":"Zeitepochen & Geschichte","title":"Papier in China","text":"Papier wurde in China lange vor seiner Verbreitung in Europa hergestellt und weiterentwickelt. Es veränderte Verwaltung, Bildung und Kommunikation.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Papier in China"],"topicKey":"history-papier-in-china"},{"id":"history-new-033","category":"Zeitepochen & Geschichte","title":"Schießpulver in China","text":"Schießpulver entstand in China aus alchemistischen Experimenten. Es wurde zunächst nicht nur militärisch, sondern auch für Feuerwerk genutzt.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Schießpulver in China"],"topicKey":"history-schie-pulver-in-china"},{"id":"history-new-034","category":"Zeitepochen & Geschichte","title":"Kompass in China","text":"Magnetische Kompasse wurden in China früh genutzt. Sie erleichterten später Navigation auf See und über weite Entfernungen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Kompass in China"],"topicKey":"history-kompass-in-china"},{"id":"history-new-035","category":"Zeitepochen & Geschichte","title":"Seidenstraße","text":"Die Seidenstraße war keine einzelne Straße, sondern ein Netzwerk vieler Land- und Seewege, über die Waren, Ideen, Krankheiten und Religionen wanderten.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Seidenstraße"],"topicKey":"history-seidenstra-e"},{"id":"history-new-036","category":"Zeitepochen & Geschichte","title":"Tang-Hauptstadt Chang'an","text":"Chang'an gehörte in der Tang-Zeit zu den größten und kosmopolitischsten Städten der Welt.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Tang-Hauptstadt Chang'an"],"topicKey":"history-tang-hauptstadt-chang-an"},{"id":"history-new-037","category":"Zeitepochen & Geschichte","title":"Verbotene Stadt","text":"Die Verbotene Stadt in Beijing war über Jahrhunderte das politische Zentrum chinesischer Kaiserherrschaft und umfasst Hunderte Gebäude.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Verbotene Stadt"],"topicKey":"history-verbotene-stadt"},{"id":"history-new-038","category":"Zeitepochen & Geschichte","title":"Samurai","text":"Samurai waren nicht einfach nur Schwertkämpfer. Sie gehörten über lange Zeit zu einer militärischen und politischen Elite mit wechselnden Aufgaben.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Samurai"],"topicKey":"history-samurai"},{"id":"history-new-039","category":"Zeitepochen & Geschichte","title":"Shogunat","text":"In mehreren Epochen Japans lag die tatsächliche politische Macht beim Shogun, während der Kaiser eine andere, oft stärker zeremonielle Rolle behielt.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Shogunat"],"topicKey":"history-shogunat"},{"id":"history-new-040","category":"Zeitepochen & Geschichte","title":"Sankin-kōtai","text":"Japanische Daimyō mussten in der Edo-Zeit regelmäßig Zeit am Hof des Shoguns in Edo verbringen. Das band enorme Ressourcen und stärkte die Kontrolle der Zentralmacht.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Sankin-kōtai"],"topicKey":"history-sankin-kotai"},{"id":"history-new-041","category":"Zeitepochen & Geschichte","title":"Maya-Kalender","text":"Die Maya nutzten mehrere miteinander kombinierte Kalendersysteme. Der Ablauf eines Zyklus im Jahr 2012 bedeutete keineswegs eine vorhergesagte Weltzerstörung.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Maya-Kalender"],"topicKey":"history-maya-kalender"},{"id":"history-new-042","category":"Zeitepochen & Geschichte","title":"Maya-Zahl Null","text":"Maya-Mathematiker verwendeten ein echtes Nullzeichen in ihrem Stellenwertsystem – unabhängig von Entwicklungen in anderen Weltregionen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Maya-Zahl Null"],"topicKey":"history-maya-zahl-null"},{"id":"history-new-043","category":"Zeitepochen & Geschichte","title":"Maya-Stadtstaaten","text":"Die klassische Maya-Welt bestand aus vielen konkurrierenden Stadtstaaten. Es gab kein dauerhaft geeintes Maya-Großreich.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Maya-Stadtstaaten"],"topicKey":"history-maya-stadtstaaten"},{"id":"history-new-044","category":"Zeitepochen & Geschichte","title":"Inka-Straßennetz","text":"Das Inka-Reich verband riesige Gebiete durch Zehntausende Kilometer Straßen, Brücken und Bergpfade.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Inka-Straßennetz"],"topicKey":"history-inka-stra-ennetz"},{"id":"history-new-045","category":"Zeitepochen & Geschichte","title":"Quipu","text":"Inka-Verwalter nutzten Knotenschnüre, sogenannte Quipus, zur Speicherung von Zahlen und vermutlich weiterer Informationen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Quipu"],"topicKey":"history-quipu"},{"id":"history-new-046","category":"Zeitepochen & Geschichte","title":"Chaski-Läufer","text":"Im Inka-Reich transportierten Staffelläufer Nachrichten und kleine Gegenstände über das Straßennetz.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Chaski-Läufer"],"topicKey":"history-chaski-laufer"},{"id":"history-new-047","category":"Zeitepochen & Geschichte","title":"Machu Picchu","text":"Machu Picchu liegt hoch in den Anden und war den spanischen Eroberern offenbar nicht in gleicher Weise bekannt wie viele andere Inka-Zentren.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Machu Picchu"],"topicKey":"history-machu-picchu"},{"id":"history-new-048","category":"Zeitepochen & Geschichte","title":"Chinampas","text":"Die Azteken nutzten intensiv bewirtschaftete künstliche Anbauflächen in flachen Seen, sogenannte Chinampas, um ihre Großstadtregion zu versorgen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Chinampas"],"topicKey":"history-chinampas"},{"id":"history-new-049","category":"Zeitepochen & Geschichte","title":"Aztekischer Markt","text":"Der Markt von Tlatelolco zog täglich große Menschenmengen an. Spanische Beobachter beschrieben ihn als überwältigend groß und organisiert.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Aztekischer Markt"],"topicKey":"history-aztekischer-markt"},{"id":"history-new-050","category":"Zeitepochen & Geschichte","title":"Olmeken-Köpfe","text":"Die Olmeken schufen monumentale Basaltköpfe, deren Stein teils über viele Kilometer transportiert wurde.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Olmeken-Köpfe"],"topicKey":"history-olmeken-kopfe"},{"id":"history-new-051","category":"Zeitepochen & Geschichte","title":"Nazca-Linien","text":"Die Nazca schufen riesige Linien und Figuren in der peruanischen Wüste. Ihre genaue Funktion wird weiterhin diskutiert.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Nazca-Linien"],"topicKey":"history-nazca-linien"},{"id":"history-new-052","category":"Zeitepochen & Geschichte","title":"Tiwanaku","text":"Tiwanaku am Titicacasee war lange vor den Inka ein bedeutendes religiöses und politisches Zentrum der Anden.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Tiwanaku"],"topicKey":"history-tiwanaku"},{"id":"history-new-053","category":"Zeitepochen & Geschichte","title":"Polynesische Navigation","text":"Polynesische Seefahrer navigierten über enorme Distanzen mit Sternen, Wellenmustern, Wind, Wolken und Verhalten von Tieren.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Polynesische Navigation"],"topicKey":"history-polynesische-navigation"},{"id":"history-new-054","category":"Zeitepochen & Geschichte","title":"Besiedlung Neuseelands","text":"Neuseeland wurde im Vergleich zu vielen anderen großen Landmassen sehr spät dauerhaft von Menschen besiedelt – durch polynesische Seefahrer.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Besiedlung Neuseelands"],"topicKey":"history-besiedlung-neuseelands"},{"id":"history-new-055","category":"Zeitepochen & Geschichte","title":"Viking Thing","text":"In der Wikingerzeit waren 'Things' Versammlungen für Recht, Streitfälle und politische Entscheidungen. Das Wort lebt in Namen wie dem isländischen Alþingi weiter.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Viking Thing"],"topicKey":"history-viking-thing"},{"id":"history-new-056","category":"Zeitepochen & Geschichte","title":"Runen","text":"Runen waren ein Schriftsystem germanischer Kulturen. Sie wurden nicht nur für magische Inschriften, sondern auch ganz praktische Mitteilungen genutzt.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Runen"],"topicKey":"history-runen"},{"id":"history-new-057","category":"Zeitepochen & Geschichte","title":"Langschiffe","text":"Wikingerschiffe kombinierten geringen Tiefgang mit Segel und Rudern. Dadurch konnten sie Meer, Küsten und Flüsse nutzen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Langschiffe"],"topicKey":"history-langschiffe"},{"id":"history-new-058","category":"Zeitepochen & Geschichte","title":"Vinland","text":"Nordische Seefahrer erreichten Nordamerika Jahrhunderte vor Kolumbus. Archäologisch gesichert ist eine Siedlung in L'Anse aux Meadows in Neufundland.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Vinland"],"topicKey":"history-vinland"},{"id":"history-new-059","category":"Zeitepochen & Geschichte","title":"Hanse","text":"Die Hanse war kein Staat, sondern ein Netzwerk von Kaufleuten und Städten, das Handel im Nord- und Ostseeraum dominierte.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Hanse"],"topicKey":"history-hanse"},{"id":"history-new-060","category":"Zeitepochen & Geschichte","title":"Mittelalterliche Zünfte","text":"Zünfte regelten Ausbildung, Qualität, Preise und Zugang zu vielen Handwerken. Wer Meister werden wollte, musste oft Jahre lernen und Prüfungen bestehen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Mittelalterliche Zünfte"],"topicKey":"history-mittelalterliche-zunfte"},{"id":"history-new-061","category":"Zeitepochen & Geschichte","title":"Mittelalterliche Universitäten","text":"Universitäten wie Bologna, Paris und Oxford entwickelten sich im Mittelalter zu dauerhaften Lehrgemeinschaften mit eigenen Rechten.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Mittelalterliche Universitäten"],"topicKey":"history-mittelalterliche-universitaten"},{"id":"history-new-062","category":"Zeitepochen & Geschichte","title":"Buch der Stunden","text":"Im späten Mittelalter war das Stundenbuch ein besonders verbreitetes privates Andachtsbuch. Wohlhabende Besitzer ließen Exemplare aufwendig illustrieren.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Buch der Stunden"],"topicKey":"history-buch-der-stunden"},{"id":"history-new-063","category":"Zeitepochen & Geschichte","title":"Pilgerreisen","text":"Pilgerreisen verbanden Religion mit Reisen, Handel und kulturellem Austausch. Orte entlang wichtiger Routen profitierten wirtschaftlich.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Pilgerreisen"],"topicKey":"history-pilgerreisen"},{"id":"history-new-064","category":"Zeitepochen & Geschichte","title":"Reliquienhandel","text":"Reliquien spielten im mittelalterlichen Europa eine enorme religiöse und wirtschaftliche Rolle. Ihre Echtheit war allerdings oft schwer nachprüfbar.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Reliquienhandel"],"topicKey":"history-reliquienhandel"},{"id":"history-new-065","category":"Zeitepochen & Geschichte","title":"Gotische Kathedralen","text":"Spitzbogen, Kreuzrippengewölbe und Strebewerk ermöglichten in der Gotik höhere Kirchen und größere Fensterflächen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Gotische Kathedralen"],"topicKey":"history-gotische-kathedralen"},{"id":"history-new-066","category":"Zeitepochen & Geschichte","title":"Mechanische Turmuhren","text":"Mechanische Uhren veränderten das Zeitgefühl mittelalterlicher Städte. Glockenschläge machten Stunden öffentlich hörbar.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Mechanische Turmuhren"],"topicKey":"history-mechanische-turmuhren"},{"id":"history-new-067","category":"Zeitepochen & Geschichte","title":"Quarantäne","text":"Der Begriff Quarantäne hängt mit einer vierzigtägigen Isolationsfrist zusammen, die in Hafenstädten gegen Seucheneinschleppung genutzt wurde.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Quarantäne"],"topicKey":"history-quarantane"},{"id":"history-new-068","category":"Zeitepochen & Geschichte","title":"Schwarzer Tod","text":"Die Pestpandemie des 14. Jahrhunderts tötete einen enormen Anteil der europäischen Bevölkerung und veränderte Wirtschaft, Arbeit und Gesellschaft.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Schwarzer Tod"],"topicKey":"history-schwarzer-tod"},{"id":"history-new-069","category":"Zeitepochen & Geschichte","title":"Renaissance-Perspektive","text":"Künstler der Renaissance entwickelten mathematische Verfahren, um räumliche Tiefe auf flachen Bildern überzeugender darzustellen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Renaissance-Perspektive"],"topicKey":"history-renaissance-perspektive"},{"id":"history-new-070","category":"Zeitepochen & Geschichte","title":"Anatomische Sektionen","text":"Renaissance-Mediziner untersuchten menschliche Körper systematischer. Andreas Vesalius korrigierte dadurch zahlreiche alte anatomische Annahmen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Anatomische Sektionen"],"topicKey":"history-anatomische-sektionen"},{"id":"history-new-071","category":"Zeitepochen & Geschichte","title":"Buchdruck","text":"Gutenbergs Kombination aus beweglichen Metalllettern, Presse, Tinte und Produktionsorganisation machte Bücher in Europa deutlich schneller reproduzierbar.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Buchdruck"],"topicKey":"history-buchdruck"},{"id":"history-new-072","category":"Zeitepochen & Geschichte","title":"Frühe Zeitungen","text":"Regelmäßig erscheinende Nachrichtenblätter entstanden in Europa im frühen 17. Jahrhundert und machten aktuelle Informationen zu einem handelbaren Produkt.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Frühe Zeitungen"],"topicKey":"history-fruhe-zeitungen"},{"id":"history-new-073","category":"Zeitepochen & Geschichte","title":"Kaffeehäuser","text":"Europäische Kaffeehäuser wurden zu Treffpunkten für Handel, Politik, Nachrichten und Debatten. Manche entwickelten sich zu Keimzellen späterer Institutionen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Kaffeehäuser"],"topicKey":"history-kaffeehauser"},{"id":"history-new-074","category":"Zeitepochen & Geschichte","title":"Lloyd's Coffee House","text":"Aus einem Londoner Kaffeehaus, in dem sich Händler und Schiffsinteressenten trafen, entwickelte sich langfristig Lloyd's als Zentrum der Seeversicherung.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Lloyd's Coffee House"],"topicKey":"history-lloyd-s-coffee-house"},{"id":"history-new-075","category":"Zeitepochen & Geschichte","title":"Tulpenhandel","text":"Die niederländische Tulpenmanie war real, wird aber oft dramatischer erzählt als die Quellen hergeben. Nicht die gesamte niederländische Wirtschaft brach deshalb zusammen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Tulpenhandel"],"topicKey":"history-tulpenhandel"},{"id":"history-new-076","category":"Zeitepochen & Geschichte","title":"Postkutschen","text":"Postkutschen transportierten nicht nur Briefe, sondern auch Passagiere. Fahrpläne und Stationen halfen, Fernreisen planbarer zu machen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Postkutschen"],"topicKey":"history-postkutschen"},{"id":"history-new-077","category":"Zeitepochen & Geschichte","title":"Pockenimpfung","text":"Edward Jenner zeigte Ende des 18. Jahrhunderts, dass eine Kuhpockeninfektion Schutz gegen Pocken vermitteln konnte. Daraus entstand die moderne Impfung.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Pockenimpfung"],"topicKey":"history-pockenimpfung"},{"id":"history-new-078","category":"Zeitepochen & Geschichte","title":"Industrialisierung und Fabrikuhr","text":"Fabrikarbeit machte genau gemessene Arbeitszeiten wichtiger. Glocke und Uhr strukturierten Arbeit stärker als bei vielen traditionellen Tätigkeiten.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Industrialisierung und Fabrikuhr"],"topicKey":"history-industrialisierung-und-fabrikuhr"},{"id":"history-new-079","category":"Zeitepochen & Geschichte","title":"Ludditen","text":"Die Ludditen waren keine pauschalen Technikfeinde. Viele protestierten gegen konkrete Maschinen, Lohnsenkungen und verschlechterte Arbeitsbedingungen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Ludditen"],"topicKey":"history-ludditen"},{"id":"history-new-080","category":"Zeitepochen & Geschichte","title":"Dampfmaschine","text":"Dampfmaschinen wurden nicht von einer Person erfunden. Verbesserungen über Jahrzehnte machten sie effizient genug für Bergbau, Fabriken und Verkehr.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Dampfmaschine"],"topicKey":"history-dampfmaschine"},{"id":"history-new-081","category":"Zeitepochen & Geschichte","title":"Eisenbahnzeit","text":"Unterschiedliche Ortszeiten wurden mit schnellen Eisenbahnen problematisch. Standardisierte Zeit wurde deshalb für Fahrpläne und Kommunikation immer wichtiger.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Eisenbahnzeit"],"topicKey":"history-eisenbahnzeit"},{"id":"history-new-082","category":"Zeitepochen & Geschichte","title":"Telegraf","text":"Der elektrische Telegraf machte Nachrichtenübermittlung über weite Distanzen erstmals nahezu unabhängig von Reisegeschwindigkeit.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Telegraf"],"topicKey":"history-telegraf"},{"id":"history-new-083","category":"Zeitepochen & Geschichte","title":"Unterseekabel","text":"Transatlantische Telegrafenkabel verkürzten Nachrichtenlaufzeiten zwischen Europa und Nordamerika von Tagen oder Wochen auf Minuten.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Unterseekabel"],"topicKey":"history-unterseekabel"},{"id":"history-new-084","category":"Zeitepochen & Geschichte","title":"Cholera und Kanalisation","text":"Cholera-Epidemien förderten im 19. Jahrhundert Untersuchungen zu Trinkwasser und Abwasser. Moderne Kanalisation wurde zu einer zentralen Gesundheitsmaßnahme.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Cholera und Kanalisation"],"topicKey":"history-cholera-und-kanalisation"},{"id":"history-new-085","category":"Zeitepochen & Geschichte","title":"John Snows Karte","text":"John Snow kartierte 1854 Cholera-Fälle in London und verband viele Erkrankungen mit einer Wasserpumpe in der Broad Street.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","John Snows Karte"],"topicKey":"history-john-snows-karte"},{"id":"history-new-086","category":"Zeitepochen & Geschichte","title":"Öffentliche Straßenbeleuchtung","text":"Gaslaternen und später elektrisches Licht verlängerten den nutzbaren Stadtabend und veränderten Sicherheit, Arbeit und Nachtleben.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Öffentliche Straßenbeleuchtung"],"topicKey":"history-offentliche-stra-enbeleuchtung"},{"id":"history-new-087","category":"Zeitepochen & Geschichte","title":"Hausnummern","text":"Hausnummern verbreiteten sich mit wachsender Verwaltung, Postzustellung, Steuern und Polizei. Die Idee, jedes Haus eindeutig zu nummerieren, war einmal neu.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Hausnummern"],"topicKey":"history-hausnummern"},{"id":"history-new-088","category":"Zeitepochen & Geschichte","title":"Müllabfuhr","text":"Regelmäßige kommunale Müllentsorgung wurde mit großen Städten und neuen Hygienevorstellungen im 19. und 20. Jahrhundert immer wichtiger.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Müllabfuhr"],"topicKey":"history-mullabfuhr"},{"id":"history-new-089","category":"Zeitepochen & Geschichte","title":"Öffentliche Parks","text":"Große Stadtparks entstanden im 19. Jahrhundert auch als Reaktion auf dichte, industrialisierte Städte und sollten Erholung sowie frische Luft bieten.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Öffentliche Parks"],"topicKey":"history-offentliche-parks"},{"id":"history-new-090","category":"Zeitepochen & Geschichte","title":"Weltausstellungen","text":"Weltausstellungen präsentierten Technik, Industrie und koloniale Macht. Viele berühmte Bauwerke entstanden ursprünglich als temporäre Ausstellungsarchitektur.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Weltausstellungen"],"topicKey":"history-weltausstellungen"},{"id":"history-new-091","category":"Zeitepochen & Geschichte","title":"Eiffelturm","text":"Der Eiffelturm wurde für die Pariser Weltausstellung 1889 gebaut und war ursprünglich keineswegs von allen Parisern geliebt.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Eiffelturm"],"topicKey":"history-eiffelturm"},{"id":"history-new-093","category":"Zeitepochen & Geschichte","title":"Krieg und Fotografie","text":"Im 19. Jahrhundert erreichten Kriegsfotografien ein breites Publikum. Wegen langer Belichtungszeiten zeigen frühe Bilder jedoch selten tatsächliche Kampfhandlungen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Krieg und Fotografie"],"topicKey":"history-krieg-und-fotografie"},{"id":"history-new-094","category":"Zeitepochen & Geschichte","title":"Lochkarten","text":"Lochkarten wurden zunächst auch zur Steuerung von Webstühlen genutzt. Später wurden sie ein wichtiges Medium für Datenverarbeitung.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Lochkarten"],"topicKey":"history-lochkarten"},{"id":"history-new-096","category":"Zeitepochen & Geschichte","title":"Telefonvermittlung","text":"Frühe Telefonnetze brauchten menschliche Vermittler, die Leitungen per Hand zusammensteckten. Telefonieren bedeutete zuerst: einen Menschen dazwischen haben.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Telefonvermittlung"],"topicKey":"history-telefonvermittlung"},{"id":"history-new-097","category":"Zeitepochen & Geschichte","title":"Kaufhaus","text":"Große Warenhäuser des 19. Jahrhunderts machten Einkaufen zu einem eigenen Freizeiterlebnis und kombinierten viele Warengruppen unter einem Dach.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.britishmuseum.org/collection","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Kaufhaus"],"topicKey":"history-kaufhaus"},{"id":"history-new-098","category":"Zeitepochen & Geschichte","title":"Versandkatalog","text":"Versandkataloge brachten Menschen auf dem Land Zugang zu einer enormen Auswahl an Waren, lange bevor Online-Shopping existierte.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Versandkatalog"],"topicKey":"history-versandkatalog"},{"id":"history-new-104","category":"Zeitepochen & Geschichte","title":"Supermarkt","text":"Selbstbedienungs-Supermärkte veränderten Einkauf, Verpackung und Werbung. Kunden holten Waren nun selbst aus Regalen statt sie einem Verkäufer zu nennen.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.nps.gov/subjects/history/index.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Supermarkt"],"topicKey":"history-supermarkt"},{"id":"history-new-105","category":"Zeitepochen & Geschichte","title":"Plastikzeitalter","text":"Kunststoffe wurden im 20. Jahrhundert zum Massenmaterial. Sie ermöglichten billige, leichte Produkte, schufen aber zugleich ein dauerhaftes Umweltproblem.","source":"The Metropolitan Museum of Art / British Museum / National Park Service","sourceUrl":"https://www.metmuseum.org/de/essays/timeline-of-art-history","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte","Plastikzeitalter"],"topicKey":"history-plastikzeitalter"},{"id":"wissen-new-001","category":"Wusstest du eigentlich …?","title":"Badewannen-Finger","text":"Finger und Zehen werden im Wasser nicht einfach nur 'aufgeweicht'. Nerven steuern eine Verengung von Blutgefäßen, wodurch sich die Hautoberfläche faltet – vermutlich mit funktionalem Vorteil beim Greifen nasser Dinge.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Badewannen-Finger"],"topicKey":"fact-badewannen-finger"},{"id":"wissen-new-002","category":"Wusstest du eigentlich …?","title":"Gähnen ist ansteckend","text":"Gähnen kann sozial ansteckend sein. Warum genau wir überhaupt gähnen, ist wissenschaftlich noch nicht vollständig geklärt; mehrere Funktionen werden diskutiert.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Gähnen ist ansteckend"],"topicKey":"fact-gahnen-ist-ansteckend"},{"id":"wissen-new-003","category":"Wusstest du eigentlich …?","title":"Drainage-Mythos","text":"Ein Waschbecken läuft nicht automatisch wegen der Erdhalbkugel links- oder rechtsherum ab. Form des Beckens und Bewegung des Wassers sind im Alltag viel entscheidender als die Corioliskraft.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Drainage-Mythos"],"topicKey":"fact-drainage-mythos"},{"id":"wissen-new-004","category":"Wusstest du eigentlich …?","title":"Steine hüpfen","text":"Damit ein flacher Stein über Wasser springt, sind Geschwindigkeit, Rotation, Form und vor allem Auftreffwinkel entscheidend.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Steine hüpfen"],"topicKey":"fact-steine-hupfen"},{"id":"wissen-new-005","category":"Wusstest du eigentlich …?","title":"Statische Elektrizität","text":"Der kleine Schlag an einer Türklinke entsteht durch eine Ladungsdifferenz. Beim Kontakt gleichen sich elektrische Ladungen schlagartig aus.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Statische Elektrizität"],"topicKey":"fact-statische-elektrizitat"},{"id":"wissen-new-006","category":"Wusstest du eigentlich …?","title":"Ei auf dem Bürgersteig","text":"Ein Ei kann theoretisch auf einer extrem heißen Oberfläche garen. Normale sonnige Gehwege werden aber meist nicht heiß genug, um das zuverlässig zu schaffen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Ei auf dem Bürgersteig"],"topicKey":"fact-ei-auf-dem-burgersteig"},{"id":"wissen-new-007","category":"Wusstest du eigentlich …?","title":"UV bleicht Farben","text":"Ultraviolettes Licht kann Farbstoffmoleküle chemisch verändern. Deshalb verblassen Stoffe, Bilder und Schilder in starker Sonne.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","UV bleicht Farben"],"topicKey":"fact-uv-bleicht-farben"},{"id":"wissen-new-008","category":"Wusstest du eigentlich …?","title":"Looping hält dich im Sitz","text":"Bei einer Achterbahn im Looping sorgt die Bewegung dafür, dass du zur Bahn gedrückt wirst. Ein loser Mensch fällt also nicht einfach am Scheitelpunkt heraus.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Looping hält dich im Sitz"],"topicKey":"fact-looping-halt-dich-im-sitz"},{"id":"wissen-new-009","category":"Wusstest du eigentlich …?","title":"Aurora","text":"Polarlichter entstehen, wenn geladene Teilchen aus dem Sonnenwind mit Teilchen in der oberen Atmosphäre wechselwirken.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Aurora"],"topicKey":"fact-aurora"},{"id":"wissen-new-010","category":"Wusstest du eigentlich …?","title":"Schwarzes Loch","text":"Ein Schwarzes Loch ist kein kosmischer Staubsauger, der automatisch alles verschluckt. In ausreichender Entfernung verhält sich seine Gravitation wie die jedes anderen Objekts gleicher Masse.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Schwarzes Loch"],"topicKey":"fact-schwarzes-loch"},{"id":"wissen-new-011","category":"Wusstest du eigentlich …?","title":"Blue Moon","text":"Ein 'Blue Moon' ist meist gar nicht blau. Der Ausdruck bezeichnet heute gewöhnlich einen zusätzlichen Vollmond innerhalb bestimmter Kalenderdefinitionen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Blue Moon"],"topicKey":"fact-blue-moon"},{"id":"wissen-new-012","category":"Wusstest du eigentlich …?","title":"Pluto","text":"Pluto wurde 2006 als Zwergplanet eingestuft, weil er die Umgebung seiner Umlaufbahn nicht dynamisch dominiert.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Pluto"],"topicKey":"fact-pluto"},{"id":"wissen-new-013","category":"Wusstest du eigentlich …?","title":"Merkur-Jahr","text":"Ein Merkurjahr dauert nur etwa 88 Erdtage. Der Planet rast also deutlich schneller um die Sonne als die Erde.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Merkur-Jahr"],"topicKey":"fact-merkur-jahr"},{"id":"wissen-new-014","category":"Wusstest du eigentlich …?","title":"Merkur-Tag","text":"Von einem Sonnenaufgang bis zum nächsten vergehen auf Merkur etwa 176 Erdtage – länger als zwei Merkurjahre.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Merkur-Tag"],"topicKey":"fact-merkur-tag"},{"id":"wissen-new-015","category":"Wusstest du eigentlich …?","title":"Saturn-Dichte","text":"Saturn hat im Mittel eine geringere Dichte als Wasser. In einer absurd großen Badewanne würde er theoretisch schwimmen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Saturn-Dichte"],"topicKey":"fact-saturn-dichte"},{"id":"wissen-new-016","category":"Wusstest du eigentlich …?","title":"Neptun-Winde","text":"Auf Neptun wurden einige der schnellsten Winde im Sonnensystem gemessen – weit schneller als die stärksten irdischen Hurrikane.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Neptun-Winde"],"topicKey":"fact-neptun-winde"},{"id":"wissen-new-017","category":"Wusstest du eigentlich …?","title":"Mars-Sonnenuntergang","text":"Auf dem Mars kann der Bereich um die untergehende Sonne bläulich erscheinen – ziemlich genau das Gegenteil des typischen rötlichen Eindrucks auf der Erde.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Mars-Sonnenuntergang"],"topicKey":"fact-mars-sonnenuntergang"},{"id":"wissen-new-018","category":"Wusstest du eigentlich …?","title":"Mond-Fußspuren","text":"Auf dem Mond gibt es weder Wind noch flüssiges Oberflächenwasser wie auf der Erde. Fußspuren können deshalb extrem lange erhalten bleiben.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Mond-Fußspuren"],"topicKey":"fact-mond-fu-spuren"},{"id":"wissen-new-019","category":"Wusstest du eigentlich …?","title":"Mond-Erdbeben","text":"Auch der Mond bebt. Einige Mondbeben können deutlich länger anhalten als typische Erdbeben auf der Erde.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Mond-Erdbeben"],"topicKey":"fact-mond-erdbeben"},{"id":"wissen-new-020","category":"Wusstest du eigentlich …?","title":"ISS-Tag","text":"Die Internationale Raumstation umrundet die Erde ungefähr alle anderthalb Stunden. Ihre Besatzung kann dadurch an einem Tag viele Sonnenauf- und -untergänge sehen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","ISS-Tag"],"topicKey":"fact-iss-tag"},{"id":"wissen-new-021","category":"Wusstest du eigentlich …?","title":"Weltraumanzug-Geruch","text":"Astronauten berichten nach Außenbordeinsätzen immer wieder von ungewöhnlichen Gerüchen an Material, das wieder in die Station gebracht wird. Der Weltraum selbst kann im Vakuum natürlich nicht direkt gerochen werden.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Weltraumanzug-Geruch"],"topicKey":"fact-weltraumanzug-geruch"},{"id":"wissen-new-022","category":"Wusstest du eigentlich …?","title":"Erdkern","text":"Der innere Erdkern besteht hauptsächlich aus Eisen und Nickel und steht unter so hohem Druck, dass er trotz enormer Temperatur fest ist.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Erdkern"],"topicKey":"fact-erdkern"},{"id":"wissen-new-023","category":"Wusstest du eigentlich …?","title":"Magnetischer Nordpol","text":"Der magnetische Nordpol ist kein fester Punkt. Er wandert, weil sich Strömungen im flüssigen äußeren Erdkern verändern.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Magnetischer Nordpol"],"topicKey":"fact-magnetischer-nordpol"},{"id":"wissen-new-024","category":"Wusstest du eigentlich …?","title":"Kontinente bewegen sich","text":"Tektonische Platten bewegen sich meist nur Zentimeter pro Jahr – ungefähr in der Größenordnung, in der Fingernägel wachsen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Kontinente bewegen sich"],"topicKey":"fact-kontinente-bewegen-sich"},{"id":"wissen-new-025","category":"Wusstest du eigentlich …?","title":"Antarktisches Eis","text":"Unter dem antarktischen Eisschild liegen Gebirge, Täler und sogar subglaziale Seen, die an der Oberfläche kaum zu erkennen sind.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Antarktisches Eis"],"topicKey":"fact-antarktisches-eis"},{"id":"wissen-new-026","category":"Wusstest du eigentlich …?","title":"Gletscher fließen","text":"Gletscher wirken wie starres Eis, bewegen sich aber unter ihrem eigenen Gewicht langsam talabwärts.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Gletscher fließen"],"topicKey":"fact-gletscher-flie-en"},{"id":"wissen-new-027","category":"Wusstest du eigentlich …?","title":"Vulkane unter Wasser","text":"Ein großer Teil des weltweiten Vulkanismus findet unter dem Meer statt, besonders entlang mittelozeanischer Rücken.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Vulkane unter Wasser"],"topicKey":"fact-vulkane-unter-wasser"},{"id":"wissen-new-028","category":"Wusstest du eigentlich …?","title":"Schwarze Raucher","text":"Hydrothermale Quellen am Meeresboden stoßen extrem heißes, mineralreiches Wasser aus. Rund um manche Quellen leben Ökosysteme ohne Sonnenlicht als Energiequelle.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Schwarze Raucher"],"topicKey":"fact-schwarze-raucher"},{"id":"wissen-new-029","category":"Wusstest du eigentlich …?","title":"Meeresspiegel und Gezeiten","text":"Gezeiten entstehen vor allem durch die Gravitation von Mond und Sonne. Küstenform und Wassertiefe bestimmen stark, wie groß der Tidenhub lokal ausfällt.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Meeresspiegel und Gezeiten"],"topicKey":"fact-meeresspiegel-und-gezeiten"},{"id":"wissen-new-030","category":"Wusstest du eigentlich …?","title":"Meerwasser ist nicht überall gleich salzig","text":"Verdunstung, Niederschlag, Flüsse und Eisbildung verändern den Salzgehalt. Deshalb ist Meerwasser regional unterschiedlich salzig.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Meerwasser ist nicht überall gleich salzig"],"topicKey":"fact-meerwasser-ist-nicht-uberall-gleich-salzig"},{"id":"wissen-new-031","category":"Wusstest du eigentlich …?","title":"Tsunami auf hoher See","text":"Ein Tsunami kann auf dem offenen Ozean vergleichsweise niedrig sein und erst nahe der Küste stark anwachsen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Tsunami auf hoher See"],"topicKey":"fact-tsunami-auf-hoher-see"},{"id":"wissen-new-032","category":"Wusstest du eigentlich …?","title":"Tiefseeberge","text":"Seamounts sind Unterwasserberge, die meist vulkanischen Ursprungs sind und oft eigene Lebensgemeinschaften tragen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Tiefseeberge"],"topicKey":"fact-tiefseeberge"},{"id":"wissen-new-033","category":"Wusstest du eigentlich …?","title":"Ozeanboden-Karten","text":"Der Meeresboden ist noch längst nicht vollständig hochauflösend kartiert. Satelliten liefern nur indirekte Hinweise auf viele Strukturen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Ozeanboden-Karten"],"topicKey":"fact-ozeanboden-karten"},{"id":"wissen-new-034","category":"Wusstest du eigentlich …?","title":"Ozean als Wärmespeicher","text":"Der Ozean speichert riesige Wärmemengen und verteilt sie über Strömungen. Dadurch beeinflusst er Wetter und Klima weit über Küsten hinaus.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Ozean als Wärmespeicher"],"topicKey":"fact-ozean-als-warmespeicher"},{"id":"wissen-new-035","category":"Wusstest du eigentlich …?","title":"Gas-Hydrate","text":"In kalten Tiefseesedimenten können eisähnliche Gashydrate entstehen, in denen Gasmoleküle in Wasserstrukturen eingeschlossen sind.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Gas-Hydrate"],"topicKey":"fact-gas-hydrate"},{"id":"wissen-new-038","category":"Wusstest du eigentlich …?","title":"Regenbogen","text":"Ein Regenbogen ist eigentlich ein vollständiger Kreis. Vom Boden sehen wir meist nur einen Bogen, weil Horizont und Erde den Rest verdecken.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Regenbogen"],"topicKey":"fact-regenbogen"},{"id":"wissen-new-039","category":"Wusstest du eigentlich …?","title":"Hagel","text":"Hagelkörner wachsen in Gewitterwolken, wenn starke Aufwinde Eisteilchen wiederholt durch Bereiche mit unterkühltem Wasser tragen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Hagel"],"topicKey":"fact-hagel"},{"id":"wissen-new-040","category":"Wusstest du eigentlich …?","title":"Schnee knirscht","text":"Sehr kalter Schnee kann stärker knirschen, weil die Eiskristalle härter und spröder sind als bei Temperaturen nahe dem Gefrierpunkt.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Schnee knirscht"],"topicKey":"fact-schnee-knirscht"},{"id":"wissen-new-041","category":"Wusstest du eigentlich …?","title":"Nebel ist eine Wolke","text":"Nebel ist physikalisch im Grunde eine Wolke am Boden: winzige Wassertröpfchen oder Eiskristalle schweben nahe der Erdoberfläche.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Nebel ist eine Wolke"],"topicKey":"fact-nebel-ist-eine-wolke"},{"id":"wissen-new-042","category":"Wusstest du eigentlich …?","title":"Luftdruck und Höhe","text":"Mit zunehmender Höhe sinkt der Luftdruck, weil weniger Luftmasse über einem liegt.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Luftdruck und Höhe"],"topicKey":"fact-luftdruck-und-hohe"},{"id":"wissen-new-043","category":"Wusstest du eigentlich …?","title":"Wasser kocht im Gebirge früher","text":"Bei geringerem Luftdruck liegt der Siedepunkt von Wasser niedriger. Deshalb kocht Wasser auf hohen Bergen bei weniger als 100 °C.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Wasser kocht im Gebirge früher"],"topicKey":"fact-wasser-kocht-im-gebirge-fruher"},{"id":"wissen-new-044","category":"Wusstest du eigentlich …?","title":"Schall in Wasser","text":"Schall breitet sich in Wasser deutlich schneller aus als in Luft. Deshalb können Meeressäuger über große Distanzen akustisch kommunizieren.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Schall in Wasser"],"topicKey":"fact-schall-in-wasser"},{"id":"wissen-new-045","category":"Wusstest du eigentlich …?","title":"Metall klingt nicht immer gleich","text":"Die Tonhöhe eines Metallgegenstands hängt nicht nur vom Material ab, sondern auch von Form, Größe, Spannung und Befestigung.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Metall klingt nicht immer gleich"],"topicKey":"fact-metall-klingt-nicht-immer-gleich"},{"id":"wissen-new-046","category":"Wusstest du eigentlich …?","title":"Glas ist kein zähflüssiger Fluss","text":"Altes Fensterglas ist unten nicht dicker, weil Glas über Jahrhunderte nach unten fließt. Die Unterschiede stammen vor allem aus alten Herstellungsverfahren.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Glas ist kein zähflüssiger Fluss"],"topicKey":"fact-glas-ist-kein-zahflussiger-fluss"},{"id":"wissen-new-047","category":"Wusstest du eigentlich …?","title":"Diamant kann brennen","text":"Diamant besteht aus Kohlenstoff und kann bei ausreichend hoher Temperatur in Sauerstoff verbrennen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Diamant kann brennen"],"topicKey":"fact-diamant-kann-brennen"},{"id":"wissen-new-048","category":"Wusstest du eigentlich …?","title":"Gallium schmilzt in der Hand","text":"Gallium hat einen Schmelzpunkt knapp über Raumtemperatur und kann deshalb in einer warmen Hand flüssig werden.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Gallium schmilzt in der Hand"],"topicKey":"fact-gallium-schmilzt-in-der-hand"},{"id":"wissen-new-049","category":"Wusstest du eigentlich …?","title":"Brom ist flüssig","text":"Brom ist neben Quecksilber eines der wenigen Elemente, die bei gewöhnlicher Raumtemperatur flüssig sind.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Brom ist flüssig"],"topicKey":"fact-brom-ist-flussig"},{"id":"wissen-new-050","category":"Wusstest du eigentlich …?","title":"Helium entkommt","text":"Helium ist so leicht, dass ein Teil davon langfristig aus der oberen Atmosphäre in den Weltraum entweichen kann.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Helium entkommt"],"topicKey":"fact-helium-entkommt"},{"id":"wissen-new-052","category":"Wusstest du eigentlich …?","title":"Heißes Wasser kann unter Bedingungen schneller frieren","text":"Unter bestimmten Versuchsbedingungen kann warmes Wasser schneller gefrieren als kälteres. Dieses sogenannte Mpemba-Phänomen ist stark von den Bedingungen abhängig.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Heißes Wasser kann unter Bedingungen schneller frieren"],"topicKey":"fact-hei-es-wasser-kann-unter-bedingungen-schneller-frieren"},{"id":"wissen-new-053","category":"Wusstest du eigentlich …?","title":"Seife macht Wasser 'nasser'","text":"Seife senkt die Oberflächenspannung von Wasser. Dadurch kann es Oberflächen besser benetzen und Schmutz leichter ablösen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Seife macht Wasser 'nasser'"],"topicKey":"fact-seife-macht-wasser-nasser"},{"id":"wissen-new-054","category":"Wusstest du eigentlich …?","title":"Öl und Wasser","text":"Öl und Wasser mischen sich schlecht, weil ihre Moleküle unterschiedlich mit elektrischen Ladungsverteilungen umgehen. Emulgatoren können beide Phasen stabil verbinden.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Öl und Wasser"],"topicKey":"fact-ol-und-wasser"},{"id":"wissen-new-055","category":"Wusstest du eigentlich …?","title":"Popcorn","text":"Popcorn platzt, weil Wasser im Korn zu Dampf wird und der Druck die harte Schale sprengt. Die Stärke schäumt dabei schlagartig auf.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Popcorn"],"topicKey":"fact-popcorn"},{"id":"wissen-new-056","category":"Wusstest du eigentlich …?","title":"Brause zischt","text":"Kohlendioxid ist unter Druck im Getränk gelöst. Beim Öffnen sinkt der Druck, das Gas bildet Blasen und entweicht.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Brause zischt"],"topicKey":"fact-brause-zischt"},{"id":"wissen-new-057","category":"Wusstest du eigentlich …?","title":"Scharf ist kein Geschmack","text":"Capsaicin aus Chili aktiviert Wärme- und Schmerzrezeptoren. 'Scharf' ist deshalb eher ein Schmerz-/Temperaturreiz als eine klassische Geschmacksrichtung.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Scharf ist kein Geschmack"],"topicKey":"fact-scharf-ist-kein-geschmack"},{"id":"wissen-new-058","category":"Wusstest du eigentlich …?","title":"Minze fühlt sich kalt an","text":"Menthol aktiviert Kälterezeptoren, ohne die Temperatur tatsächlich stark zu senken.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Minze fühlt sich kalt an"],"topicKey":"fact-minze-fuhlt-sich-kalt-an"},{"id":"wissen-new-060","category":"Wusstest du eigentlich …?","title":"Honig kristallisiert","text":"Kristallisierter Honig ist nicht automatisch verdorben. Je nach Zuckerzusammensetzung bilden sich mit der Zeit Glukosekristalle.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Honig kristallisiert"],"topicKey":"fact-honig-kristallisiert"},{"id":"wissen-new-061","category":"Wusstest du eigentlich …?","title":"Käse-Löcher","text":"Die Löcher mancher Käsesorten entstehen durch Gase, die Bakterien während der Reifung produzieren.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Käse-Löcher"],"topicKey":"fact-kase-locher"},{"id":"wissen-new-062","category":"Wusstest du eigentlich …?","title":"Brot wird altbacken","text":"Altbackenes Brot verliert nicht nur Wasser. Vor allem verändert sich die Struktur der Stärke – deshalb kann Erwärmen Brot vorübergehend wieder weicher machen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Brot wird altbacken"],"topicKey":"fact-brot-wird-altbacken"},{"id":"wissen-new-063","category":"Wusstest du eigentlich …?","title":"Kaffee enthält viele Aromastoffe","text":"Kaffee gehört chemisch zu den komplexesten Alltagsgetränken: Beim Rösten entstehen Hunderte flüchtige Aromastoffe.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Kaffee enthält viele Aromastoffe"],"topicKey":"fact-kaffee-enthalt-viele-aromastoffe"},{"id":"wissen-new-064","category":"Wusstest du eigentlich …?","title":"Karotten und Sehen","text":"Vitamin A ist für normales Sehen wichtig, aber zusätzliche Karotten verleihen Menschen mit ausreichender Versorgung keine Super-Nachtsicht.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Karotten und Sehen"],"topicKey":"fact-karotten-und-sehen"},{"id":"wissen-new-065","category":"Wusstest du eigentlich …?","title":"Spinat und Eisen","text":"Spinat enthält Eisen, ist aber kein außergewöhnliches Eisenwunder. Viele Lebensmittel liefern pro Portion ähnlich viel oder mehr verfügbares Eisen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Spinat und Eisen"],"topicKey":"fact-spinat-und-eisen"},{"id":"wissen-new-066","category":"Wusstest du eigentlich …?","title":"Möhren waren nicht immer orange","text":"Historische Karottensorten gab es in mehreren Farben. Orangefarbene Sorten wurden später besonders populär.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Möhren waren nicht immer orange"],"topicKey":"fact-mohren-waren-nicht-immer-orange"},{"id":"wissen-new-067","category":"Wusstest du eigentlich …?","title":"Kartoffeln wurden misstrauisch beäugt","text":"Als Kartoffeln nach Europa kamen, begegneten ihnen viele Menschen zunächst skeptisch. Erst allmählich wurden sie zu einem Grundnahrungsmittel.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Kartoffeln wurden misstrauisch beäugt"],"topicKey":"fact-kartoffeln-wurden-misstrauisch-beaugt"},{"id":"wissen-new-068","category":"Wusstest du eigentlich …?","title":"Tomaten galten als verdächtig","text":"Tomaten wurden in Europa lange eher als Zierpflanzen betrachtet und nicht überall sofort als Lebensmittel akzeptiert.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Tomaten galten als verdächtig"],"topicKey":"fact-tomaten-galten-als-verdachtig"},{"id":"wissen-new-071","category":"Wusstest du eigentlich …?","title":"Erdbeere ist Sammelnussfrucht","text":"Die kleinen 'Körnchen' außen an der Erdbeere sind einzelne Früchte. Das rote Fruchtfleisch ist botanisch nur der vergrößerte Blütenboden.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Erdbeere ist Sammelnussfrucht"],"topicKey":"fact-erdbeere-ist-sammelnussfrucht"},{"id":"wissen-new-072","category":"Wusstest du eigentlich …?","title":"Erdnuss ist keine Nuss","text":"Erdnüsse gehören zu den Hülsenfrüchten und sind näher mit Bohnen und Erbsen verwandt als mit Walnüssen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Erdnuss ist keine Nuss"],"topicKey":"fact-erdnuss-ist-keine-nuss"},{"id":"wissen-new-073","category":"Wusstest du eigentlich …?","title":"Cashew wächst außen","text":"Der Cashewkern sitzt außen am sogenannten Cashewapfel. Die Schale enthält reizende Stoffe und wird deshalb industriell entfernt.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Cashew wächst außen"],"topicKey":"fact-cashew-wachst-au-en"},{"id":"wissen-new-074","category":"Wusstest du eigentlich …?","title":"Muskat kann giftig sein","text":"Muskatnuss ist in Küchenmengen unproblematisch, sehr große Mengen können jedoch schwere Vergiftungserscheinungen auslösen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Muskat kann giftig sein"],"topicKey":"fact-muskat-kann-giftig-sein"},{"id":"wissen-new-075","category":"Wusstest du eigentlich …?","title":"Fingerabdrücke","text":"Fingerabdrücke entstehen schon vor der Geburt durch ein Zusammenspiel aus Genetik, Wachstum und mechanischen Einflüssen im Mutterleib.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Fingerabdrücke"],"topicKey":"fact-fingerabdrucke"},{"id":"wissen-new-077","category":"Wusstest du eigentlich …?","title":"Leber regeneriert","text":"Die Leber kann verlorenes Gewebe bemerkenswert gut nachbilden. Das bedeutet allerdings nicht, dass sie gegen dauerhafte Schäden immun ist.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Leber regeneriert"],"topicKey":"fact-leber-regeneriert"},{"id":"wissen-new-078","category":"Wusstest du eigentlich …?","title":"Magen verdaut sich nicht selbst","text":"Die Magenschleimhaut schützt sich mit Schleim, Bicarbonat und ständig erneuerten Zellen vor Säure und Verdauungsenzymen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Magen verdaut sich nicht selbst"],"topicKey":"fact-magen-verdaut-sich-nicht-selbst"},{"id":"wissen-new-079","category":"Wusstest du eigentlich …?","title":"Blut ist nie blau","text":"Menschliches Blut ist immer rot. Venen wirken durch Haut und Lichtstreuung manchmal blau oder grünlich.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Blut ist nie blau"],"topicKey":"fact-blut-ist-nie-blau"},{"id":"wissen-new-080","category":"Wusstest du eigentlich …?","title":"Geschmack hängt von Geruch ab","text":"Ein großer Teil dessen, was wir als Geschmack erleben, stammt aus Geruchsinformationen. Bei verstopfter Nase wirkt Essen deshalb oft fade.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Geschmack hängt von Geruch ab"],"topicKey":"fact-geschmack-hangt-von-geruch-ab"},{"id":"wissen-new-081","category":"Wusstest du eigentlich …?","title":"Schluckauf","text":"Schluckauf entsteht durch unwillkürliche Kontraktionen des Zwerchfells, gefolgt vom schnellen Verschluss der Stimmritze.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Schluckauf"],"topicKey":"fact-schluckauf"},{"id":"wissen-new-082","category":"Wusstest du eigentlich …?","title":"Ohrenschmalz","text":"Ohrenschmalz ist kein nutzloser Schmutz. Es hält den Gehörgang geschmeidig und hilft, Staub sowie kleine Partikel nach außen zu transportieren.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Ohrenschmalz"],"topicKey":"fact-ohrenschmalz"},{"id":"wissen-new-083","category":"Wusstest du eigentlich …?","title":"Tränen sind unterschiedlich","text":"Basale Tränen befeuchten das Auge ständig, Reflextränen reagieren etwa auf Reizstoffe und emotionale Tränen entstehen in emotionalen Situationen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Tränen sind unterschiedlich"],"topicKey":"fact-tranen-sind-unterschiedlich"},{"id":"wissen-new-084","category":"Wusstest du eigentlich …?","title":"Pupille ist ein Loch","text":"Die schwarze Pupille ist kein schwarzes Gewebe, sondern eine Öffnung in der Iris, durch die Licht ins Auge fällt.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Pupille ist ein Loch"],"topicKey":"fact-pupille-ist-ein-loch"},{"id":"wissen-new-086","category":"Wusstest du eigentlich …?","title":"Zähne sind keine Knochen","text":"Zähne und Knochen teilen Mineralstoffe, sind biologisch aber verschieden aufgebaut. Zahnschmelz ist das härteste Gewebe des menschlichen Körpers.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Zähne sind keine Knochen"],"topicKey":"fact-zahne-sind-keine-knochen"},{"id":"wissen-new-087","category":"Wusstest du eigentlich …?","title":"Haare sind außerhalb der Haut tot","text":"Der sichtbare Teil eines Haares besteht aus totem Keratin. Lebendige Zellen sitzen vor allem im Haarfollikel unter der Haut.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Haare sind außerhalb der Haut tot"],"topicKey":"fact-haare-sind-au-erhalb-der-haut-tot"},{"id":"wissen-new-088","category":"Wusstest du eigentlich …?","title":"Nägel wachsen unterschiedlich schnell","text":"Fingernägel wachsen typischerweise schneller als Fußnägel. Wachstumsgeschwindigkeit hängt außerdem von Alter, Gesundheit und Jahreszeit ab.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.usgs.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Nägel wachsen unterschiedlich schnell"],"topicKey":"fact-nagel-wachsen-unterschiedlich-schnell"},{"id":"wissen-new-089","category":"Wusstest du eigentlich …?","title":"Haut ist Organ","text":"Die Haut ist das größte Organ des menschlichen Körpers und erfüllt Aufgaben von Schutz über Temperaturregulation bis Sinneswahrnehmung.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.nist.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Haut ist Organ"],"topicKey":"fact-haut-ist-organ"},{"id":"wissen-new-090","category":"Wusstest du eigentlich …?","title":"Muskeln arbeiten oft paarweise","text":"Viele Bewegungen entstehen durch Gegenspieler: Ein Muskel zieht in eine Richtung, ein anderer ermöglicht die Gegenbewegung.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://www.loc.gov/everyday-mysteries/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Muskeln arbeiten oft paarweise"],"topicKey":"fact-muskeln-arbeiten-oft-paarweise"},{"id":"wissen-new-091","category":"Wusstest du eigentlich …?","title":"Knochen leben","text":"Knochen sind kein totes Gerüst. Sie werden ständig umgebaut und enthalten Blutgefäße sowie lebende Zellen.","source":"Library of Congress / NOAA / NASA / USGS / NIST","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Knochen leben"],"topicKey":"fact-knochen-leben"},{"id":"geo-001","category":"Geografie & Länder","title":"Antarktis ist die größte Wüste","text":"Eine Wüste wird über Niederschlag definiert, nicht über Hitze. Deshalb ist die Antarktis die größte Wüste der Erde.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Antarktis ist die größte Wüste"],"topicKey":"geo-antarktis-ist-die-gro-te-wuste"},{"id":"geo-002","category":"Geografie & Länder","title":"Grönland ist die größte Insel","text":"Wenn Kontinente nicht als Inseln gezählt werden, ist Grönland die größte Insel der Welt.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Grönland ist die größte Insel"],"topicKey":"geo-gronland-ist-die-gro-te-insel"},{"id":"geo-003","category":"Geografie & Länder","title":"Lesotho liegt vollständig in Südafrika","text":"Lesotho ist komplett von einem einzigen Staat umschlossen: Südafrika.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Lesotho liegt vollständig in Südafrika"],"topicKey":"geo-lesotho-liegt-vollstandig-in-sudafrika"},{"id":"geo-004","category":"Geografie & Länder","title":"San Marino liegt vollständig in Italien","text":"San Marino ist ein Kleinstaat, der vollständig von Italien umgeben ist.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","San Marino liegt vollständig in Italien"],"topicKey":"geo-san-marino-liegt-vollstandig-in-italien"},{"id":"geo-005","category":"Geografie & Länder","title":"Vatikanstadt ist der kleinste Staat","text":"Die Vatikanstadt ist nach Fläche der kleinste allgemein anerkannte souveräne Staat der Welt.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Vatikanstadt ist der kleinste Staat"],"topicKey":"geo-vatikanstadt-ist-der-kleinste-staat"},{"id":"geo-006","category":"Geografie & Länder","title":"Kasachstan ist größter Binnenstaat","text":"Kasachstan ist der flächenmäßig größte Staat ohne Zugang zu einem offenen Ozean.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Kasachstan ist größter Binnenstaat"],"topicKey":"geo-kasachstan-ist-gro-ter-binnenstaat"},{"id":"geo-007","category":"Geografie & Länder","title":"Bolivien hat zwei Hauptstadtrollen","text":"Sucre ist die verfassungsmäßige Hauptstadt Boliviens, während Regierung und Parlament in La Paz sitzen.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Bolivien hat zwei Hauptstadtrollen"],"topicKey":"geo-bolivien-hat-zwei-hauptstadtrollen"},{"id":"geo-008","category":"Geografie & Länder","title":"Salar de Uyuni","text":"Der Salar de Uyuni in Bolivien ist die größte Salzpfanne der Erde und kann nach Regen zu einer riesigen spiegelnden Fläche werden.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Salar de Uyuni"],"topicKey":"geo-salar-de-uyuni"},{"id":"geo-009","category":"Geografie & Länder","title":"Atacama","text":"Teile der Atacama-Wüste gehören zu den trockensten nichtpolaren Gebieten der Erde.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Atacama"],"topicKey":"geo-atacama"},{"id":"geo-010","category":"Geografie & Länder","title":"Namib","text":"Die Namib gilt als eine der ältesten dauerhaft trockenen Wüstenlandschaften der Welt.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Namib"],"topicKey":"geo-namib"},{"id":"geo-011","category":"Geografie & Länder","title":"Totes Meer","text":"Die Uferregion des Toten Meeres liegt tiefer als jede andere frei zugängliche Landoberfläche der Erde.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Totes Meer"],"topicKey":"geo-totes-meer"},{"id":"geo-012","category":"Geografie & Länder","title":"Kaspisches Meer","text":"Das Kaspische Meer ist trotz seines Namens ein abflussloser Binnensee und flächenmäßig der größte der Erde.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Kaspisches Meer"],"topicKey":"geo-kaspisches-meer"},{"id":"geo-013","category":"Geografie & Länder","title":"Baikalsee","text":"Der Baikalsee ist der tiefste See der Erde und enthält einen sehr großen Anteil des flüssigen Oberflächen-Süßwassers.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Baikalsee"],"topicKey":"geo-baikalsee"},{"id":"geo-014","category":"Geografie & Länder","title":"Titicacasee","text":"Der Titicacasee liegt auf über 3.800 Metern Höhe und wird von Peru und Bolivien geteilt.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Titicacasee"],"topicKey":"geo-titicacasee"},{"id":"geo-015","category":"Geografie & Länder","title":"Chimborazo","text":"Der Gipfel des Chimborazo in Ecuador liegt wegen der Erdabplattung weiter vom Erdmittelpunkt entfernt als der Mount Everest.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Chimborazo"],"topicKey":"geo-chimborazo"},{"id":"geo-016","category":"Geografie & Länder","title":"Mauna Kea","text":"Vom Meeresboden bis zum Gipfel gemessen ist Mauna Kea höher als der Mount Everest über dem Meeresspiegel.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Mauna Kea"],"topicKey":"geo-mauna-kea"},{"id":"geo-017","category":"Geografie & Länder","title":"Everest wächst und schrumpft","text":"Tektonische Prozesse heben den Himalaya weiter an, während Erosion gleichzeitig Material abträgt.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Everest wächst und schrumpft"],"topicKey":"geo-everest-wachst-und-schrumpft"},{"id":"geo-018","category":"Geografie & Länder","title":"Himalaya war Meeresboden","text":"Gesteine im Himalaya enthalten Meeresfossilien, weil sie aus Sedimenten eines früheren Ozeans entstanden.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Himalaya war Meeresboden"],"topicKey":"geo-himalaya-war-meeresboden"},{"id":"geo-019","category":"Geografie & Länder","title":"Marianengraben","text":"Der Challenger Deep im Marianengraben ist der tiefste bekannte Punkt des Weltmeeres.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Marianengraben"],"topicKey":"geo-marianengraben"},{"id":"geo-020","category":"Geografie & Länder","title":"Pazifik größer als alle Kontinente zusammen","text":"Die Fläche des Pazifiks ist größer als die gesamte Landfläche aller Kontinente zusammen.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Pazifik größer als alle Kontinente zusammen"],"topicKey":"geo-pazifik-gro-er-als-alle-kontinente-zusammen"},{"id":"geo-021","category":"Geografie & Länder","title":"Ring of Fire","text":"Rund um den Pazifik konzentrieren sich besonders viele aktive Vulkane und Erdbebenregionen.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Ring of Fire"],"topicKey":"geo-ring-of-fire"},{"id":"geo-022","category":"Geografie & Länder","title":"Island sitzt auf zwei Platten","text":"Island liegt auf dem Mittelatlantischen Rücken, an dem die Nordamerikanische und Eurasische Platte auseinanderdriften.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Island sitzt auf zwei Platten"],"topicKey":"geo-island-sitzt-auf-zwei-platten"},{"id":"geo-023","category":"Geografie & Länder","title":"Afrika reißt langsam auf","text":"Im Ostafrikanischen Grabenbruch wird die Erdkruste gedehnt. Langfristig kann dort ein neuer Ozean entstehen.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Afrika reißt langsam auf"],"topicKey":"geo-afrika-rei-t-langsam-auf"},{"id":"geo-024","category":"Geografie & Länder","title":"Rotes Meer wird breiter","text":"Das Rote Meer liegt in einer aktiven Riftzone und wird geologisch langsam breiter.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Rotes Meer wird breiter"],"topicKey":"geo-rotes-meer-wird-breiter"},{"id":"geo-025","category":"Geografie & Länder","title":"Nil-Länge ist kompliziert","text":"Welche Quelle als Beginn eines Flusses zählt, ist nicht immer eindeutig. Deshalb hängen exakte Längenangaben großer Flüsse von Definition und Messmethode ab.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Nil-Länge ist kompliziert"],"topicKey":"geo-nil-lange-ist-kompliziert"},{"id":"geo-026","category":"Geografie & Länder","title":"Amazonas führt am meisten Wasser","text":"Der Amazonas transportiert mehr Wasser als jeder andere Fluss der Erde.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Amazonas führt am meisten Wasser"],"topicKey":"geo-amazonas-fuhrt-am-meisten-wasser"},{"id":"geo-027","category":"Geografie & Länder","title":"Kongo ist extrem tief","text":"Der Kongo gehört zu den tiefsten bekannten Flüssen der Erde und führt gewaltige Wassermengen.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Kongo ist extrem tief"],"topicKey":"geo-kongo-ist-extrem-tief"},{"id":"geo-028","category":"Geografie & Länder","title":"Gambia folgt einem Fluss","text":"Der Staat Gambia ist ungewöhnlich lang und schmal und folgt weitgehend dem Lauf des Gambia-Flusses.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Gambia folgt einem Fluss"],"topicKey":"geo-gambia-folgt-einem-fluss"},{"id":"geo-029","category":"Geografie & Länder","title":"Chile ist extrem lang","text":"Chile zieht sich über mehrere Tausend Kilometer entlang der Pazifikküste Südamerikas, ist dabei aber vergleichsweise schmal.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Chile ist extrem lang"],"topicKey":"geo-chile-ist-extrem-lang"},{"id":"geo-030","category":"Geografie & Länder","title":"Nepal hat enorme Höhenunterschiede","text":"Nepal reicht von Tiefland nahe Meereshöhe bis zu den höchsten Gipfeln der Erde.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Nepal hat enorme Höhenunterschiede"],"topicKey":"geo-nepal-hat-enorme-hohenunterschiede"},{"id":"geo-031","category":"Geografie & Länder","title":"Bangladesch ist Delta-Land","text":"Große Teile Bangladeschs liegen im riesigen Delta von Ganges, Brahmaputra und Meghna.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Bangladesch ist Delta-Land"],"topicKey":"geo-bangladesch-ist-delta-land"},{"id":"geo-032","category":"Geografie & Länder","title":"Niederlande unter Meeresspiegel","text":"Teile der Niederlande liegen unter dem Meeresspiegel und werden durch Deiche, Dünen und Pumpwerke geschützt.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Niederlande unter Meeresspiegel"],"topicKey":"geo-niederlande-unter-meeresspiegel"},{"id":"geo-033","category":"Geografie & Länder","title":"Venedig auf Inseln","text":"Venedig entstand auf zahlreichen kleinen Inseln in einer Lagune, verbunden durch Kanäle und Brücken.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Venedig auf Inseln"],"topicKey":"geo-venedig-auf-inseln"},{"id":"geo-034","category":"Geografie & Länder","title":"Finnland ist Land der vielen Seen","text":"Finnland besitzt Zehntausende Seen und eine stark von Eiszeiten geprägte Landschaft.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Finnland ist Land der vielen Seen"],"topicKey":"geo-finnland-ist-land-der-vielen-seen"},{"id":"geo-035","category":"Geografie & Länder","title":"Kanada hat extrem lange Küste","text":"Kanada besitzt wegen seiner riesigen Fläche und zahllosen Inseln eine der längsten Küstenlinien der Welt.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Kanada hat extrem lange Küste"],"topicKey":"geo-kanada-hat-extrem-lange-kuste"},{"id":"geo-036","category":"Geografie & Länder","title":"Indonesien ist ein Inselstaat","text":"Indonesien besteht aus Tausenden Inseln und erstreckt sich über einen enormen Teil des Äquators.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Indonesien ist ein Inselstaat"],"topicKey":"geo-indonesien-ist-ein-inselstaat"},{"id":"geo-037","category":"Geografie & Länder","title":"Philippinen sind Archipel","text":"Die Philippinen bestehen aus Tausenden Inseln, von denen nur ein Teil dauerhaft bewohnt ist.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Philippinen sind Archipel"],"topicKey":"geo-philippinen-sind-archipel"},{"id":"geo-038","category":"Geografie & Länder","title":"Papua-Neuguinea ist sprachlich extrem vielfältig","text":"In Papua-Neuguinea werden mehrere Hundert unterschiedliche Sprachen gesprochen – mehr als in fast jedem anderen Land.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Papua-Neuguinea ist sprachlich extrem vielfältig"],"topicKey":"geo-papua-neuguinea-ist-sprachlich-extrem-vielfaltig"},{"id":"geo-039","category":"Geografie & Länder","title":"Russland überspannt viele Zeitzonen","text":"Russland erstreckt sich über elf Zeitzonen.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Russland überspannt viele Zeitzonen"],"topicKey":"geo-russland-uberspannt-viele-zeitzonen"},{"id":"geo-040","category":"Geografie & Länder","title":"Frankreich hat Gebiete auf mehreren Kontinenten","text":"Durch Überseegebiete liegt französisches Staatsgebiet in Europa, Amerika, Ozeanien und anderen Weltregionen.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Frankreich hat Gebiete auf mehreren Kontinenten"],"topicKey":"geo-frankreich-hat-gebiete-auf-mehreren-kontinenten"},{"id":"geo-041","category":"Geografie & Länder","title":"Spanien liegt auch in Afrika","text":"Zu Spanien gehören unter anderem Ceuta und Melilla an der nordafrikanischen Küste.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Spanien liegt auch in Afrika"],"topicKey":"geo-spanien-liegt-auch-in-afrika"},{"id":"geo-042","category":"Geografie & Länder","title":"Türkei liegt auf zwei Kontinenten","text":"Die Türkei erstreckt sich über Europa und Asien; der Bosporus trennt beide Landesteile.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Türkei liegt auf zwei Kontinenten"],"topicKey":"geo-turkei-liegt-auf-zwei-kontinenten"},{"id":"geo-043","category":"Geografie & Länder","title":"Ägypten liegt auf zwei Kontinenten","text":"Der größte Teil Ägyptens liegt in Afrika, die Sinai-Halbinsel geografisch in Asien.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Ägypten liegt auf zwei Kontinenten"],"topicKey":"geo-agypten-liegt-auf-zwei-kontinenten"},{"id":"geo-044","category":"Geografie & Länder","title":"Panama verbindet Kontinente","text":"Die Landenge von Panama verbindet Nord- und Südamerika und trennt zugleich Atlantik und Pazifik.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Panama verbindet Kontinente"],"topicKey":"geo-panama-verbindet-kontinente"},{"id":"geo-045","category":"Geografie & Länder","title":"Suez trennt Afrika und Asien","text":"Der Suezkanal durchschneidet die Landbrücke zwischen Afrika und Asien und verbindet Mittelmeer und Rotes Meer.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Suez trennt Afrika und Asien"],"topicKey":"geo-suez-trennt-afrika-und-asien"},{"id":"geo-046","category":"Geografie & Länder","title":"Beringstraße trennt nur wenige Dutzend Kilometer","text":"Zwischen Russland und Alaska liegen an der engsten Stelle der Beringstraße nur rund 80 Kilometer.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Beringstraße trennt nur wenige Dutzend Kilometer"],"topicKey":"geo-beringstra-e-trennt-nur-wenige-dutzend-kilometer"},{"id":"geo-047","category":"Geografie & Länder","title":"Diomede-Inseln","text":"Zwischen den Diomede-Inseln verläuft die internationale Datumsgrenze. Obwohl sie nur wenige Kilometer auseinanderliegen, unterscheiden sich ihre Kalenderdaten.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Diomede-Inseln"],"topicKey":"geo-diomede-inseln"},{"id":"geo-048","category":"Geografie & Länder","title":"Samoa sprang einen Tag","text":"Samoa übersprang 2011 den 30. Dezember, um wirtschaftlich auf die andere Seite der internationalen Datumsgrenze zu wechseln.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Samoa sprang einen Tag"],"topicKey":"geo-samoa-sprang-einen-tag"},{"id":"geo-049","category":"Geografie & Länder","title":"Kiribati über mehrere Zeitzonen","text":"Kiribati erstreckt sich so weit über den Pazifik, dass das Land mehrere Zeitzonen umfasst und die Datumsgrenze angepasst wurde.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Kiribati über mehrere Zeitzonen"],"topicKey":"geo-kiribati-uber-mehrere-zeitzonen"},{"id":"geo-050","category":"Geografie & Länder","title":"Nullmeridian ist Konvention","text":"Der Nullmeridian durch Greenwich ist keine natürliche Linie. Er wurde international als Referenz festgelegt.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Nullmeridian ist Konvention"],"topicKey":"geo-nullmeridian-ist-konvention"},{"id":"geo-051","category":"Geografie & Länder","title":"Äquator ist länger als Polarumfang","text":"Weil die Erde am Äquator etwas ausgebeult ist, ist ihr Umfang dort größer als über die Pole.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Äquator ist länger als Polarumfang"],"topicKey":"geo-aquator-ist-langer-als-polarumfang"},{"id":"geo-053","category":"Geografie & Länder","title":"Hawaii bewegt sich","text":"Die Pazifische Platte bewegt sich über einen relativ stationären Hotspot. Deshalb bilden die Hawaii-Inseln eine Alterskette.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Hawaii bewegt sich"],"topicKey":"geo-hawaii-bewegt-sich"},{"id":"geo-054","category":"Geografie & Länder","title":"Yellowstone ist kein einzelner Vulkanberg","text":"Yellowstone liegt über einem großen vulkanischen System mit Caldera, Geysiren und heißen Quellen statt einem klassischen Kegelvulkan.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Yellowstone ist kein einzelner Vulkanberg"],"topicKey":"geo-yellowstone-ist-kein-einzelner-vulkanberg"},{"id":"geo-055","category":"Geografie & Länder","title":"Grand Canyon ist geologisch jung und alt zugleich","text":"Das Gestein am Grand Canyon ist teilweise extrem alt, während der Canyon selbst geologisch viel jünger eingeschnitten wurde.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Grand Canyon ist geologisch jung und alt zugleich"],"topicKey":"geo-grand-canyon-ist-geologisch-jung-und-alt-zugleich"},{"id":"geo-056","category":"Geografie & Länder","title":"Sahara war zeitweise grün","text":"In feuchteren Klimaphasen gab es in der heutigen Sahara Seen, Grasland und deutlich mehr Vegetation.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Sahara war zeitweise grün"],"topicKey":"geo-sahara-war-zeitweise-grun"},{"id":"geo-057","category":"Geografie & Länder","title":"Arabische Halbinsel hat alte Flusstäler","text":"Trockene Wadis zeigen, dass heute aride Regionen in früheren Klimaphasen wesentlich feuchter sein konnten.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Arabische Halbinsel hat alte Flusstäler"],"topicKey":"geo-arabische-halbinsel-hat-alte-flusstaler"},{"id":"geo-058","category":"Geografie & Länder","title":"Australien hat sehr alte Landschaften","text":"Australien besitzt große geologisch stabile Gebiete, deren Oberflächenformen über extrem lange Zeiträume entwickelt wurden.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Australien hat sehr alte Landschaften"],"topicKey":"geo-australien-hat-sehr-alte-landschaften"},{"id":"geo-059","category":"Geografie & Länder","title":"Madagaskar trennte sich früh","text":"Madagaskar war lange isoliert. Dadurch konnten sich viele Tier- und Pflanzenarten entwickeln, die sonst nirgends vorkommen.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Madagaskar trennte sich früh"],"topicKey":"geo-madagaskar-trennte-sich-fruh"},{"id":"geo-060","category":"Geografie & Länder","title":"Neuseeland ist Teil von Zealandia","text":"Neuseeland ist der sichtbare Teil eines größtenteils unter Wasser liegenden Kontinentalfragments namens Zealandia.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Neuseeland ist Teil von Zealandia"],"topicKey":"geo-neuseeland-ist-teil-von-zealandia"},{"id":"geo-061","category":"Geografie & Länder","title":"Japan ist stark gebirgig","text":"Ein großer Teil Japans besteht aus Bergen. Deshalb konzentrieren sich Bevölkerung und Landwirtschaft stark auf geeignete Ebenen und Küstenräume.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Japan ist stark gebirgig"],"topicKey":"geo-japan-ist-stark-gebirgig"},{"id":"geo-062","category":"Geografie & Länder","title":"Norwegen hat Fjorde durch Eis","text":"Viele norwegische Fjorde sind tiefe Täler, die von Gletschern ausgeschürft und später vom Meer geflutet wurden.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Norwegen hat Fjorde durch Eis"],"topicKey":"geo-norwegen-hat-fjorde-durch-eis"},{"id":"geo-063","category":"Geografie & Länder","title":"Schottlands Lochs sind Gletschererbe","text":"Viele schottische Seen und Täler wurden stark durch eiszeitliche Gletscher geformt.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Schottlands Lochs sind Gletschererbe"],"topicKey":"geo-schottlands-lochs-sind-gletschererbe"},{"id":"geo-064","category":"Geografie & Länder","title":"Great Lakes sind Süßwasser-Riesen","text":"Die nordamerikanischen Großen Seen gehören zusammen zu den größten Süßwassersystemen der Erde.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Great Lakes sind Süßwasser-Riesen"],"topicKey":"geo-great-lakes-sind-su-wasser-riesen"},{"id":"geo-065","category":"Geografie & Länder","title":"Donau durchquert viele Staaten","text":"Die Donau verbindet besonders viele Länder Europas und mündet über ein großes Delta ins Schwarze Meer.","source":"CIA World Factbook / USGS / NOAA","sourceUrl":"https://www.cia.gov/the-world-factbook/","verified":true,"tone":"curious","sensitive":false,"tags":["Geografie","Donau durchquert viele Staaten"],"topicKey":"geo-donau-durchquert-viele-staaten"},{"id":"sync-001","category":"Stimmen & Synchron","title":"Thomas Danneberg","text":"Thomas Danneberg prägte im Deutschen unter anderem Sylvester Stallone und Arnold Schwarzenegger. In 'The Expendables 2' sprach er tatsächlich beide Schauspieler im selben Film.","source":"Deutsche Synchronkartei","sourceUrl":"https://www.synchronkartei.de/","verified":true,"tone":"curious","sensitive":false,"tags":["Synchronsprecher","Thomas Danneberg"],"topicKey":"sync-thomas-danneberg"},{"id":"sync-002","category":"Stimmen & Synchron","title":"Wolfgang Pampel","text":"Wolfgang Pampel ist über Jahrzehnte eng mit Harrison Ford verbunden – von Han Solo über Indiana Jones bis zu späteren Rollen.","source":"Deutsche Synchronkartei","sourceUrl":"https://www.synchronkartei.de/","verified":true,"tone":"curious","sensitive":false,"tags":["Synchronsprecher","Wolfgang Pampel"],"topicKey":"sync-wolfgang-pampel"},{"id":"sync-003","category":"Stimmen & Synchron","title":"Christian Brückner","text":"Christian Brückner ist besonders als deutsche Stimme von Robert De Niro bekannt und sprach ihn über Jahrzehnte in zahlreichen Filmen.","source":"Deutsche Synchronkartei","sourceUrl":"https://www.synchronkartei.de/","verified":true,"tone":"curious","sensitive":false,"tags":["Synchronsprecher","Christian Brückner"],"topicKey":"sync-christian-bruckner"},{"id":"sync-004","category":"Stimmen & Synchron","title":"David Nathan","text":"David Nathan gehört zu den bekanntesten deutschen Synchronstimmen von Johnny Depp und Christian Bale.","source":"Deutsche Synchronkartei","sourceUrl":"https://www.synchronkartei.de/","verified":true,"tone":"curious","sensitive":false,"tags":["Synchronsprecher","David Nathan"],"topicKey":"sync-david-nathan"},{"id":"sync-005","category":"Stimmen & Synchron","title":"Tobias Meister","text":"Tobias Meister ist seit vielen Jahren eng mit Brad Pitt verbunden und spricht außerdem häufig Kiefer Sutherland.","source":"Deutsche Synchronkartei","sourceUrl":"https://www.synchronkartei.de/","verified":true,"tone":"curious","sensitive":false,"tags":["Synchronsprecher","Tobias Meister"],"topicKey":"sync-tobias-meister"},{"id":"sync-006","category":"Stimmen & Synchron","title":"Joachim Kerzel","text":"Joachim Kerzel sprach sowohl Jack Nicholson als auch Dustin Hoffman in vielen Produktionen und war außerdem eine äußerst bekannte Trailerstimme.","source":"Deutsche Synchronkartei","sourceUrl":"https://www.synchronkartei.de/","verified":true,"tone":"curious","sensitive":false,"tags":["Synchronsprecher","Joachim Kerzel"],"topicKey":"sync-joachim-kerzel"},{"id":"sync-007","category":"Stimmen & Synchron","title":"Detlef Bierstedt","text":"Detlef Bierstedt ist über viele Jahre besonders mit George Clooney verbunden und sprach ihn in zahlreichen Kino- und Fernsehproduktionen.","source":"Deutsche Synchronkartei","sourceUrl":"https://www.synchronkartei.de/","verified":true,"tone":"curious","sensitive":false,"tags":["Synchronsprecher","Detlef Bierstedt"],"topicKey":"sync-detlef-bierstedt"},{"id":"sync-008","category":"Stimmen & Synchron","title":"Udo Schenk","text":"Udo Schenk ist unter anderem regelmäßig als deutsche Stimme von Gary Oldman und Ralph Fiennes zu hören.","source":"Deutsche Synchronkartei","sourceUrl":"https://www.synchronkartei.de/","verified":true,"tone":"curious","sensitive":false,"tags":["Synchronsprecher","Udo Schenk"],"topicKey":"sync-udo-schenk"},{"id":"sync-009","category":"Stimmen & Synchron","title":"Frank Glaubrecht","text":"Frank Glaubrecht sprach über viele Jahre unter anderem Pierce Brosnan und Kevin Costner in zahlreichen deutschen Fassungen.","source":"Deutsche Synchronkartei","sourceUrl":"https://www.synchronkartei.de/","verified":true,"tone":"curious","sensitive":false,"tags":["Synchronsprecher","Frank Glaubrecht"],"topicKey":"sync-frank-glaubrecht"},{"id":"sync-010","category":"Stimmen & Synchron","title":"Manfred Lehmann","text":"Manfred Lehmann ist besonders als langjährige deutsche Stimme von Bruce Willis bekannt; auch in den 'Expendables'-Filmen hört man diese Zuordnung.","source":"Deutsche Synchronkartei","sourceUrl":"https://www.synchronkartei.de/","verified":true,"tone":"curious","sensitive":false,"tags":["Synchronsprecher","Manfred Lehmann"],"topicKey":"sync-manfred-lehmann"},{"id":"person-extra-001","category":"Wer ist eigentlich …?","title":"Emmy Noether","text":"Deutsche Mathematikerin, deren Arbeiten zur abstrakten Algebra und theoretischen Physik enormen Einfluss hatten. Das Noether-Theorem verbindet Symmetrien mit Erhaltungsgrößen.","source":"Encyclopaedia Britannica","sourceUrl":"https://www.britannica.com/biography/Emmy-Noether","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Emmy Noether"],"topicKey":"person-emmy-noether"},{"id":"person-extra-002","category":"Wer ist eigentlich …?","title":"Lise Meitner","text":"Österreichisch-schwedische Physikerin, die entscheidend zum Verständnis der Kernspaltung beitrug. Trotz ihrer zentralen Rolle erhielt nur Otto Hahn den Chemie-Nobelpreis 1944.","source":"Nobel Prize / Wissenschaftsgeschichte","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Lise Meitner"],"topicKey":"person-lise-meitner"},{"id":"person-extra-003","category":"Wer ist eigentlich …?","title":"Henrietta Swan Leavitt","text":"US-Astronomin, die einen Zusammenhang zwischen Helligkeit und Pulsationsdauer bestimmter veränderlicher Sterne entdeckte. Damit entstand ein wichtiges Werkzeug zur Entfernungsbestimmung im All.","source":"NASA","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Henrietta Swan Leavitt"],"topicKey":"person-henrietta-swan-leavitt"},{"id":"person-extra-004","category":"Wer ist eigentlich …?","title":"Cecilia Payne-Gaposchkin","text":"Astronomin, die zeigte, dass Sterne hauptsächlich aus Wasserstoff und Helium bestehen – eine damals überraschende Erkenntnis.","source":"NASA","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Cecilia Payne-Gaposchkin"],"topicKey":"person-cecilia-payne-gaposchkin"},{"id":"person-extra-005","category":"Wer ist eigentlich …?","title":"Vera Rubin","text":"US-Astronomin, deren Messungen von Galaxienrotationen starke Hinweise auf Dunkle Materie lieferten.","source":"NASA","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Vera Rubin"],"topicKey":"person-vera-rubin"},{"id":"person-extra-006","category":"Wer ist eigentlich …?","title":"Annie Jump Cannon","text":"Astronomin, die Hunderttausende Sterne klassifizierte und ein System prägte, das bis heute Grundlage der Spektralklassen ist.","source":"NASA","sourceUrl":"https://science.nasa.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Annie Jump Cannon"],"topicKey":"person-annie-jump-cannon"},{"id":"person-extra-007","category":"Wer ist eigentlich …?","title":"Subrahmanyan Chandrasekhar","text":"Astrophysiker, der die maximale Masse eines stabilen Weißen Zwergs berechnete. Der sogenannte Chandrasekhar-Grenzwert ist zentral für das Verständnis von Sternentwicklung.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Subrahmanyan Chandrasekhar"],"topicKey":"person-subrahmanyan-chandrasekhar"},{"id":"person-extra-008","category":"Wer ist eigentlich …?","title":"Abdus Salam","text":"Pakistanischer Physiker und Mitbegründer der elektroschwachen Theorie. 1979 erhielt er gemeinsam mit Sheldon Glashow und Steven Weinberg den Physik-Nobelpreis.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Abdus Salam"],"topicKey":"person-abdus-salam"},{"id":"person-extra-009","category":"Wer ist eigentlich …?","title":"Norman Borlaug","text":"US-Agrarwissenschaftler, dessen Arbeiten an ertragreichen Getreidesorten zur sogenannten Grünen Revolution beitrugen. 1970 erhielt er den Friedensnobelpreis.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Norman Borlaug"],"topicKey":"person-norman-borlaug"},{"id":"person-extra-010","category":"Wer ist eigentlich …?","title":"Jonas Salk","text":"US-Mediziner, der einen der ersten wirksamen Impfstoffe gegen Polio entwickelte und bewusst auf ein Patent auf den Impfstoff verzichtete.","source":"Smithsonian / Medizingeschichte","sourceUrl":"https://www.si.edu/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Jonas Salk"],"topicKey":"person-jonas-salk"},{"id":"person-extra-012","category":"Wer ist eigentlich …?","title":"Gregor Mendel","text":"Augustinermönch und Naturforscher, dessen Kreuzungsversuche mit Erbsen grundlegende Regeln der Vererbung sichtbar machten.","source":"Encyclopaedia Britannica","sourceUrl":"https://www.britannica.com/biography/Gregor-Mendel","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Gregor Mendel"],"topicKey":"person-gregor-mendel"},{"id":"person-extra-013","category":"Wer ist eigentlich …?","title":"Antonie van Leeuwenhoek","text":"Niederländischer Tuchhändler und Mikroskopbauer. Mit seinen starken Einlinsenmikroskopen beobachtete er als einer der Ersten Mikroorganismen.","source":"Royal Society","sourceUrl":"https://royalsociety.org/people/antonie-van-leeuwenhoek-12241/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Antonie van Leeuwenhoek"],"topicKey":"person-antonie-van-leeuwenhoek"},{"id":"person-extra-014","category":"Wer ist eigentlich …?","title":"Robert Hooke","text":"Englischer Naturforscher. In 'Micrographia' veröffentlichte er detaillierte Mikroskopzeichnungen und prägte beim Blick auf Kork den Begriff 'Zelle'.","source":"Royal Society","sourceUrl":"https://royalsociety.org/people/robert-hooke-11664/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Robert Hooke"],"topicKey":"person-robert-hooke"},{"id":"person-extra-015","category":"Wer ist eigentlich …?","title":"James Clerk Maxwell","text":"Schottischer Physiker, dessen Gleichungen Elektrizität, Magnetismus und Licht in einer gemeinsamen Theorie verbanden.","source":"Encyclopaedia Britannica","sourceUrl":"https://www.britannica.com/biography/James-Clerk-Maxwell","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","James Clerk Maxwell"],"topicKey":"person-james-clerk-maxwell"},{"id":"person-extra-016","category":"Wer ist eigentlich …?","title":"Michael Faraday","text":"Britischer Experimentalphysiker, der grundlegende Entdeckungen zu elektromagnetischer Induktion machte und damit Generatoren und Elektromotoren theoretisch wie praktisch vorbereitete.","source":"Royal Institution","sourceUrl":"https://www.rigb.org/explore-science/explore/person/michael-faraday","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Michael Faraday"],"topicKey":"person-michael-faraday"},{"id":"person-extra-017","category":"Wer ist eigentlich …?","title":"Srinivasa Ramanujan","text":"Indischer Mathematiker, der weitgehend autodidaktisch außergewöhnliche Formeln und Einsichten in Zahlentheorie und Analysis entwickelte.","source":"Royal Society","sourceUrl":"https://royalsociety.org/people/srinivasa-ramanujan-12133/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Srinivasa Ramanujan"],"topicKey":"person-srinivasa-ramanujan"},{"id":"person-extra-018","category":"Wer ist eigentlich …?","title":"Hypatia","text":"Mathematikerin, Astronomin und Philosophin im spätantiken Alexandria. Sie lehrte öffentlich und wurde zu einer der bekanntesten Gelehrten ihrer Epoche.","source":"Encyclopaedia Britannica","sourceUrl":"https://www.britannica.com/biography/Hypatia","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Hypatia"],"topicKey":"person-hypatia"},{"id":"person-extra-019","category":"Wer ist eigentlich …?","title":"Ibn al-Haytham","text":"Gelehrter des 10./11. Jahrhunderts, der Optik experimentell untersuchte und entscheidend zum Verständnis von Licht und Sehen beitrug.","source":"UNESCO","sourceUrl":"https://en.unesco.org/courier/2015-2/ibn-al-haytham-pioneer-modern-optics","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Ibn al-Haytham"],"topicKey":"person-ibn-al-haytham"},{"id":"person-extra-020","category":"Wer ist eigentlich …?","title":"Al-Chwarizmi","text":"Mathematiker des 9. Jahrhunderts. Sein Name steckt im Wort 'Algorithmus', und seine Arbeiten zur Algebra beeinflussten Mathematik über Jahrhunderte.","source":"Encyclopaedia Britannica","sourceUrl":"https://www.britannica.com/biography/al-Khwarizmi","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Al-Chwarizmi"],"topicKey":"person-al-chwarizmi"},{"id":"tier-extra-001","category":"Tier im Fokus","title":"Großer Ameisenbär","text":"Große Ameisenbären können etwa 1,8 bis 2,4 Meter lang werden und 27 bis 45 Kilogramm wiegen. Zähne haben sie keine. Dafür kann ihre ungefähr 60 Zentimeter lange, klebrige Zunge bis zu 150-mal pro Minute vorschnellen, um Ameisen und Termiten einzusammeln.","source":"Smithsonian's National Zoo","sourceUrl":"https://nationalzoo.si.edu/animals/giant-anteater","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Ameisenbär"],"topicKey":"animal-giant-anteater"},{"id":"tier-extra-002","category":"Tier im Fokus","title":"Fischkatze","text":"Fischkatzen gehören zu den wenigen Katzen, die regelrecht ans Wasser angepasst sind. Sie schwimmen freiwillig, besitzen teilweise Schwimmhäute zwischen den Zehen und jagen Fische, indem sie am Ufer lauern oder direkt ins Wasser gehen. Erwachsene Männchen wiegen etwa 8 bis 14 Kilogramm.","source":"Smithsonian's National Zoo","sourceUrl":"https://nationalzoo.si.edu/animals/fishing-cat","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Katzen"],"topicKey":"animal-fishing-cat"},{"id":"tier-extra-003","category":"Tier im Fokus","title":"Lippenbär","text":"Lippenbären aus Südasien sind auf Ameisen und Termiten spezialisiert. Ihre Nasenlöcher können sich schließen, zwei obere Schneidezähne fehlen, und mit beweglichen Lippen saugen sie Insekten regelrecht aus ihren Nestern. In insektenreichen Zeiten kann ein enormer Teil ihrer Nahrung aus Termiten bestehen.","source":"Smithsonian's National Zoo","sourceUrl":"https://nationalzoo.si.edu/animals/sloth-bear","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Bären"],"topicKey":"animal-sloth-bear"},{"id":"tier-extra-004","category":"Tier im Fokus","title":"Schwarzschwanz-Präriehund","text":"Präriehunde sind keine Hunde, sondern Erdhörnchen. Sie bauen unterirdische Kolonien, sogenannte 'Towns'. Die größte historisch dokumentierte Kolonie soll sich über rund 65.000 Quadratkilometer erstreckt und schätzungsweise Hunderte Millionen Tiere beherbergt haben.","source":"Smithsonian's National Zoo","sourceUrl":"https://nationalzoo.si.edu/animals/black-tailed-prairie-dog","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Nagetiere"],"topicKey":"animal-black-tailed-prairie-dog"},{"id":"tier-extra-005","category":"Tier im Fokus","title":"Mähnenwolf","text":"Der Mähnenwolf sieht wie ein langbeiniger Fuchs aus und heißt Wolf, ist aber weder echter Wolf noch Fuchs. Er ist der größte Hundeartige Südamerikas und frisst überraschend viel pflanzliche Nahrung; Früchte und Gemüse können etwa die Hälfte seines Speiseplans ausmachen.","source":"Smithsonian's National Zoo","sourceUrl":"https://nationalzoo.si.edu/animals/maned-wolf","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Hundeartige"],"topicKey":"animal-maned-wolf"},{"id":"tier-extra-006","category":"Tier im Fokus","title":"Binturong","text":"Binturongs werden auch 'Bärenkatzen' genannt, sind aber weder Bären noch Katzen. Sie leben in Bäumen Süd- und Südostasiens, besitzen einen Greifschwanz und sind berühmt für einen bizarren Nebeneffekt ihrer Körperchemie: Ihr Geruch erinnert viele Menschen an gebuttertes Popcorn.","source":"Smithsonian's National Zoo","sourceUrl":"https://nationalzoo.si.edu/animals/binturong","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Kurios"],"topicKey":"animal-binturong"},{"id":"tier-extra-007","category":"Tier im Fokus","title":"Säbelantilope","text":"Säbelantilopen sind Wüstenspezialisten. Sie können ihre Körpertemperatur stark ansteigen lassen und müssen dadurch weniger schwitzen, was Wasser spart. Nachdem die Art in freier Wildbahn verschwunden war, gelang durch Zucht- und Auswilderungsprogramme eine Rückkehr; seit 2023 gilt sie wieder als 'Endangered' statt 'Extinct in the Wild'.","source":"Smithsonian's National Zoo","sourceUrl":"https://nationalzoo.si.edu/conservation/news/once-extinct-wild-scimitar-horned-oryx-are-back-brink","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Artenschutz"],"topicKey":"animal-scimitar-horned-oryx"},{"id":"tier-extra-008","category":"Tier im Fokus","title":"Nebelparder","text":"Nebelparder sind keine kleinen Leoparden. Ihre Eckzähne sind im Verhältnis zum Schädel außergewöhnlich lang, sie können ihr Maul ungefähr 100 Grad weit öffnen und gehören zu den wenigen Katzen, die kopfüber einen Baum hinunterklettern können.","source":"Smithsonian's National Zoo","sourceUrl":"https://www.nationalzoo.si.edu/animals/clouded-leopard","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Katzen"],"topicKey":"animal-clouded-leopard"},{"id":"tier-extra-009","category":"Tier im Fokus","title":"Goldenes Löwenäffchen","text":"Goldene Löwenäffchen wiegen nur ungefähr ein halbes Kilogramm und leben in Familiengruppen im brasilianischen Atlantikwald. In den frühen 1970er-Jahren waren in freier Wildbahn nur noch etwa 200 Tiere übrig; intensive Schutz- und Auswilderungsprogramme halfen der Population, sich deutlich zu erholen.","source":"Smithsonian's National Zoo","sourceUrl":"https://nationalzoo.si.edu/animals/golden-lion-tamarin","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Primaten","Artenschutz"],"topicKey":"animal-golden-lion-tamarin"},{"id":"person-extra-clean-001","category":"Wer ist eigentlich …?","title":"Kate Walker","text":"Kate Walker betreute Ende des 19. und Anfang des 20. Jahrhunderts den Leuchtturm Robbins Reef im New Yorker Hafen. Nach dem Tod ihres Mannes erledigte sie die Arbeit jahrelang praktisch allein, obwohl die Behörden Frauen zunächst nicht als verantwortliche Leuchtturmwärterinnen akzeptieren wollten. 1895 wurde sie schließlich offiziell ernannt.","source":"U.S. National Park Service","sourceUrl":"https://www.nps.gov/articles/000/-h-our-history-lesson-kate-walker-lighthouse-keeper-and-hero-of-new-york-harbor.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Leuchtturm","Geschichte"],"topicKey":"person-kate-walker"},{"id":"person-extra-clean-002","category":"Wer ist eigentlich …?","title":"Mary Fields","text":"Mary Fields wurde versklavt geboren und begann später im Westen der USA ein völlig anderes Leben. Mit über 60 Jahren transportierte sie als Star-Route-Carrier Post durch Montana. Bei tiefem Schnee legte sie Teile der Strecke sogar auf Schneeschuhen zurück. Sie war die erste afroamerikanische Frau mit einem solchen Postvertrag.","source":"U.S. National Park Service","sourceUrl":"https://www.nps.gov/people/mary-fields.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Post","Geschichte"],"topicKey":"person-mary-fields"},{"id":"person-extra-clean-003","category":"Wer ist eigentlich …?","title":"Bass Reeves","text":"Bass Reeves wurde versklavt geboren und arbeitete nach dem Bürgerkrieg mehr als drei Jahrzehnte als Deputy U.S. Marshal im damaligen Indian Territory. Um seine Karriere ranken sich viele Legenden; der National Park Service weist ausdrücklich darauf hin, dass spektakuläre Zahlen zu Festnahmen und Schießereien historisch mit Vorsicht behandelt werden müssen.","source":"U.S. National Park Service","sourceUrl":"https://www.nps.gov/articles/000/bass-reeves-site-bulletin.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Geschichte","Lawman"],"topicKey":"person-bass-reeves"},{"id":"person-extra-clean-004","category":"Wer ist eigentlich …?","title":"Bessie Coleman","text":"Bessie Coleman wollte fliegen, fand als schwarze Frau in den USA aber keine Flugschule, die sie ausbildete. Sie lernte deshalb in Frankreich und erhielt 1921 eine internationale Pilotenlizenz. Danach wurde sie mit spektakulären Flugshows bekannt und setzte sich dafür ein, anderen Schwarzen Amerikanern den Weg in die Luftfahrt zu öffnen.","source":"U.S. National Park Service","sourceUrl":"https://www.nps.gov/tuai/and-there-were-women.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Luftfahrt","Geschichte"],"topicKey":"person-bessie-coleman"},{"id":"person-extra-clean-005","category":"Wer ist eigentlich …?","title":"Nellie Bly","text":"Nellie Bly war eine Pionierin des investigativen Journalismus. Für eine Recherche ließ sie sich 1887 unter falscher Identität in eine psychiatrische Einrichtung auf Blackwell's Island einweisen und berichtete anschließend über Missstände dort. Später reiste sie, inspiriert von Jules Verne, in rund 72 Tagen um die Welt.","source":"U.S. National Park Service","sourceUrl":"https://home.nps.gov/people/nellie-bly.htm","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Journalismus","Geschichte"],"topicKey":"person-nellie-bly"},{"id":"joke-001","category":"Witz","title":"Britisch trocken","text":"Mein Chef sagte, ich solle mehr Eigeninitiative zeigen. Ich bin früher gegangen, bevor er mich darum bitten konnte.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-003","category":"Witz","title":"Britisch trocken","text":"Mein Chef fragte nach meiner langfristigen Perspektive. Ich sagte: Feierabend. Er meinte offenbar etwas anderes.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-005","category":"Witz","title":"Britisch trocken","text":"Wir haben jetzt ein Effizienzprogramm. Die Einführung dazu dauert nur sechs Meetings.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-006","category":"Witz","title":"Britisch trocken","text":"Der Drucker meldet Papierstau. Ich respektiere, dass wenigstens einer offen zugibt, heute nicht arbeiten zu wollen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-007","category":"Witz","title":"Britisch trocken","text":"Ich liebe klare Arbeitsanweisungen. Besonders die Sorte, die später mit „So war das nicht gemeint“ endet.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-008","category":"Witz","title":"Britisch trocken","text":"Mein Kollege arbeitet angeblich am besten unter Druck. Deshalb beginnen wir grundsätzlich fünf Minuten vor Feierabend.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-010","category":"Witz","title":"Norddeutsch","text":"„Und, wie läuft's?“ – „Vorwärts wär übertrieben, aber rückwärts ist es auch noch nicht.“","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"],"jokeQuality":"editorial_checked"},{"id":"joke-011","category":"Witz","title":"Norddeutsch","text":"Chef: „Kannst du heute länger?“ – „Können schon. Wollen ist organisatorisch schwieriger.“","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"],"jokeQuality":"editorial_checked"},{"id":"joke-015","category":"Witz","title":"Norddeutsch","text":"Wenn der Chef sagt „nur ganz kurz“, weiß man: Jacke wieder aus.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"],"jokeQuality":"editorial_checked"},{"id":"joke-017","category":"Witz","title":"Arbeit","text":"Meine To-do-Liste und ich führen eine Fernbeziehung. Wir wissen voneinander, sehen uns aber selten.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"],"jokeQuality":"editorial_checked"},{"id":"joke-024","category":"Witz","title":"Arbeit","text":"Der Computer fragt, ob ich wirklich herunterfahren möchte. Endlich interessiert sich jemand für meine Gefühle.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"],"jokeQuality":"editorial_checked"},{"id":"joke-025","category":"Witz","title":"Arbeit","text":"Montag ist wie ein Softwareupdate: Keiner hat darum gebeten, trotzdem startet es automatisch.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"],"jokeQuality":"editorial_checked"},{"id":"joke-027","category":"Witz","title":"Arbeit","text":"Der Chef wollte eine kreative Lösung. Ich habe Urlaub vorgeschlagen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"],"jokeQuality":"editorial_checked"},{"id":"joke-031","category":"Witz","title":"Absurd","text":"Ein Mann geht zum Wahrsager. Der sagt: „Ich sehe, Sie verschwenden gerade Geld.“ Endlich ein Treffer.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"],"jokeQuality":"editorial_checked"},{"id":"joke-038","category":"Witz","title":"Beziehung","text":"Meine Partnerin sagte: „Du hörst mir nie zu.“ Seltsamer Einstieg in ein Gespräch.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"],"jokeQuality":"editorial_checked"},{"id":"joke-039","category":"Witz","title":"Beziehung","text":"Wir teilen alles in der Beziehung. Sie die Meinung, ich die Schuld.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"],"jokeQuality":"editorial_checked"},{"id":"joke-040","category":"Witz","title":"Beziehung","text":"„Was denkst du gerade?“ ist keine Frage. Es ist ein Überraschungstest ohne Lernmaterial.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"],"jokeQuality":"editorial_checked"},{"id":"joke-043","category":"Witz","title":"Beziehung","text":"Sie sagte, ich solle spontaner sein. Ich habe einen Termin dafür eingetragen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"],"jokeQuality":"editorial_checked"},{"id":"joke-044","category":"Witz","title":"Beziehung","text":"„Mach, was du willst“ ist sprachlich ein Satz und praktisch eine Minenkarte.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"],"jokeQuality":"editorial_checked"},{"id":"joke-045","category":"Witz","title":"Arzt","text":"Der Arzt fragte, ob ich regelmäßig Sport mache. Ich sagte: „Ich gehe täglich Risiken aus dem Weg.“","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"],"jokeQuality":"editorial_checked"},{"id":"joke-046","category":"Witz","title":"Arzt","text":"Arzt: „Sie müssen sich mehr bewegen.“ – „Kann ich die Tabletten nicht einfach weiter weg legen?“","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"],"jokeQuality":"editorial_checked"},{"id":"joke-047","category":"Witz","title":"Arzt","text":"Der Arzt sagte: „Sie brauchen Ruhe.“ Ich bat um ein schriftliches Attest für sämtliche Menschen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"],"jokeQuality":"editorial_checked"},{"id":"joke-048","category":"Witz","title":"Arzt","text":"Beim Arzt stand: „Bitte haben Sie Geduld.“ Schön, wenn die Diagnose schon im Wartezimmer beginnt.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"],"jokeQuality":"editorial_checked"},{"id":"joke-050","category":"Witz","title":"Arzt","text":"Ich fragte den Arzt nach einer zweiten Meinung. Er sagte: „Gut, Ihre Frisur gefällt mir auch nicht.“","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"],"jokeQuality":"editorial_checked"},{"id":"joke-051","category":"Witz","title":"Schwarz","text":"Der Friedhof ist der beliebteste Ort der Stadt. Die Leute sterben darauf, reinzukommen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"],"jokeQuality":"editorial_checked"},{"id":"joke-053","category":"Witz","title":"Schwarz","text":"Auf meinem Grabstein soll stehen: „Bin gleich zurück.“ Nur um langfristig Erwartungen zu enttäuschen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"],"jokeQuality":"editorial_checked"},{"id":"joke-054","category":"Witz","title":"Schwarz","text":"Wenn ich als Geist zurückkomme, erschrecke ich niemanden. Ich mache nur ständig das Druckerpapier leer.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"],"jokeQuality":"editorial_checked"},{"id":"joke-058","category":"Witz","title":"Erwachsen","text":"Früher blieb ich bis drei Uhr wegen Partys wach. Heute, weil ich falsch gelegen habe und mein Rücken Beschwerde einreicht.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"],"jokeQuality":"editorial_checked"},{"id":"joke-063","category":"Witz","title":"Derb","text":"Mein Geduldsfaden ist kein Faden mehr. Das ist inzwischen Zahnseide.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"],"jokeQuality":"editorial_checked"},{"id":"joke-066","category":"Witz","title":"Derb","text":"Wenn Dummheit Strom erzeugen würde, könnten manche Meetings das Gebäude autark versorgen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"],"jokeQuality":"editorial_checked"},{"id":"joke-079","category":"Witz","title":"Britisch trocken","text":"Ich habe meinem Chef gesagt, ich brauche mehr Anerkennung. Er nickte und sagte: „Das stimmt.“","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-080","category":"Witz","title":"Britisch trocken","text":"Wir suchen keine Schuldigen. Wir möchten nur wissen, wer es war.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-081","category":"Witz","title":"Britisch trocken","text":"Das Projekt ist fast fertig. Es fehlen nur noch die Dinge, die funktionieren müssen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-082","category":"Witz","title":"Britisch trocken","text":"Unsere neue Software spart Zeit. Seit der Einführung dokumentieren wir täglich, wie viel.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-083","category":"Witz","title":"Britisch trocken","text":"Ich habe einen Verbesserungsvorschlag eingereicht. Jetzt weiß ich, warum das Formular so gut versteckt war.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-084","category":"Witz","title":"Britisch trocken","text":"Der Termin beginnt pünktlich um neun. Inhaltlich kommt er gegen halb elf dazu.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-085","category":"Witz","title":"Britisch trocken","text":"Wir haben flache Hierarchien. Der Unsinn fällt dadurch schneller nach unten.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-086","category":"Witz","title":"Britisch trocken","text":"Der Plan ist absolut realistisch, sofern nichts Reales passiert.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-087","category":"Witz","title":"Britisch trocken","text":"Mein Chef liebt offene Kommunikation. Deshalb schließt er vorher die Tür.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-088","category":"Witz","title":"Britisch trocken","text":"Das Problem ist gelöst. Wir haben es in „Herausforderung“ umbenannt.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"],"jokeQuality":"editorial_checked"},{"id":"joke-091","category":"Witz","title":"Norddeutsch","text":"„Freust du dich?“ – „Ich beschwer mich nicht.“ Höchste norddeutsche Auszeichnung.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"],"jokeQuality":"editorial_checked"},{"id":"joke-092","category":"Witz","title":"Norddeutsch","text":"Chef sagt, wir müssen flexibel bleiben. Feierabend bleibt vorsichtshalber flexibel nach hinten.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"],"jokeQuality":"editorial_checked"},{"id":"joke-094","category":"Witz","title":"Norddeutsch","text":"„War schlimm?“ – „Ging.“ Das Ereignis kann zwischen leichtem Regen und Weltuntergang gelegen haben.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"],"jokeQuality":"editorial_checked"},{"id":"joke-095","category":"Witz","title":"Norddeutsch","text":"Kollege: „Noch Kaffee?“ – „Jo.“ Damit ist das Motivationsseminar beendet.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"],"jokeQuality":"editorial_checked"},{"id":"joke-098","category":"Witz","title":"Norddeutsch","text":"„Bis morgen.“ – „Wenn's sein muss.“ Kollegiale Zuneigung, norddeutsche Ausgabe.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"],"jokeQuality":"editorial_checked"},{"id":"joke-104","category":"Witz","title":"Arbeit","text":"Der Chef sagt, jeder sei ersetzbar. Ich warte noch auf die praktische Vorführung.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"],"jokeQuality":"editorial_checked"},{"id":"joke-105","category":"Witz","title":"Arbeit","text":"Wenn Erfahrung unbezahlbar ist, müsste mein Konto inzwischen beeindruckender aussehen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"],"jokeQuality":"editorial_checked"},{"id":"joke-111","category":"Witz","title":"Arbeit","text":"Mein Chef sagte: „Denk mit.“ Seitdem denke ich darüber nach, nach Hause zu gehen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"],"jokeQuality":"editorial_checked"},{"id":"joke-115","category":"Witz","title":"Arbeit","text":"Die wichtigste berufliche Fähigkeit ist, beschäftigt auszusehen, während Windows neu startet.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"],"jokeQuality":"editorial_checked"},{"id":"joke-116","category":"Witz","title":"Arbeit","text":"Ich wollte heute nichts aufschieben. Das mache ich morgen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"],"jokeQuality":"editorial_checked"},{"id":"joke-119","category":"Witz","title":"Absurd","text":"Mein Navi sagte „Bitte wenden“. Endlich mal Technik, die meine Lebensentscheidungen kennt.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"],"jokeQuality":"editorial_checked"},{"id":"joke-122","category":"Witz","title":"Absurd","text":"Ich räume nicht auf. Ich verändere die Suchwahrscheinlichkeit von Gegenständen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"],"jokeQuality":"editorial_checked"},{"id":"joke-125","category":"Witz","title":"Absurd","text":"Ich habe einen Kalender gekauft, damit ich genau weiß, an welchem Datum ich Dinge vergesse.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"],"jokeQuality":"editorial_checked"},{"id":"joke-128","category":"Witz","title":"Absurd","text":"Mein Gehirn speichert nachts zuverlässig peinliche Gespräche von 2007, aber keine Passwörter.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"],"jokeQuality":"editorial_checked"},{"id":"joke-129","category":"Witz","title":"Beziehung","text":"Beziehungen sind Teamarbeit. Einer fragt „Wo ist das?“ und der andere findet es an exakt der beschriebenen Stelle.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"],"jokeQuality":"editorial_checked"},{"id":"joke-131","category":"Witz","title":"Beziehung","text":"Liebe ist, wenn man die Decke teilt und morgens feststellt, dass das Konzept gescheitert ist.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"],"jokeQuality":"editorial_checked"},{"id":"joke-132","category":"Witz","title":"Beziehung","text":"Sie fragte, ob mir etwas aufgefallen sei. Ich wusste sofort: Die Prüfung hat begonnen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"],"jokeQuality":"editorial_checked"},{"id":"joke-133","category":"Witz","title":"Beziehung","text":"In Beziehungen gibt es zwei Arten von Menschen: die, die den Thermostat einstellen, und die, die ihn heimlich korrigieren.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"],"jokeQuality":"editorial_checked"},{"id":"joke-135","category":"Witz","title":"Beziehung","text":"Romantik nach Jahren: „Ich hab dein Ladekabel mitgebracht.“","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"],"jokeQuality":"editorial_checked"},{"id":"joke-136","category":"Witz","title":"Beziehung","text":"Ein gemeinsamer Einkauf zeigt, wie unterschiedlich zwei Menschen das Wort „nur“ verstehen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"],"jokeQuality":"editorial_checked"},{"id":"joke-137","category":"Witz","title":"Beziehung","text":"Liebe ist blind. Zusammenleben liefert anschließend die Sehhilfe.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"],"jokeQuality":"editorial_checked"},{"id":"joke-138","category":"Witz","title":"Beziehung","text":"Der Satz „Ist mir egal“ hat in Beziehungen ungefähr zwölf Bedeutungen. Keine davon ist egal.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"],"jokeQuality":"editorial_checked"},{"id":"joke-139","category":"Witz","title":"Arzt","text":"Der Arzt sagte, ich solle mich schonen. Ich wusste, dass irgendwann jemand meine Lebensphilosophie medizinisch bestätigt.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"],"jokeQuality":"editorial_checked"},{"id":"joke-141","category":"Witz","title":"Arzt","text":"Mein Arzt empfiehlt acht Stunden Schlaf. Mein Wecker hat Widerspruch eingelegt.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"],"jokeQuality":"editorial_checked"},{"id":"joke-142","category":"Witz","title":"Arzt","text":"Der Arzt fragte nach meinem Stresslevel. Ich fragte, ob er eine Skala bis Montag hat.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"],"jokeQuality":"editorial_checked"},{"id":"joke-144","category":"Witz","title":"Arzt","text":"Der Arzt sagte, Bewegung sei gesund. Ich bewege seitdem regelmäßig den Termin.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"],"jokeQuality":"editorial_checked"},{"id":"joke-146","category":"Witz","title":"Arzt","text":"Beim Zahnarzt heißt „Sie spüren nur Druck“ offenbar etwas völlig anderes als im Alltag.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"],"jokeQuality":"editorial_checked"},{"id":"joke-147","category":"Witz","title":"Arzt","text":"Der Arzt fragte, ob ich rauche. Ich sagte: „Nur wenn ich brenne.“ Das Formular war danach nicht einfacher.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"],"jokeQuality":"editorial_checked"},{"id":"joke-149","category":"Witz","title":"Schwarz","text":"Ich möchte friedlich im Schlaf sterben wie mein Großvater. Nicht schreiend wie seine Mitfahrer. Ein Klassiker bleibt ein Klassiker.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"],"jokeQuality":"editorial_checked"},{"id":"joke-150","category":"Witz","title":"Schwarz","text":"Mein letzter Wille: Bitte löscht meinen Browserverlauf. Würde und so.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"],"jokeQuality":"editorial_checked"},{"id":"joke-151","category":"Witz","title":"Schwarz","text":"Der Tod kommt sicher. Wenigstens ein Termin ohne Warteschleife.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"],"jokeQuality":"editorial_checked"},{"id":"joke-153","category":"Witz","title":"Schwarz","text":"Auf Beerdigungen merkt man, wie viele Menschen plötzlich sagen: „Wir müssen uns öfter sehen.“ Timing ist alles.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"],"jokeQuality":"editorial_checked"},{"id":"joke-155","category":"Witz","title":"Schwarz","text":"Unsterblichkeit klingt toll, bis man merkt, dass dann auch Montage unendlich oft vorkommen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"],"jokeQuality":"editorial_checked"},{"id":"joke-157","category":"Witz","title":"Schwarz","text":"Wenn das Leben an mir vorbeizieht, hoffe ich, es hat wenigstens den Blinker gesetzt.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"],"jokeQuality":"editorial_checked"},{"id":"joke-162","category":"Witz","title":"Erwachsen","text":"Meine Knie geben inzwischen Wetterberichte heraus, ohne meteorologische Ausbildung.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"],"jokeQuality":"editorial_checked"},{"id":"joke-165","category":"Witz","title":"Erwachsen","text":"Erwachsensein: Man besitzt fünf Ladekabel und nie das richtige.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"],"jokeQuality":"editorial_checked"},{"id":"joke-168","category":"Witz","title":"Erwachsen","text":"Meine Partybeleuchtung ist inzwischen die Lampe im Kühlschrank um 22 Uhr.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"],"jokeQuality":"editorial_checked"},{"id":"joke-170","category":"Witz","title":"Derb","text":"Es gibt Menschen, die bereichern jeden Raum. Besonders beim Verlassen.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"],"jokeQuality":"editorial_checked"},{"id":"joke-171","category":"Witz","title":"Derb","text":"Ich habe nichts gegen dumme Fragen. Nur gegen die überraschend engagierte Serienproduktion.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"],"jokeQuality":"editorial_checked"},{"id":"joke-173","category":"Witz","title":"Derb","text":"Ich kann Kritik gut vertragen. Solange sie falsch ist und von jemand anderem handelt.","source":"Redaktionell geprüft","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"],"jokeQuality":"editorial_checked"},{"id":"animal-new-001","category":"Tier im Fokus","title":"Capybara","text":"Capybaras sind die größten Nagetiere der Welt. Sie leben eng am Wasser, besitzen teilweise Schwimmhäute und können mehrere Minuten unter Wasser bleiben, wenn sie Schutz suchen.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals/capybara","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Capybara"],"topicKey":"animal-capybara"},{"id":"animal-new-002","category":"Tier im Fokus","title":"Tapir","text":"Tapire sind näher mit Pferden und Nashörnern verwandt als mit Schweinen. Ihre verlängerte Nase und Oberlippe bilden einen beweglichen kleinen Rüssel, der auch beim Fressen hilft.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals/tapir","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Tapir"],"topicKey":"animal-tapir"},{"id":"animal-new-003","category":"Tier im Fokus","title":"Kasuar","text":"Kasuare gehören zu den schwersten Vögeln der Welt. Sie können nicht fliegen, besitzen kräftige Beine und einen auffälligen Helm auf dem Kopf.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals/cassowary","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Kasuar"],"topicKey":"animal-kasuar"},{"id":"animal-new-004","category":"Tier im Fokus","title":"Tüpfelhyäne","text":"Tüpfelhyänen sind erfolgreiche Jäger und keineswegs nur Aasfresser. Ihre Kiefer können selbst kräftige Knochen zerbrechen, und ihre Sozialverbände sind komplex organisiert.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Tüpfelhyäne"],"topicKey":"animal-tupfelhyane"},{"id":"animal-new-005","category":"Tier im Fokus","title":"Strauß","text":"Strauße sind die größten lebenden Vögel und können nicht fliegen. Ihre langen Beine machen sie dafür zu sehr schnellen Läufern; ein Ei kann über ein Kilogramm wiegen.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Strauß"],"topicKey":"animal-strau"},{"id":"animal-new-006","category":"Tier im Fokus","title":"Flamingo","text":"Flamingos erhalten ihre rosa Färbung aus Pigmenten in ihrer Nahrung. Junge Tiere sind zunächst eher grau oder weißlich.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Flamingo"],"topicKey":"animal-flamingo"},{"id":"animal-new-007","category":"Tier im Fokus","title":"Stachelschwein","text":"Stachelschweine schießen ihre Stacheln nicht ab. Die Stacheln lösen sich bei Kontakt relativ leicht und dienen als wirksame Verteidigung.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Stachelschwein"],"topicKey":"animal-stachelschwein"},{"id":"animal-new-008","category":"Tier im Fokus","title":"Erdferkel","text":"Erdferkel sind nachtaktive Säugetiere Afrikas und ernähren sich hauptsächlich von Ameisen und Termiten. Mit kräftigen Krallen können sie erstaunlich schnell graben.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Erdferkel"],"topicKey":"animal-erdferkel"},{"id":"animal-new-009","category":"Tier im Fokus","title":"Pangolin","text":"Pangoline sind die einzigen Säugetiere mit großen überlappenden Keratinschuppen. Bei Gefahr rollen sich viele Arten zu einer geschützten Kugel zusammen.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Pangolin"],"topicKey":"animal-pangolin"},{"id":"animal-new-010","category":"Tier im Fokus","title":"Axolotl","text":"Axolotl bleiben ihr Leben lang in einem larvenähnlichen Entwicklungszustand und behalten äußere Kiemen. Besonders faszinierend ist ihre Fähigkeit, verlorene Gliedmaßen und anderes Gewebe zu regenerieren.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Axolotl"],"topicKey":"animal-axolotl"},{"id":"animal-new-011","category":"Tier im Fokus","title":"Schuhschnabel","text":"Schuhschnäbel sind große afrikanische Sumpfvögel mit einem enormen, schuhförmigen Schnabel. Sie können lange nahezu regungslos auf Fische und andere Beute lauern.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Schuhschnabel"],"topicKey":"animal-schuhschnabel"},{"id":"animal-new-012","category":"Tier im Fokus","title":"Mondfisch","text":"Mondfische gehören zu den schwersten Knochenfischen. Ihr Körper wirkt wie abgeschnitten, weil die Schwanzregion stark reduziert ist.","source":"Monterey Bay Aquarium","sourceUrl":"https://www.montereybayaquarium.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Mondfisch"],"topicKey":"animal-mondfisch"},{"id":"animal-new-013","category":"Tier im Fokus","title":"Muräne","text":"Muränen besitzen ein zweites Kieferpaar im Rachen. Dieses sogenannte Schlundkiefer-System hilft dabei, Beute tiefer ins Maul zu ziehen.","source":"Monterey Bay Aquarium","sourceUrl":"https://www.montereybayaquarium.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Muräne"],"topicKey":"animal-murane"},{"id":"animal-new-015","category":"Tier im Fokus","title":"Pfeilschwanzkrebs","text":"Pfeilschwanzkrebse sind näher mit Spinnen als mit echten Krebsen verwandt. Ihre Entwicklungslinie reicht Hunderte Millionen Jahre zurück.","source":"Monterey Bay Aquarium","sourceUrl":"https://www.montereybayaquarium.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Pfeilschwanzkrebs"],"topicKey":"animal-pfeilschwanzkrebs"},{"id":"animal-new-016","category":"Tier im Fokus","title":"Ohrenqualle","text":"Quallen besitzen weder Gehirn noch Herz. Trotzdem reagieren sie auf Licht, Strömung und Berührung über ein einfaches Nervennetz.","source":"Monterey Bay Aquarium","sourceUrl":"https://www.montereybayaquarium.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Ohrenqualle"],"topicKey":"animal-ohrenqualle"},{"id":"animal-new-017","category":"Tier im Fokus","title":"Löwenmähnenqualle","text":"Die Löwenmähnenqualle gehört zu den größten Quallenarten. Ihre langen Tentakel können bei großen Exemplaren viele Meter erreichen.","source":"Monterey Bay Aquarium","sourceUrl":"https://www.montereybayaquarium.org/animals-the-ocean/animals-a-to-z/jellies","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Löwenmähnenqualle"],"topicKey":"animal-lowenmahnenqualle"},{"id":"animal-new-018","category":"Tier im Fokus","title":"Sepia","text":"Sepien können ihre Hautfarbe und Muster in Sekundenbruchteilen verändern. Sie nutzen das für Tarnung, Kommunikation und Jagd.","source":"Monterey Bay Aquarium","sourceUrl":"https://www.montereybayaquarium.org/animals-the-ocean/animals-a-to-z/common-cuttlefish","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Sepia"],"topicKey":"animal-sepia"},{"id":"animal-new-019","category":"Tier im Fokus","title":"Zweipunkt-Oktopus","text":"Der kalifornische Zweipunkt-Oktopus besitzt auffällige blaue Augenflecken, die tatsächliche Augen vortäuschen können. Er jagt unter anderem Muscheln, Schnecken und kleine Fische.","source":"Monterey Bay Aquarium","sourceUrl":"https://www.montereybayaquarium.org/animals-the-ocean/animals-a-to-z/two-spot-octopus","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Zweipunkt-Oktopus"],"topicKey":"animal-zweipunkt-oktopus"},{"id":"animal-new-020","category":"Tier im Fokus","title":"Goliathfrosch","text":"Goliathfrösche sind die größten heute lebenden Frösche. Erwachsene Tiere können mehr als drei Kilogramm wiegen.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Goliathfrosch"],"topicKey":"animal-goliathfrosch"},{"id":"animal-new-021","category":"Tier im Fokus","title":"Zwergseidenäffchen","text":"Zwergseidenäffchen gehören zu den kleinsten Affen der Welt. Sie ernähren sich unter anderem von Baumsäften, die sie mit speziellen Zähnen erschließen.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Zwergseidenäffchen"],"topicKey":"animal-zwergseidenaffchen"},{"id":"animal-new-022","category":"Tier im Fokus","title":"Fossa","text":"Die Fossa ist Madagaskars größtes einheimisches Raubtier und ein hervorragender Kletterer. Sie ist enger mit Mangusten verwandt als mit Katzen.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Fossa"],"topicKey":"animal-fossa"},{"id":"animal-new-023","category":"Tier im Fokus","title":"Saiga","text":"Saiga-Antilopen besitzen eine ungewöhnlich große, flexible Nase. Sie hilft, Staub zu filtern und sehr kalte Winterluft zu erwärmen.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Saiga"],"topicKey":"animal-saiga"},{"id":"animal-new-024","category":"Tier im Fokus","title":"Przewalski-Pferd","text":"Przewalski-Pferde gelten als letzte noch lebende echte Wildpferde. Die Art verschwand zeitweise aus der Wildnis und wurde durch Zuchtprogramme wieder ausgewildert.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Przewalski-Pferd"],"topicKey":"animal-przewalski-pferd"},{"id":"animal-new-025","category":"Tier im Fokus","title":"Riesenotter","text":"Riesenotter leben in südamerikanischen Flüssen in Familiengruppen. Sie kommunizieren mit einer erstaunlich großen Auswahl unterschiedlicher Rufe.","source":"San Diego Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Riesenotter"],"topicKey":"animal-riesenotter"},{"id":"person-new-001","category":"Wer ist eigentlich …?","title":"Margaret E. Knight","text":"US-Erfinderin des 19. Jahrhunderts. Sie entwickelte unter anderem eine Maschine, die Papiertüten mit flachem Boden automatisch herstellen konnte.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Margaret E. Knight"],"topicKey":"person-margaret-e-knight"},{"id":"person-new-002","category":"Wer ist eigentlich …?","title":"Josephine Cochrane","text":"Erfinderin einer frühen praktikablen Geschirrspülmaschine. Sie konstruierte das Gerät im 19. Jahrhundert und zielte zunächst besonders auf Hotels und Restaurants.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Josephine Cochrane"],"topicKey":"person-josephine-cochrane"},{"id":"person-new-003","category":"Wer ist eigentlich …?","title":"Mary Anderson","text":"US-Erfinderin, die 1903 ein handbedientes Scheibenwischer-System patentieren ließ, nachdem sie beobachtet hatte, wie Fahrer bei schlechtem Wetter mit der Sicht kämpften.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Mary Anderson"],"topicKey":"person-mary-anderson"},{"id":"person-new-004","category":"Wer ist eigentlich …?","title":"Lewis Latimer","text":"US-Erfinder und Zeichner, der an elektrischer Beleuchtung und Telefontechnik arbeitete. Er verbesserte unter anderem die Herstellung von Kohlefäden für Glühlampen.","source":"Smithsonian","sourceUrl":"https://www.si.edu/explore/technology","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Lewis Latimer"],"topicKey":"person-lewis-latimer"},{"id":"person-new-005","category":"Wer ist eigentlich …?","title":"Granville T. Woods","text":"US-Erfinder mit zahlreichen Patenten rund um Eisenbahn- und Elektrotechnik. Seine Systeme verbesserten unter anderem Kommunikation und Sicherheit im Bahnverkehr.","source":"Smithsonian","sourceUrl":"https://www.si.edu/explore/technology","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Granville T. Woods"],"topicKey":"person-granville-t-woods"},{"id":"person-new-006","category":"Wer ist eigentlich …?","title":"Otis Boykin","text":"US-Erfinder und Ingenieur, bekannt für verbesserte elektrische Widerstände, die in zahlreichen elektronischen Geräten eingesetzt wurden.","source":"Smithsonian Lemelson Center","sourceUrl":"https://invention.si.edu/invention-stories","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Otis Boykin"],"topicKey":"person-otis-boykin"},{"id":"person-new-007","category":"Wer ist eigentlich …?","title":"Gladys West","text":"US-Mathematikerin, deren Arbeiten an präzisen Erdmodellen und Satellitendaten später wichtige Grundlagen für GPS-Navigation lieferten.","source":"U.S. Air Force","sourceUrl":"https://www.af.mil/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Gladys West"],"topicKey":"person-gladys-west"},{"id":"person-new-008","category":"Wer ist eigentlich …?","title":"Evelyn Berezin","text":"Informatikpionierin, die unter anderem ein frühes computergestütztes Textverarbeitungssystem für Büros entwickelte.","source":"Computer History Museum","sourceUrl":"https://computerhistory.org/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Evelyn Berezin"],"topicKey":"person-evelyn-berezin"},{"id":"person-new-009","category":"Wer ist eigentlich …?","title":"Barbara Liskov","text":"Informatikerin, bekannt für grundlegende Arbeiten zu Programmiersprachen, Datenabstraktion und dem nach ihr benannten Liskovschen Substitutionsprinzip.","source":"ACM","sourceUrl":"https://amturing.acm.org/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Barbara Liskov"],"topicKey":"person-barbara-liskov"},{"id":"person-new-010","category":"Wer ist eigentlich …?","title":"John Bardeen","text":"US-Physiker und bislang der einzige Mensch, der zweimal den Physik-Nobelpreis erhielt: für den Transistor und später für die Theorie der Supraleitung.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","John Bardeen"],"topicKey":"person-john-bardeen"},{"id":"person-new-011","category":"Wer ist eigentlich …?","title":"Claude Shannon","text":"US-Mathematiker und Elektroingenieur. Seine Informationstheorie schuf eine mathematische Grundlage für digitale Kommunikation und Datenübertragung.","source":"MIT","sourceUrl":"https://www.mit.edu/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Claude Shannon"],"topicKey":"person-claude-shannon"},{"id":"person-new-012","category":"Wer ist eigentlich …?","title":"John von Neumann","text":"Mathematiker und Universalgelehrter, der wichtige Beiträge zu Quantenmechanik, Spieltheorie und Computerarchitektur leistete.","source":"Institute for Advanced Study","sourceUrl":"https://www.ias.edu/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","John von Neumann"],"topicKey":"person-john-von-neumann"},{"id":"person-new-013","category":"Wer ist eigentlich …?","title":"Louis Braille","text":"Französischer Pädagoge, der als Jugendlicher das nach ihm benannte Punktschrift-System für blinde Menschen entwickelte.","source":"American Foundation for the Blind","sourceUrl":"https://www.afb.org/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Louis Braille"],"topicKey":"person-louis-braille"},{"id":"person-new-014","category":"Wer ist eigentlich …?","title":"Samuel Morse","text":"US-Künstler und Erfinder, der die elektrische Telegrafie mitentwickelte. Das Morsealphabet machte Nachrichtenübertragung über einfache elektrische Signale praktikabel.","source":"Smithsonian","sourceUrl":"https://www.si.edu/explore/technology","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Samuel Morse"],"topicKey":"person-samuel-morse"},{"id":"person-new-015","category":"Wer ist eigentlich …?","title":"Guglielmo Marconi","text":"Italienischer Funkpionier. Seine Arbeiten trugen entscheidend zur praktischen drahtlosen Telegrafie über große Distanzen bei.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Guglielmo Marconi"],"topicKey":"person-guglielmo-marconi"},{"id":"person-new-016","category":"Wer ist eigentlich …?","title":"Philo Farnsworth","text":"US-Erfinder, der wichtige Beiträge zum vollelektronischen Fernsehen leistete und bereits als Jugendlicher zentrale Ideen dafür entwickelte.","source":"Smithsonian","sourceUrl":"https://www.si.edu/explore/technology","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Philo Farnsworth"],"topicKey":"person-philo-farnsworth"},{"id":"person-new-017","category":"Wer ist eigentlich …?","title":"Vladimir Zworykin","text":"Ingenieur und Fernseh-Pionier, der bei RCA an elektronischen Kameraröhren und Bildröhren arbeitete.","source":"Smithsonian","sourceUrl":"https://www.si.edu/explore/technology","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Vladimir Zworykin"],"topicKey":"person-vladimir-zworykin"},{"id":"person-new-018","category":"Wer ist eigentlich …?","title":"Mary Jackson","text":"Mathematikerin und Ingenieurin bei NACA/NASA. 1958 wurde sie die erste schwarze Ingenieurin der NASA.","source":"NASA","sourceUrl":"https://www.nasa.gov/people/mary-w-jackson-biography/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Mary Jackson"],"topicKey":"person-mary-jackson"},{"id":"person-new-019","category":"Wer ist eigentlich …?","title":"Dorothy Vaughan","text":"Mathematikerin und Programmiererin bei NACA/NASA. Sie leitete die West Area Computing Unit und eignete sich früh FORTRAN-Programmierung an.","source":"NASA","sourceUrl":"https://www.nasa.gov/people/dorothy-vaughan/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Dorothy Vaughan"],"topicKey":"person-dorothy-vaughan"},{"id":"person-new-020","category":"Wer ist eigentlich …?","title":"Annie Easley","text":"Mathematikerin, Informatikerin und Raketenwissenschaftlerin bei NACA/NASA. Sie arbeitete an Software und Energiesystemen.","source":"NASA","sourceUrl":"https://www.nasa.gov/people/annie-easley/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Annie Easley"],"topicKey":"person-annie-easley"},{"id":"person-new-021","category":"Wer ist eigentlich …?","title":"Gertrude B. Elion","text":"US-Biochemikerin und Pharmakologin. Ihre Forschung führte zu mehreren wichtigen Medikamenten gegen Krebs, Infektionen und andere Krankheiten.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Gertrude B. Elion"],"topicKey":"person-gertrude-b-elion"},{"id":"person-new-022","category":"Wer ist eigentlich …?","title":"Rita Levi-Montalcini","text":"Italienische Neurologin, die den Nervenwachstumsfaktor mitentdeckte und dafür 1986 den Medizin-Nobelpreis erhielt.","source":"Nobel Prize","sourceUrl":"https://www.nobelprize.org/prizes/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Rita Levi-Montalcini"],"topicKey":"person-rita-levi-montalcini"},{"id":"person-new-023","category":"Wer ist eigentlich …?","title":"Jane Cooke Wright","text":"US-Onkologin, die wichtige Beiträge zur systematischen Chemotherapie von Krebserkrankungen leistete.","source":"National Library of Medicine","sourceUrl":"https://www.nlm.nih.gov/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Jane Cooke Wright"],"topicKey":"person-jane-cooke-wright"},{"id":"person-new-024","category":"Wer ist eigentlich …?","title":"Alice Ball","text":"US-Chemikerin, die Anfang des 20. Jahrhunderts eine wirksamere injizierbare Form von Chaulmoogra-Öl zur Behandlung von Lepra entwickelte.","source":"University of Hawaii","sourceUrl":"https://www.hawaii.edu/","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Alice Ball"],"topicKey":"person-alice-ball"},{"id":"person-new-025","category":"Wer ist eigentlich …?","title":"Mary Beatrice Davidson Kenner","text":"US-Erfinderin mit mehreren Patenten für Alltags- und Hygieneprodukte, darunter ein verbesserter hygienischer Gürtel für Menstruationsschutz.","source":"Smithsonian","sourceUrl":"https://www.si.edu/explore/technology","verified":true,"tone":"curious","sensitive":false,"tags":["Personen","Mary Beatrice Davidson Kenner"],"topicKey":"person-mary-beatrice-davidson-kenner"},{"id":"origin-extra-002","category":"Wie entstand eigentlich …?","title":"… die Postleitzahl?","text":"Postleitzahlen entstanden, weil wachsende Städte und immer größere Briefmengen eine schnellere organisatorische und später maschinelle Sortierung nötig machten.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… die Postleitzahl?"],"topicKey":"origin-extra-die-postleitzahl"},{"id":"origin-extra-003","category":"Wie entstand eigentlich …?","title":"… das Klebeband?","text":"Klebebänder entwickelten sich aus neuen druckempfindlichen Klebstoffen. Unterschiedliche Varianten entstanden für Verpackung, Lackierarbeiten, Medizin und Haushalt.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… das Klebeband?"],"topicKey":"origin-extra-das-klebeband"},{"id":"origin-extra-004","category":"Wie entstand eigentlich …?","title":"… der Klebestift?","text":"Der Klebestift übertrug das Prinzip eines Lippenstift-Drehmechanismus auf festen Klebstoff. Dadurch wurde Kleben deutlich sauberer und transportabler.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… der Klebestift?"],"topicKey":"origin-extra-der-klebestift"},{"id":"origin-extra-005","category":"Wie entstand eigentlich …?","title":"… die Thermosflasche?","text":"Doppelwandige Vakuumgefäße wurden ursprünglich für wissenschaftliche Zwecke entwickelt. Später erkannte man, wie gut sich damit Getränke warm oder kalt halten lassen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… die Thermosflasche?"],"topicKey":"origin-extra-die-thermosflasche"},{"id":"origin-extra-006","category":"Wie entstand eigentlich …?","title":"… die Sonnenbrille?","text":"Getönte Gläser wurden schon früh gegen Blendung genutzt. Moderne Sonnenbrillen entwickelten sich aber erst mit besserem Wissen über UV-Strahlung und geeignete Filtermaterialien.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… die Sonnenbrille?"],"topicKey":"origin-extra-die-sonnenbrille"},{"id":"origin-extra-007","category":"Wie entstand eigentlich …?","title":"… die Parkuhr?","text":"Parkuhren entstanden in den 1930er-Jahren, weil Städte knappe Parkplätze zeitlich begrenzen und Gebühren direkt am Stellplatz erheben wollten.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… die Parkuhr?"],"topicKey":"origin-extra-die-parkuhr"},{"id":"origin-extra-008","category":"Wie entstand eigentlich …?","title":"… das Rauchmeldegerät?","text":"Kleine Rauchmelder wurden durch kompaktere Sensoren und Batterien für Privathaushalte praktikabel. Sie erkennen Rauchpartikel je nach Bauart optisch oder über Ionisation.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… das Rauchmeldegerät?"],"topicKey":"origin-extra-das-rauchmeldegerat"},{"id":"origin-extra-009","category":"Wie entstand eigentlich …?","title":"… der Warenautomat?","text":"Mechanische Verkaufsautomaten gab es schon im 19. Jahrhundert. Münzprüfer und zuverlässige Mechanik machten später den automatischen Verkauf vieler Produkte möglich.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… der Warenautomat?"],"topicKey":"origin-extra-der-warenautomat"},{"id":"origin-extra-010","category":"Wie entstand eigentlich …?","title":"… das Parkhaus?","text":"Mit wachsendem Autoverkehr wurde innerstädtische Fläche knapp. Mehrstöckige Garagen entstanden, um viele Fahrzeuge auf relativ kleiner Grundfläche unterzubringen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… das Parkhaus?"],"topicKey":"origin-extra-das-parkhaus"},{"id":"origin-extra-011","category":"Wie entstand eigentlich …?","title":"… die Spültoilette?","text":"Spültoiletten gab es in verschiedenen historischen Formen, doch moderne Systeme wurden erst mit zuverlässiger Wasserversorgung, Abwasserkanälen und Geruchsverschlüssen wirklich alltagstauglich.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… die Spültoilette?"],"topicKey":"origin-extra-die-spultoilette"},{"id":"origin-extra-012","category":"Wie entstand eigentlich …?","title":"… das Toilettenpapier?","text":"Papier zur Körperhygiene wurde in China schon früh beschrieben. Industriell hergestelltes Toilettenpapier verbreitete sich viel später, als Papier billig genug für Einwegprodukte wurde.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… das Toilettenpapier?"],"topicKey":"origin-extra-das-toilettenpapier"},{"id":"origin-extra-013","category":"Wie entstand eigentlich …?","title":"… der Locher?","text":"Locher wurden mit wachsender Büroorganisation praktisch, weil Dokumente immer häufiger in Mappen und Ordnern systematisch abgelegt wurden.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… der Locher?"],"topicKey":"origin-extra-der-locher"},{"id":"origin-extra-014","category":"Wie entstand eigentlich …?","title":"… der Aktenordner?","text":"Aktenordner und standardisierte Lochsysteme entstanden aus dem Bedarf, wachsende Papiermengen in Büros schnell abzulegen und wiederzufinden.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… der Aktenordner?"],"topicKey":"origin-extra-der-aktenordner"},{"id":"origin-extra-016","category":"Wie entstand eigentlich …?","title":"… die Taschenlampe?","text":"Kleine tragbare Lampen wurden möglich, als Batterien und Glühlampen kompakt genug wurden, um ohne offene Flamme Licht mitzunehmen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… die Taschenlampe?"],"topicKey":"origin-extra-die-taschenlampe"},{"id":"origin-extra-017","category":"Wie entstand eigentlich …?","title":"… die Türklingel?","text":"Mechanische Klingeln wurden durch elektrische Schaltungen ergänzt. Mit einem einfachen Taster ließ sich nun aus der Ferne ein Signal im Haus auslösen.","source":"Library of Congress / Smithsonian","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Ursprung","… die Türklingel?"],"topicKey":"origin-extra-die-turklingel"},{"id":"science-extra-001","category":"Wusstest du eigentlich …?","title":"Unsere Sonne enthält fast die gesamte Masse des Sonnensystems","text":"Mehr als 99 Prozent der Masse unseres Sonnensystems steckt in der Sonne. Planeten, Monde, Asteroiden und Kometen teilen sich den vergleichsweise kleinen Rest.","source":"NASA","sourceUrl":"https://science.nasa.gov/solar-system/solar-system-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Unsere Sonne enthält fast die gesamte Masse des Sonnensystems"],"topicKey":"science-unsere-sonne-enthalt-fast-die-gesamte-masse-des-sonnensystems"},{"id":"science-extra-002","category":"Wusstest du eigentlich …?","title":"Ein galaktisches Jahr dauert rund 230 Millionen Jahre","text":"Unser Sonnensystem umkreist das Zentrum der Milchstraße. Eine komplette Runde dauert ungefähr 230 Millionen Jahre.","source":"NASA","sourceUrl":"https://science.nasa.gov/solar-system/solar-system-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Ein galaktisches Jahr dauert rund 230 Millionen Jahre"],"topicKey":"science-ein-galaktisches-jahr-dauert-rund-230-millionen-jahre"},{"id":"science-extra-003","category":"Wusstest du eigentlich …?","title":"Venus ist heißer als Merkur","text":"Obwohl Merkur näher an der Sonne liegt, ist Venus der heißeste Planet. Ihre dichte Kohlendioxidatmosphäre erzeugt einen extrem starken Treibhauseffekt.","source":"NASA","sourceUrl":"https://science.nasa.gov/solar-system/solar-system-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Venus ist heißer als Merkur"],"topicKey":"science-venus-ist-hei-er-als-merkur"},{"id":"science-extra-004","category":"Wusstest du eigentlich …?","title":"Merkur und Venus haben keine Monde","text":"Von den acht Planeten besitzen nur Merkur und Venus keine natürlichen Monde.","source":"NASA","sourceUrl":"https://science.nasa.gov/solar-system/solar-system-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Merkur und Venus haben keine Monde"],"topicKey":"science-merkur-und-venus-haben-keine-monde"},{"id":"science-extra-005","category":"Wusstest du eigentlich …?","title":"Pluto hat fünf bekannte Monde","text":"Der Zwergplanet Pluto wird von fünf bekannten Monden begleitet. Charon ist im Verhältnis zu Pluto so groß, dass beide um einen gemeinsamen Punkt außerhalb Plutos kreisen.","source":"NASA","sourceUrl":"https://science.nasa.gov/dwarf-planets/pluto/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Pluto hat fünf bekannte Monde"],"topicKey":"science-pluto-hat-funf-bekannte-monde"},{"id":"science-extra-006","category":"Wusstest du eigentlich …?","title":"Saturns Ringe sind überwiegend Eis","text":"Saturns auffällige Ringe bestehen aus unzähligen Teilchen, größtenteils Wassereis, von Staubkörnern bis zu sehr großen Brocken.","source":"NASA","sourceUrl":"https://science.nasa.gov/saturn/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Saturns Ringe sind überwiegend Eis"],"topicKey":"science-saturns-ringe-sind-uberwiegend-eis"},{"id":"science-extra-007","category":"Wusstest du eigentlich …?","title":"Jupiter hat einen Sturm größer als die Erde","text":"Der Große Rote Fleck auf Jupiter ist ein langlebiger Wirbelsturm. Seine Größe verändert sich, bleibt aber gewaltig.","source":"NASA","sourceUrl":"https://science.nasa.gov/jupiter/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Jupiter hat einen Sturm größer als die Erde"],"topicKey":"science-jupiter-hat-einen-sturm-gro-er-als-die-erde"},{"id":"science-extra-008","category":"Wusstest du eigentlich …?","title":"Mars besitzt den größten bekannten Vulkan des Sonnensystems","text":"Olympus Mons auf dem Mars erhebt sich weit über seine Umgebung und ist deutlich größer als jeder Vulkan auf der Erde.","source":"NASA","sourceUrl":"https://science.nasa.gov/mars/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Mars besitzt den größten bekannten Vulkan des Sonnensystems"],"topicKey":"science-mars-besitzt-den-gro-ten-bekannten-vulkan-des-sonnensystems"},{"id":"science-extra-009","category":"Wusstest du eigentlich …?","title":"Uranus rotiert nahezu auf der Seite","text":"Die Rotationsachse des Uranus ist extrem stark gekippt. Dadurch erlebt der Planet sehr ungewöhnliche Jahreszeiten.","source":"NASA","sourceUrl":"https://science.nasa.gov/uranus/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Uranus rotiert nahezu auf der Seite"],"topicKey":"science-uranus-rotiert-nahezu-auf-der-seite"},{"id":"science-extra-010","category":"Wusstest du eigentlich …?","title":"Neptun wurde mathematisch vorhergesagt","text":"Unregelmäßigkeiten in der Bahn des Uranus führten Mathematiker zu der Vermutung, dass ein weiterer Planet existieren müsse. Kurz darauf wurde Neptun tatsächlich beobachtet.","source":"NASA","sourceUrl":"https://science.nasa.gov/neptune/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Neptun wurde mathematisch vorhergesagt"],"topicKey":"science-neptun-wurde-mathematisch-vorhergesagt"},{"id":"science-extra-011","category":"Wusstest du eigentlich …?","title":"Der Ozean bedeckt rund 70 Prozent der Erde","text":"Die Weltmeere bedecken etwa sieben Zehntel der Erdoberfläche und bilden den größten zusammenhängenden Lebensraum des Planeten.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Der Ozean bedeckt rund 70 Prozent der Erde"],"topicKey":"science-der-ozean-bedeckt-rund-70-prozent-der-erde"},{"id":"science-extra-012","category":"Wusstest du eigentlich …?","title":"Die durchschnittliche Meerestiefe liegt bei mehreren Kilometern","text":"Im Mittel ist der Ozean rund 3,7 Kilometer tief. Viele Bereiche sind deutlich tiefer und bis heute nur grob untersucht.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Die durchschnittliche Meerestiefe liegt bei mehreren Kilometern"],"topicKey":"science-die-durchschnittliche-meerestiefe-liegt-bei-mehreren-kilometern"},{"id":"science-extra-013","category":"Wusstest du eigentlich …?","title":"Abyssale Ebenen sind riesige Tiefsee-Flächen","text":"Weite Bereiche des tiefen Meeresbodens bestehen aus erstaunlich flachen Ebenen, die von feinen Sedimenten bedeckt sind.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Abyssale Ebenen sind riesige Tiefsee-Flächen"],"topicKey":"science-abyssale-ebenen-sind-riesige-tiefsee-flachen"},{"id":"science-extra-014","category":"Wusstest du eigentlich …?","title":"Hydrothermale Quellen können ohne Sonnenlicht Leben ernähren","text":"An manchen Tiefseequellen bilden Mikroorganismen aus chemischer Energie organische Stoffe. Ganze Ökosysteme können davon abhängen.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Hydrothermale Quellen können ohne Sonnenlicht Leben ernähren"],"topicKey":"science-hydrothermale-quellen-konnen-ohne-sonnenlicht-leben-ernahren"},{"id":"science-extra-015","category":"Wusstest du eigentlich …?","title":"Ozeanisches Leben existiert bis in enorme Tiefen","text":"Selbst in tiefsten Meeresgräben wurden Tiere und Mikroorganismen gefunden. Druck und Dunkelheit schließen Leben also keineswegs aus.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Ozeanisches Leben existiert bis in enorme Tiefen"],"topicKey":"science-ozeanisches-leben-existiert-bis-in-enorme-tiefen"},{"id":"science-extra-016","category":"Wusstest du eigentlich …?","title":"Frühe Steinwerkzeuge sind über drei Millionen Jahre alt","text":"Die ältesten bekannten Steinwerkzeuge sind mindestens etwa 3,3 Millionen Jahre alt. Werkzeuggebrauch begann also lange vor dem modernen Menschen.","source":"Smithsonian Human Origins","sourceUrl":"https://www.si.edu/stories/human-origins-facts","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Frühe Steinwerkzeuge sind über drei Millionen Jahre alt"],"topicKey":"science-fruhe-steinwerkzeuge-sind-uber-drei-millionen-jahre-alt"},{"id":"science-extra-017","category":"Wusstest du eigentlich …?","title":"Menschen nutzten Farbpigmente schon vor Hunderttausenden Jahren","text":"Bearbeitete Pigmentstücke zeigen, dass frühe Menschen Farbe lange vor historischen Hochkulturen gezielt nutzten.","source":"Smithsonian Human Origins","sourceUrl":"https://www.si.edu/stories/human-origins-facts","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Menschen nutzten Farbpigmente schon vor Hunderttausenden Jahren"],"topicKey":"science-menschen-nutzten-farbpigmente-schon-vor-hunderttausenden-jahren"},{"id":"science-extra-018","category":"Wusstest du eigentlich …?","title":"Fischfang mit spezialisierten Geräten ist sehr alt","text":"Knochenharpunen und andere spezialisierte Fanggeräte zeigen, dass Menschen schon vor Zehntausenden Jahren gezielt große Fische jagten.","source":"Smithsonian Human Origins","sourceUrl":"https://www.si.edu/stories/human-origins-facts","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Fischfang mit spezialisierten Geräten ist sehr alt"],"topicKey":"science-fischfang-mit-spezialisierten-geraten-ist-sehr-alt"},{"id":"science-extra-019","category":"Wusstest du eigentlich …?","title":"Menschen sind beim Schlucken erstaunlich verletzlich","text":"Durch die Lage unseres Kehlkopfes können Menschen viele Sprachlaute erzeugen. Gleichzeitig kreuzen sich Luft- und Speiseweg so, dass wir uns verschlucken können.","source":"Smithsonian Human Origins","sourceUrl":"https://www.si.edu/stories/human-origins-facts","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Menschen sind beim Schlucken erstaunlich verletzlich"],"topicKey":"science-menschen-sind-beim-schlucken-erstaunlich-verletzlich"},{"id":"science-extra-020","category":"Wusstest du eigentlich …?","title":"Werkzeuge veränderten unseren Speiseplan","text":"Steinwerkzeuge machten es frühen Menschen möglich, Fleisch, Knochenmark und harte Pflanzenbestandteile effizienter zu nutzen.","source":"Smithsonian Human Origins","sourceUrl":"https://www.si.edu/stories/human-origins-facts","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen","Werkzeuge veränderten unseren Speiseplan"],"topicKey":"science-werkzeuge-veranderten-unseren-speiseplan"},{"id":"shortstory-001","category":"Kurze Geschichte","title":"Der Pony Express existierte nur 18 Monate","text":"Der berühmte Pony Express transportierte Post über rund 1.800 Meilen quer durch den Westen der USA, war aber nur von April 1860 bis Oktober 1861 in Betrieb.","source":"National Park Service","sourceUrl":"https://www.nps.gov/poex/learn/historyculture/index.htm","verified":true,"tone":"historical","sensitive":false,"tags":["Kurze Geschichte","Der Pony Express existierte nur 18 Monate"],"topicKey":"story-der-pony-express-existierte-nur-18-monate"},{"id":"shortstory-004","category":"Kurze Geschichte","title":"Frühe Kinotechnik entstand auch aus Bewegungsstudien","text":"Serienfotografien von Bewegungen, etwa galoppierenden Pferden, halfen im 19. Jahrhundert dabei, die technischen Grundlagen bewegter Bilder weiterzuentwickeln.","source":"Smithsonian","sourceUrl":"https://www.si.edu/explore/technology/stories?page=2","verified":true,"tone":"historical","sensitive":false,"tags":["Kurze Geschichte","Frühe Kinotechnik entstand auch aus Bewegungsstudien"],"topicKey":"story-fruhe-kinotechnik-entstand-auch-aus-bewegungsstudien"},{"id":"shortstory-005","category":"Kurze Geschichte","title":"Astronautinnen und Astronauten brauchten für Apollo auch Näherinnen","text":"Weltraumanzüge waren Hochtechnologie aus vielen präzise gefertigten Stofflagen. Erfahrene Näherinnen spielten deshalb eine wichtige Rolle bei der Herstellung der Apollo-Anzüge.","source":"Smithsonian","sourceUrl":"https://www.si.edu/explore/technology/stories?page=1","verified":true,"tone":"historical","sensitive":false,"tags":["Kurze Geschichte","Astronautinnen und Astronauten brauchten für Apollo auch Näherinnen"],"topicKey":"story-astronautinnen-und-astronauten-brauchten-fur-apollo-auch-naherinnen"},{"id":"shortstory-010","category":"Kurze Geschichte","title":"Die Glühlampe war eine Teamgeschichte","text":"Thomas Edison war nicht der einzige Mensch, der an elektrischem Licht arbeitete. Sein Team verbesserte jedoch Materialien, Stromversorgung und ein ganzes Beleuchtungssystem so, dass es praktisch nutzbar wurde.","source":"Smithsonian","sourceUrl":"https://www.si.edu/explore/technology","verified":true,"tone":"historical","sensitive":false,"tags":["Kurze Geschichte","Die Glühlampe war eine Teamgeschichte"],"topicKey":"story-die-gluhlampe-war-eine-teamgeschichte"},{"id":"shortstory-013","category":"Kurze Geschichte","title":"Frühe Computer füllten ganze Räume","text":"Elektronische Computer der 1940er- und 1950er-Jahre benötigten riesige Mengen Bauteile und Energie. Rechenleistung, die heute in Taschen passt, beanspruchte damals ganze Räume.","source":"Smithsonian","sourceUrl":"https://www.si.edu/explore/technology","verified":true,"tone":"historical","sensitive":false,"tags":["Kurze Geschichte","Frühe Computer füllten ganze Räume"],"topicKey":"story-fruhe-computer-fullten-ganze-raume"},{"id":"shortstory-014","category":"Kurze Geschichte","title":"Der 1903 Wright Flyer flog nur Sekunden, veränderte aber die Technikgeschichte","text":"Der erste motorisierte, kontrollierte Flug der Wright-Brüder dauerte nur kurz. Trotzdem bewies er, dass ein steuerbares Motorflugzeug praktisch möglich war.","source":"Smithsonian","sourceUrl":"https://www.si.edu/explore/technology","verified":true,"tone":"historical","sensitive":false,"tags":["Kurze Geschichte","Der 1903 Wright Flyer flog nur Sekunden, veränderte aber die Technikgeschichte"],"topicKey":"story-der-1903-wright-flyer-flog-nur-sekunden-veranderte-aber-die-technikgeschichte"},{"id":"shortstory-015","category":"Kurze Geschichte","title":"Elektrischer Strom machte Städte nachts völlig anders nutzbar","text":"Mit elektrischer Beleuchtung konnten Straßen, Fabriken und Geschäfte länger und verlässlicher betrieben werden. Nacht wurde zunehmend zu einer nutzbaren Wirtschafts- und Freizeitphase.","source":"Smithsonian","sourceUrl":"https://www.si.edu/explore/technology","verified":true,"tone":"historical","sensitive":false,"tags":["Kurze Geschichte","Elektrischer Strom machte Städte nachts völlig anders nutzbar"],"topicKey":"story-elektrischer-strom-machte-stadte-nachts-vollig-anders-nutzbar"},{"id":"kurzgeschichte-krikalev-001","category":"Kurze Geschichte","title":"Der Kosmonaut, dessen Land während seines Fluges verschwand","text":"Sergei Krikalev startete am 18. Mai 1991 mit Sojus TM-12 zur Raumstation Mir, damals noch als Bürger der Sowjetunion. Wegen geänderter Flugpläne erklärte er sich bereit, deutlich länger an Bord zu bleiben. Während seines Aufenthalts scheiterte im August 1991 ein Putsch gegen Michail Gorbatschow, und wenige Monate später zerfiel die Sowjetunion. Als Krikalev am 25. März 1992 zurückkehrte, landete er im inzwischen unabhängigen Kasachstan und war nun russischer Bürger. Insgesamt hatte er bei dieser Mission rund 320 Tage im All verbracht.","source":"NASA / ESA","sourceUrl":"https://www.nasa.gov/history/","verified":true,"tone":"historical","sensitive":false,"tags":["Raumfahrt","Mir","Sowjetunion","Krikalev","1991","1992"],"topicKey":"sergei-krikalev-sowjetunion-zerfall-mir"},{"id":"animal-extra2-001","category":"Tier im Fokus","title":"Sternmull","text":"Der Sternmull besitzt 22 fleischige Fortsätze rund um die Nase. Dieses Tastorgan ist so empfindlich, dass er damit Beute in extrem kurzer Zeit erkennen kann.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Sternmull"],"topicKey":"animal-sternmull"},{"id":"animal-extra2-002","category":"Tier im Fokus","title":"Dikdik","text":"Dikdiks sind winzige afrikanische Antilopen. Viele Arten wiegen nur wenige Kilogramm und leben oft paarweise in festen Revieren.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Dikdik"],"topicKey":"animal-dikdik"},{"id":"animal-extra2-003","category":"Tier im Fokus","title":"Aye-Aye","text":"Das Aye-Aye ist ein nachtaktiver Lemur aus Madagaskar. Mit einem besonders dünnen Mittelfinger klopft es Holz ab und angelt Larven aus Hohlräumen.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Aye-Aye"],"topicKey":"animal-aye-aye"},{"id":"animal-extra2-004","category":"Tier im Fokus","title":"Quokka","text":"Quokkas sind kleine australische Beuteltiere. Sie sind Pflanzenfresser und können in trockenen Zeiten einen großen Teil ihres Wasserbedarfs über Nahrung decken.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Quokka"],"topicKey":"animal-quokka"},{"id":"animal-extra2-005","category":"Tier im Fokus","title":"Baumkänguru","text":"Baumkängurus sind Känguruverwandte, die an ein Leben in Bäumen angepasst sind. Kräftige Vorderbeine und beweglichere Hintergliedmaßen helfen beim Klettern.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Baumkänguru"],"topicKey":"animal-baumkanguru"},{"id":"animal-extra2-006","category":"Tier im Fokus","title":"Tamandua","text":"Tamanduas sind mittelgroße Ameisenbären Mittel- und Südamerikas. Ihr Greifschwanz hilft beim Klettern, und sie können sich gegen Angreifer mit kräftigen Vorderkrallen verteidigen.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Tamandua"],"topicKey":"animal-tamandua"},{"id":"animal-extra2-007","category":"Tier im Fokus","title":"Solenodon","text":"Solenodons sind seltene nachtaktive Säugetiere der Karibik. Sie gehören zu den wenigen Säugetieren, die giftigen Speichel zur Beuteüberwältigung nutzen.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Solenodon"],"topicKey":"animal-solenodon"},{"id":"animal-extra2-008","category":"Tier im Fokus","title":"Nasenaffe","text":"Nasenaffen leben auf Borneo. Die auffällig großen Nasen erwachsener Männchen spielen vermutlich eine Rolle bei Lauterzeugung und Partnerwahl.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Nasenaffe"],"topicKey":"animal-nasenaffe"},{"id":"animal-extra2-009","category":"Tier im Fokus","title":"Gelada","text":"Geladas leben im äthiopischen Hochland und ernähren sich ungewöhnlich stark von Gräsern. Sie verbringen viel Zeit am Boden und bilden große soziale Gruppen.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Gelada"],"topicKey":"animal-gelada"},{"id":"animal-extra2-010","category":"Tier im Fokus","title":"Markhor","text":"Markhore sind Wildziegen Zentralasiens mit auffällig schraubenförmig gedrehten Hörnern. Sie leben in steilen, felsigen Bergregionen.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Markhor"],"topicKey":"animal-markhor"},{"id":"animal-extra2-011","category":"Tier im Fokus","title":"Takin","text":"Takine sind kräftige Huftiere des Himalaya-Raums. Ihr dichtes Fell und eine ölige Hautabsonderung helfen beim Schutz gegen kaltes, nasses Wetter.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Takin"],"topicKey":"animal-takin"},{"id":"animal-extra2-012","category":"Tier im Fokus","title":"Dhole","text":"Dholes sind asiatische Wildhunde, die in Rudeln jagen. Sie kommunizieren mit Pfeiflauten, die über größere Entfernung hörbar sein können.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Dhole"],"topicKey":"animal-dhole"},{"id":"animal-extra2-013","category":"Tier im Fokus","title":"Manati","text":"Manatis sind große pflanzenfressende Meeressäuger. Sie verbringen viele Stunden mit Fressen und besitzen einen überraschend langsamen Stoffwechsel.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Manati"],"topicKey":"animal-manati"},{"id":"animal-extra2-014","category":"Tier im Fokus","title":"Kragenbär","text":"Kragenbären sind asiatische Bären mit heller Brustzeichnung. Sie klettern ausgezeichnet und verbringen je nach Region viel Zeit in Bäumen.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Kragenbär"],"topicKey":"animal-kragenbar"},{"id":"animal-extra2-015","category":"Tier im Fokus","title":"Klippschliefer","text":"Klippschliefer sehen ein wenig wie große Nagetiere aus, sind evolutionär aber näher mit Elefanten und Seekühen verwandt.","source":"San Diego Zoo / Smithsonian National Zoo","sourceUrl":"https://animals.sandiegozoo.org/animals","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Klippschliefer"],"topicKey":"animal-klippschliefer"}]};
